(window.GIM_TS=window.GIM_TS||{})["Zevachim.2"]={"from":48,"a":[["אם \u0003שחט\u0004 את הבהמה \u0003ואחר כך חתך\u0004 את הרגלים — \u0003פסולה,\u0004 שהדם שברגליה, שנפסל במה שהוא חוץ, מתערב עם הדם שהיה בפנים.","ותוהים: \u0003חתך\u0004 רגליה \u0003ואחר כך שחט\u0004 — \u0003כשרה?\u0004 הלוא \u0003בעל מום קא\u0004 \u0005[הוא]\u0006 \u0003מקריב! אלא אימא\u0004 \u0005[אמור]\u0006 כך: שחט כשהיתה הבהמה בפנים, ואז יצאו רגליה לחוץ. ובמקרה זה, אם \u0003[חתך\u0004 את רגליה \u0003ואחר כך קיבל\u0004 את הדם — \u0003כשרה],\u0004 אבל אם \u0003קיבל ואחר כך חתך\u0004 — \u0003פסולה,\u0004 מפני שדם הרגלים כבר התערב בדם האחר.","ותוהים: \u0003חתך\u0004 רגליה \u0003ואחר כך קיבל\u0004 את הדם — \u0003כשרה? והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' זירא\u0004 בשם רבי: \u0003הצורם אזן בבכור ואחר כך קיבל דמו\u0004 — \u0003פסול, שנאמר: \"ולקח מדם\u0004 \u0003הפר\", פר שהיה כבר\u0004 כלומר, שלא נפל בו מום מאז ששחט!","\u0003אמר רב חסדא אמר אבימי:\u0004 אין הכוונה שחותך לגמרי את הרגלים, אלא \u0003חותך באבר\u0004 בבשר \u0003עד שמגיע לעצם,\u0004 ואת העצם אינו חותך, כך שעל ידי חיתוך זה אינה נעשית בעלת מום.","ודנים בדין השני שהובא בענין זה: אם \u0003קיבל\u0004 את דמה של הבהמה שרגליה בחוץ \u0003ואחר כך חתך\u0004 את רגליה — \u0003פסולה,\u0004 כי הדם שקיבל מעורב בדם שברגלי הבהמה. \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 ש\u0003דם המובלע באברים דם הוא\u0004 נחשב, ולכן נפסל ביוצא?","ומשיבים: אין מכאן הוכחה, כי \u0003דלמא\u0004 \u0005[שמא]\u0006 הבהמה נפסלת \u0003משום שמנונית\u0004 שיש בו בדם הרגלים, שמתערבת עם שאר הדם, והיא נחשבת כבשר הקרבן שיצא לחוץ.","ושואלים: \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 לגבי דבר שנדון במקום אחר, ש\u0003בשר קדשים קלים שיצא\u0004 מחוץ לעזרה \u0003לפני\u0004 \u0003זריקת דם\u0004 — הרי הוא \u0003פסול,\u0004 למרות שלאחר זריקת הדם הרי הוא נאכל בכל ירושלים?","ודוחים: לא, \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר כאן \u0003בקדשי קדשים\u0004 שנאכלים בעזרה, ואין בשרם עתיד לצאת משם.","ומציעים: בא ושמע ראיה לענין זה ממה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קדשי קדשים שחיטתן בצפון\u0004 העזרה, \u0003וקבול דמן בכלי שרת\u0004 גם כן \u0003בצפון.\u0004 אם \u0003עמד בדרום והושיט ידו לצפון ושחט\u0004 — \u0003שחיטתו כשרה.\u0004 לעומת זאת אם כשעמד בדרום \u0003קיבל\u0004 בצפון — \u0003קבלתו פסולה,\u0004 אבל אם \u0003הכניס ראשו ורובו\u0004 לצפון וקיבל — \u0003כאילו נכנס כולו.\u0004 שחט בצפון ולאחר השחיטה \u0003פרכסה\u0004 הבהמה \u0003ויצתה לדרום, וחזרה\u0004 לצפון — \u0003כשרה,\u0004 שאין הבהמה נפסלת משום שיצאה לדרום.","\u0003קדשים קלים שחיטתן בפנים\u0004 בתוך העזרה (כולה), \u0003וקיבול דמן בכלי שרת בפנים. עמד בחוץ והכניס ידו לפנים ושחט\u0004 — \u0003שחיטתו כשרה,\u0004 אם \u0003קיבל\u0004 כשהוא עומד בחוץ — \u0003קבלתו פסולה, ו\u0004אולם במקרה זה, שלא כדין צפון בקדשי קדשים, גם אם \u0003הכניס ראשו ורובו\u0004 — \u0003כאילו לא נכנס\u0004 כלל, כמבואר להלן. ועוד הבדל, שהשוחט בהמת קדשים קלים בעזרה, אם לאחר מכן \u0003פרכסה ויצתה לחוץ וחזרה\u0004 — \u0003פסולה.\u0004 וממה שהיא פסולה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בשר קדשים קלים שיצא לפני זריקת\u0004 \u0003דמים\u0004 — \u0003פסולים!\u0004","ודוחים: לא, \u0003דילמא\u0004 \u0005[שמא]\u0006 אין מדובר בבשר שנפסל משום שיצא, אלא דווקא \u0003באליה ויותרת הכבד ושתי כליות,\u0004 שהם אימורים שמוקטרים על גבי המזבח, והם נפסלים ביוצא משום שאינם עתידים לצאת כלל מחוץ לעזרה.","ובעניינים אלו של עבודה בפנים, \u0003בעא מיניה אבוה\u0004 \u0005[שאל אותו אביו]\u0006 של \u0003שמואל משמואל\u0004 כדי לבחון אותו: היתה \u0003היא בפנים ורגליה בחוץ, מהו\u0004 לשוחטה?","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והביאום לה'\"\u0004 (ויקרא יז, ה), לומר \u0003עד שתהא כולה לפנים.\u0004","ועוד שאלו: אם \u0003תלה\u0004 את הבהמה באויר העזרה \u0003ושחט, מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כשרה, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אישתבשת\u0004 \u0005[טעית],\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהא \u0003שחיטה על ירך\u0004 המזבח (ויקרא א, יא), כלומר בצדו וסמוך לו, \u0003וליכא\u0004 \u0005[ואין כאן].\u0006","ועוד שאל: \u0003נתלה\u0004 הכהן בדבר, \u0003ושחט\u0004 כשהוא תלוי באויר, \u0003מהו? אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003פסולה\u0004 היא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו: \u0003אישתבשת\u0004 \u0005[טעית],\u0006 נאמר שתהא \u0003שחיטה על ירך, ולא\u0004 נאמר שיהא ה\u0003שוחט על ירך.\u0004","ועוד שאל: \u0003נתלה\u0004 הכהן \u0003וקבל\u0004 את הדם, \u0003מהו? אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003כשרה, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אישתבשת\u0004 \u0005[טעית],\u0006 \u0003אין דרך שירות בכך.\u0004","ועוד שאל: אם \u0003תלה\u0004 את הבהמה \u0003וקיבל, מהו? אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003פסולה, אמר ליה\u0004 \u0005[לו]\u0006 אביו: \u0003אישתבשת\u0004 \u0005[טעית],\u0006 נאמרה \u0003שחיטה על ירך\u0004 המזבח \u0003ולא\u0004 נאמר שתהא \u0003קבלה על ירך.\u0004","ובסיכום הלכות אלו \u0003אמר אביי: בקדשי קדשים כולן פסולות בר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004אשר מקרה של \u0003נתלה ושחט, בקדשים קלים כולן כשרות בר\u0004 \u0005[חוץ]\u0006 \u0003מן נתלה\u0004 \u0003וקיבל.\u0004","\u0003אמר רבא: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003תלה\u0004 את הבהמה \u0003וקיבל\u0004 דמה \u0003בקדשים קלים\u0004 שהיא \u0003כשרה?\u0004 משום ש\u0003אויר פנים כפנים דמי\u0004 \u0005[נחשב],\u0006 \u0003בקדשי קדשים נמי\u0004 \u0005[גם כן]\u0006 אפשר לומר כי \u0003אויר צפון כצפון דמי\u0004 \u0005[נחשב]!\u0006","\u0003אלא אמר רבא: בין בקדשי קדשים\u0004 \u0003בין בקדשים קלים\u0004 — \u0003כשרות, בר\u0004 \u0005[חוץ]\u0006 \u0003מן תלה ושחט בקדשי קדשים,\u0004 מפני שאינו \"על ירך המזבח\", ופסוק זה נאמר בעולה שהיא קדשי קדשים. וכן \u0003נתלה וקיבל\u0004 פסול, \u0003בין בקדשי קדשים בין בקדשים קלים,\u0004 מפני שאינו דרך שירות.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא:\u0004 \u0003הוא\u0004 הכהן \u0003בפנים וציציתו\u0004 כלומר, חלק משערו \u0003בחוץ\u0004 וקיבל את הדם, \u0003מהו\u0004 הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אמרת\u0004 לגבי הבהמה \u0003\"והביאום לה'\"\u0004 (ויקרא יז, ח), \u0003עד שתבא כולה לפנים?\u0004 \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 לענין הכהנים אתה צריך לפרש: \u0003\"בבואם אל אהל מועד\"\u0004 (שמות כח, מג) — \u0003עד שיבא כולו לאהל מועד\u0004 ולא שיהיה מקצתו בחוץ.","\u0003נתנו\u0004 את הדם \u0003על גבי הכבש\u0004 שעולים בו למזבח, או נתנו על קיר המזבח אבל \u0003שלא כנגד היסוד\u0004 כלומר, באותם מקומות במזבח שלא היה בהם יסוד, או \u0003נתן את\u0004 הדמים \u0003הניתנין למטה למעלה\u0004 כגון דם עולה שצריך ליתנו למטה מחצי המזבח, נתנו למעלה מאמצע המזבח, \u0003ו\u0004כן נתן \u0003את הניתנין למעלה\u0004 כגון דם חטאת — \u0003למטה, ו\u0004נתן \u0003את הניתנין בפנים\u0004 שצריך לתת מדמם על מזבח הזהב בהיכל, או בקדש הקדשים \u0003בחוץ\u0004 במזבח העולה, \u0003ואת הניתנין בחוץ\u0004 נתן \u0003בפנים\u0004 — בכל אלו הרי זה \u0003פסול,\u0004 ו\u0003אין בו\u0004 באכילת הקרבן \u0003כרת,\u0004 כאשר יבואר הענין בגמרא."],["\u0003אמר שמואל:\u0004 מה שנאמר במשנה שאם נזרק הדם שלא במקומו \u0003פסול,\u0004 הכוונה היא שה\u0003בשר\u0004 פסול, \u0003אבל בעלים נתכפרו. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ש\u0003אמר\u0004 \u0003קרא\u0004 \u0005[המקרא]\u0006 לגבי הדם: \u0003\"ואני נתתיו לכם על המזבח לכפר\"\u0004 (ויקרא יז, יא), ומכאן יש ללמוד כי \u0003כיון\u0004 \u0003שהגיע דם למזבח\u0004 בכל מקום \u0003נתכפרו בעלים.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003בשר נמי\u0004 \u0005[גם כן]\u0006 יהיה כשר! \u0005ומשיבים:\u0006 \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 שם: \u0003\"לכפר\",\u0004 והרי זו הדגשה — \u0003לכפרה נתתיו\u0004 שיהא מועיל לזה, \u0003ולא לדבר אחר\u0004 כגון להכשר הבשר.","ומעירים, \u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]:\u0006 דם הניתן \u0003שלא במקומו כ\u0004ניתן ב\u0003מקומו דמי\u0004 \u0005[נחשב].\u0006 ואולם \u0003תנן באידך פירקין\u0004 \u0005[שנינו\u0006 במשנה \u0005בפרקנו האחר]:\u0006 \u0003נתנו על הכבש\u0004 \u0003שלא כנגד היסוד, נתן את הניתנין למטה למעלה ואת הניתנין למעלה\u0004 נתן \u0003למטה,\u0004 או \u0003את הניתנין בפנים\u0004 נתן \u0003בחוץ ואת הניתנין בחוץ\u0004 נתן \u0003בפנים, אם\u0004 \u0003יש\u0004 עדיין \u0003דם הנפש\u0004 בבהמה \u0003—\u0004 \u0003יחזור\u0004 הכהן \u0003הכשר ויקבל\u0004 את הדם ויזרקנו כראוי.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שדם שניתן \u0003שלא במקומו\u0004 נחשב \u0003כ\u0004ניתן ב\u0003מקומו\u0004 ומכפר, אם כן \u0003למה לי\u0004 \u0003יחזור הכשר ויקבל\u0004 ויזרוק את הדם? והרי כבר כיפרה הזריקה הראשונה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שייזרק הדם על מנת \u0003להתיר בשר באכילה, מי איכא\u0004 \u0005[האם יש]\u0006 \u0003זריקה\u0004 ש\u0003לא מכפרת\u0004 כלומר, שאינה באה לכפרה (שהרי כבר היתה כפרה) \u0003ושריא\u0004 \u0005[ו\u0006אינה אלא \u0005מתירה]\u0006 \u0003בשר\u0004 \u0003באכילה?\u0004 אלא, מכאן שהדם שניתן בתחילה שלא במקומו — אינו מכפר.","ומשיבים: \u0003אי דיהביה\u0004 \u0005[אם היה\u0006 מדובר במשנה זו כ\u0005שנתן]\u0006 את הדם כהן \u0003כשר\u0004 שלא במקומו — \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006 היה הדין\u0005],\u0006 שכבר כיפר שלא במקומו, ואינו יכול לחזור ולזרוק, ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במשנה זו, \u0005במה אנו עוסקים]?\u0006 \u0003דיהביה\u0004 \u0005[שנתן אותו]\u0006 \u0003פסול\u0004 שלא במקומו, ולכן לא כיפר מתחילה.","ושואלים: אם כן, מדוע יש אפשרות לתקן על ידי כהן כשר? \u0003וליהוי\u0004 \u0005[ושיהיה]\u0006 הקרבן \u0003דחוי! דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו]:\u0006 \u0003וכולן\u0004 כל הפסולים (כגון מי שאינו כהן) \u0003שקיבלו\u0004 את הדם במחשבת \u0003חוץ לזמנו וחוץ למקומו, אם יש דם הנפש\u0004 — \u0003יחזור הכשר ויקבל.\u0004 וממה שהמשנה משמיעה דין זה דווקא בקבלת הדם נלמד מכאן: דווקא אם \u0003קיבלו\u0004 פסולים — \u0003אין\u0004 \u0005[כן],\u0006 יכול הכשר לחזור ולקבל, אבל אם \u0003זרקו\u0004 כבר פסולים את הדם — \u0003לא, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דהוי\u0004 \u0005[שנעשה]\u0006 הקרבן \u0003דחוי\u0004 כשנזרק דמו על ידי פסולים?","ודוחים: \u0003לא,\u0004 \u0003משום דפסיל\u0004 \u0005[שנפסל]\u0006 \u0003במחשבה,\u0004 שחשבו בו מחשבת פסול בזריקה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 משום פסול מחשבה \u0003קבלה נמי\u0004 \u0005[גם כן]\u0006 תדחה את הקרבן! \u0003ועוד\u0004 יש להקשות: \u0003מי פסלה\u0004 \u0005[האם פוסלת]\u0006 \u0003מחשבה\u0004 בכגון זה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: אין מחשבה מועלת\u0004 (פועלת ומשפיעה) לפסול \u0003אלא במי שראוי לעבודה, ובדבר הראוי לעבודה, ובמקום הראוי לעבודה,\u0004 וכאן מדובר בפסול שזרק את הדם, ואין מחשבתו פוסלת!","ומתרצים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 אל תדייק כמו שאמרנו קודם, שאם \u0003זרקו\u0004 פסולים במחשבה פסולה \u0003לא\u0004 ניתן עוד לקבל את הדם, \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 אם \u0003שחטו\u0004 פסולים במחשבה פסולה \u0003לא\u0004 ניתן עוד לתקן את הקרבן. שכיון ששחיטה כשירה בפסולים, הרי אף מחשבתם מועילה לפגום בה. שלא כמו בקבלה, שאינם כשרים לה ואינם פוסלים בה.","ושואלים: לפי הסבר זה, \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 במה שמדובר במשנה בקבלת הדם דווקא? \u0003דפסלה\u0004 \u0005[שפוסלת]\u0006 \u0003מחשבה\u0004 של פסולים בשחיטה? \u0003תנינא\u0004 \u0005[\u0006הרי \u0005שנינו]\u0006 כבר דבר זה באותה משנה עצמה, שכל הפסולים ששחטו שחיטתם כשרה, \u0003לפיכך הן פוסלין במחשבה\u0004 בשחיטה!","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 דווקא בשחיטה הם פוסלים, אבל \u0003מקבלה ואילך לא פסלה\u0004 \u0005[אין פוסלת]\u0006 \u0003מחשבה\u0004 של פסולים, \u0003מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 \u0003כ\u0004מו שאמר \u0003רבא\u0004 שאם עשה את העבודה מי שאינו ראוי — אינו יכול לפסול במחשבה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: אם כששחט \u0003חישב ליתן את הניתנין למעלה למטה,\u0004 או חישב ליתן את אלה שניתנים \u0003למטה למעלה,\u0004 אם חישב לעשות זאת \u0003לאלתר\u0004 כלומר, בזמן הראוי לזריקה — \u0003כשר,\u0004 שעצם המחשבה לזרוק את הדם שלא במקום הראוי על גבי המזבח — אינה מחשבה הפוסלת \u0003(למחר\u0004 — \u0003פסול).\u0004 ולפיכך, אם כשהמשיך בעבודות \u0003הקרבן\u0004 \u0003חזר וחישב\u0004 באחת מהן להקטיר את האימורים, או לאכול את בשר הקרבן,"],["\u0003חוץ למקומו\u0004 — \u0003פסול ואין בו כרת,\u0004 אם חשב עליו \u0003חוץ לזמנו\u0004 — \u0003פיגול וחייבין עליו כרת.\u0004","אבל אם חשב לזרוק את הניתנים למעלה למטה וכו' \u0003למחר\u0004 — הרי זה \u0003פסול,\u0004 ולפיכך, \u0003חזר וחישב\u0004 עליו \u0003בין חוץ לזמנו בין חוץ למקומו\u0004 — \u0003פסול ואין בו כרת,\u0004 שאין קרבן נעשה פיגול במחשבת חוץ לזמנו, אלא אם לא היה בו פסול אחר.","\u0003ואי\u0004 \u0005[ואם]\u0006 דם שנזרק על המזבח \u0003שלא במקומו כמקומו דמי\u0004 \u0005[נחשב],\u0006 \u0003האי\u0004 \u0005[זה]\u0006 שחשב עליו לזורקו למחר שלא במקומו, \u0003פסול\u0004 בלבד? הלוא \u0003פיגול הוא!\u0004","\u0003אמר מר זוטרא: זריקה דשריא\u0004 \u0005[שמתירה]\u0006 \u0003בשר באכילה מייתא\u0004 \u0005[מביאה]\u0006 \u0003לידי פיגול\u0004 כשחשב לעשותה חוץ לזמנה, \u0003זריקה דלא שריא\u0004 \u0005[שאינה מתירה]\u0006 \u0003בשר באכילה\u0004 אם היה חושב בה מחשבה ראויה — \u0003לא מייתא\u0004 \u0005[אינה מביאה]\u0006 \u0003לידי פיגול.\u0004 ואף שמואל לא אמר שזריקת הדם שלא במקומו מתירה את הבשר, אלא רק מכפרת על הבעלים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי למר זוטרא: מנא\u0004 \u0005[מנין]\u0006 \u0003לך הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 ענה לו: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בענין פיגול \u0003\"ואם האכל יאכל מבשר זבח שלמיו\u0004 ביום השלישי... (כלומר, אם חשב לאוכלו חוץ לזמנו) \u0003פגול יהיה\"\u0004 (ויקרא ז, יח), לומר: \u0003מי שפיגולו\u0004 (מחשבת חוץ לזמנו) בלבד \u0003גרם לו\u0004 להיפסל הוא הפיגול שחייבים עליו כרת, \u0003יצא זה\u0004 שנתכוון לזורקו שלא במקומו, \u0003שאין פיגולו\u0004 (מחשבת חוץ לזמנו) \u0003גרם לו\u0004 להיפסל, \u0003אלא איסור דבר אחר גרם לו,\u0004 ואינו נדון כפיגול.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחוץ למקומו נחשב כמקומו, ואין כאן מחשבת פיגול, \u0003איפסולי נמי לא ליפסל\u0004 \u0005[גם לא ייפסל]\u0006 אם חשב לעשות כן למחר!","\u0003אמר רב נחמן בר יצחק:\u0004 מכל מקום הרי זו מחשבת חוץ לזמנו, ויש בה לפסול את הקרבן. \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 לגבי \u0003מחשבת הינוח, ואליבא\u0004 \u0005[ועל פי\u0006 דעת\u0005]\u0006 \u0003ר' יהודה\u0004 במשנה להלן (זבחים לה,ב) שאם חשב להניח את הדם למחר, ולא לזורקו על המזבח — פסול.","ומביאים דעות נוספות בענין הפסול שבמשנתנו, כשנתן את הדם שלא במקומו. \u0003ריש לקיש אמר: לעולם\u0004 מה ששנינו \u0003\"פסול\"\u0004 כוונתו פסול \u0003ממש,\u0004 לא רק שהבשר פסול, כדברי שמואל, אלא שאינו מכפר. \u0003ו\u0004מצד אחר, לדעת ריש לקיש דם שניתן על המזבח \u0003שלא במקומו כמקומו דמי\u0004 \u0005[נחשב],\u0006 ומכפר. \u0003ו\u0004אף שיש בכך סתירה לכאורה, \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן שנתן\u0004 שלא במקומו \u0003בשתיקה\u0004 — מכפר, \u0003כאן שנתן באמירה\u0004 כלומר, במחשבת אכילה חוץ לזמנו — אינו מכפר.","והגמרא דנה בדבריו בדיוק כפי שדנה בדברי שמואל לעיל, שמקשים ממה ש\u0003תנן\u0004 \u0005[שנינו]:\u0006 \u0003חישב ליתן את הניתנין למטה למעלה, למעלה למטה\u0004 וכו', \u0003עד\u0004 סוף הדיון, שהסביר רב נחמן בר יצחק כי אף שלא כמקומו כמקומו הוא נחשב, מכל מקום כאשר חישב לזרוק שלא במקומו למחר הריהו פסול, \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 ב\u0003מחשבת הינוח ואליבא\u0004 \u0005[ועל פי\u0006 דעת\u0005]\u0006 \u0003ר' יהודה\u0004","\u0003ר' יוחנן אמר: אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר \u0003שנתן בשתיקה\u0004 כלומר, משנתנו פוסלת לגמרי כשנתן שלא במקומו, גם שלא במחשבה פסולה. \u0003ו\u0004טעמו, כי דם שניתן \u0003שלא במקומו לאו\u0004 \u0005[לא]\u0006 \u0003כמקומו דמי\u0004 \u0005[נחשב].\u0006 \u0003ו\u0004מה שנאמר במשנה להלן (זבחים לב,א) שיש אפשרות לחזור ולזרוק כראוי, יש ליישב זאת באופן זה: \u0003הא\u0004 \u0005[זה]\u0006 מדבר \u0003דאיכא\u0004 \u0005[שיש]\u0006 בבהמה \u0003דם הנפש, הא דליכא\u0004 \u0005[זה שאין]\u0006 \u0003דם הנפש.\u0004","ומציעים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 כי דם שניתן שלא במקומו \u0003פסול ואין בו כרת. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ריש לקיש,\u0004 שמפרש את משנתנו כשחושב לעשות זאת שלא בזמנו, ומשום כך פסול הקרבן — \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"פסול ואין בו כרת\",\u0004 להשמיענו שלמרות מחשבה זאת — אין בו כרת,","\u0003אלא לר' יוחנן\u0004 שמפרש את המשנה כשנתן בשתיקה, \u0003מאי\u0004 \u0005[מה\u0006 צורך לומר\u0005]\u0006 \u0003\"אין בו כרת\"\u0004 משום מחשבת חוץ לזמנו? והרי לא משום כך הקרבן פסול! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה].\u0006","ושואלים: \u0003ול\u0004דעת \u0003שמואל מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין בו כרת?\u0004 ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אם נתן במחשבה\u0004 — \u0003פסול ואין בו כרת.\u0004","ושואלים: \u0003ו\u0004לשיטת \u0003ר' יוחנן, אי\u0004 \u0005[אם]\u0006 דם שנזרק \u0003שלא במקומו לאו\u0004 \u0005[לא]\u0006 \u0003כ\u0004נזרק ב\u0003מקומו דמי\u0004 \u0005[נחשב],\u0006 \u0003ליהוי\u0004 \u0005[שיהא\u0006 דינו של הדם\u0005]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 ש\u0003נשפך מן הכלי על הרצפה, ויאספנו\u0004 ויזרקנו כראוי!","ומשיבים: \u0003סבר לה כמאן דאמר\u0004 \u0005[סבור הוא,\u0006 התנא של משנתנו, \u0005כ\u0006דעת \u0005מי שאומר]:\u0006 \u0003לא יאספנו,\u0004 וכפי שאכן \u0003אמר רב יצחק בר יוסף אמר ר' יוחנן: הכל מודים בניתנין למעלה שנתנן למעלה,\u0004 או בניתנין \u0003למטה שנתנן למטה,\u0004 שאם נתנם \u0003שלא כמצותן\u0004 כגון ביד שמאל או במחשבה פסולה — \u0003לא יאספנו. לא נחלקו אלא בניתנין למעלה שנתנן למטה,\u0004 או \u0003למטה שנתנן למעלה, שר' יוסי אומר: לא יאספנו, ור' שמעון אומר: יאספנו.\u0004"],["\u0003ומשנתינו כדברי האומר: לא יאספנו.\u0004","\u0003ורב חסדא אמר\u0004 בשם \u0003אבימי: הכל מודין בניתנין למטה שנתנן למעלה\u0004 — \u0003שלא יאספנו,\u0004 הואיל והגיעו למזבח, וזריקה פסולה היא, \u0003וכל שכן בניתנין למעלה שנתנן למטה, הואיל ו\u0004גם \u0003דמים העליונים\u0004 בסופו של דבר \u0003למטה הן באין\u0004 ונוזלים, \u0003לא נחלקו אלא בניתנין לפנים שנתנן בחוץ,\u0004 או הניתנים \u0003בחוץ שנתנן לפנים, שר' יוסי אומר: יאספנו,\u0004 כאילו נשפכו על הרצפה, \u0003ור' שמעון אומר: לא יאספנו,\u0004 הואיל וניתנו על מקום מתן דמים, וזריקה פסולה היא.","\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כדברי ר' יוחנן, שגם דם הניתן שלא במקומו, שאינו מכפר כלל, המזבח קולטו. שכך שנינו בברייתא, \u0003ר' יהודה אומר:\u0004 אף שקרבנות פסולים שעלו על המזבח לא ירדו, ויישרפו על גביו, מכל מקום בכתוב ממנו למדנו דין זה נאמר: \u0003\"זאת\u0004 תורת העולה \u0003היא העולה\"\u0004 (ויקרא ו, ב) — \u0003הרי אלו\u0004 שלושה \u0003מיעוטין, פרט לנשחטה בלילה, ושנשפך דמה, ושיצא דמה חוץ לקלעים,\u0004 שכל אחת מאלה, גם \u0003אם עלתה\u0004 למזבח — \u0003תרד.\u0004","\u0003ר' שמעון אומר\u0004 כך בדרשת כתוב זה: נאמר \u0003\"עולה\"\u0004 שאם עלתה על המזבח לא תרד, \u0003אין לי אלא עולה כשרה, מנין לרבות\u0004 זו \u0003שנשחטה בלילה, ושנשפך דמה, ושיצא דמה חוץ לקלעים, ו\u0004בשר קרבן \u0003הלן\u0004 מחוץ למזבח, \u0003והיוצא\u0004 חוץ לעזרה, \u0003והטמא, ו\u0004קרבן \u0003שנשחט\u0004 במחשבת \u0003חוץ לזמנו וחוץ למקומו, ושקיבלו פסולין וזרקו את דמה, וה\u0004קרבנות שדמיהם \u0003ניתנין למעלה שנתנן למטה והניתנין למטה שנתנן למעלה, והניתנין בפנים שנתנן בחוץ והניתנין בחוץ שנתנן בפנים, והפסח והחטאת ששחטן שלא לשמן,\u0004 שאם עלו למזבח \u0003מנין\u0004 שלא ירדו?","\u0003תלמוד לומר: \"תורת העולה\"\u0004 — \u0003ריבה תורה אחת לכל העולין, שאם עלו\u0004 על המזבח \u0003לא ירדו.\u0004","\u0003יכול שאני מרבה\u0004 בדין זה \u0003אף הרובע\u0004 אשה, \u0003והנרבע\u0004 לאיש, \u0003והמוקצה\u0004 שהקצוהו וייחדוהו לעבודה זרה, \u0003והנעבד\u0004 בפועל כעבודה זרה, \u0003והאתנן\u0004 של זונה, \u0003והמחיר\u0004 של כלב, \u0003והכלאים, והטריפה, ויוצא דופן? תלמוד לומר: \"זאת\"\u0004 למעט.","ושואלים: \u0003ומה ראית לרבות את אלו ולהוציא את אלו?\u0004 ומסבירים: \u0003מרבה אני את אלו,\u0004 שנשחטה בלילה וכו', \u0003שהיה פסולן בקודש\u0004 שהיו קרבנות כשרים אלא שנפסלו, \u0003ומוציא אני את אלו\u0004 הרובע והנרבע וכו', \u0003שלא היה פסולן בקודש\u0004 שמתחילה לא היו ראויים.","\u0003קתני מיהא\u0004 \u0005[שנינו על כל פנים]:\u0006 \u0003הניתנין למטה שנתנן למעלה ולמעלה שנתנן למטה\u0004 אם עלו לא ירדו, \u0003ולא פליג\u0004 \u0005[חלק]\u0006 \u0003ר' יהודה\u0004 למרות שלדעתו עולה שנשפך דמה תרד, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דקלטיה\u0004 \u0005[שקלט אותו]\u0006 כבר ה\u0003מזבח,\u0004 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שדם כזה, שנזרק שלא במקומו — זריקה פסולה היא, ושוב \u0003לא יאספנו,\u0004 וכדברי ר' יוחנן.","ובענין זה של פסולים שאם עלו למזבח העולה לא ירדו, \u0003אמר ר' אליעזר: מזבח הפנימי\u0004 אף הוא \u0003מקדש פסולין\u0004 שעלו עליו, שכיון שעלו — לא ירדו.","ושואלים: \u0003מאי\u0004 \u0003קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]\u0006? הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 בכלל אלו שאם עלו לא ירדו: \u0003הניתנין בפנים\u0004 שנתנן בחוץ והניתנים בחוץ שנתנן בפנים, משמע שהמזבח הפנימי קולט את הניתנים בחוץ!","ומשיבים: \u0003אי\u0004 \u0003מהתם הוה אמינא\u0004 \u0005[אם משם\u0006 בלבד \u0005הייתי אומר]\u0006 כך: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003ב\u0004\u0003דם\u0004 שצריך היה להינתן בחוץ, וטעם הדבר — משום \u0003דחזי ליה\u0004 \u0005[ש\u0006דם \u0005ראוי לו]\u0006 למזבח הפנימי, שהרי מזים עליו מדם חטאות הפנימיות, כגון פר ושעיר של יום הכיפורים. \u0003אבל קומץ\u0004 מנחה, \u0003דלא חזי ליה\u0004 \u0005[שאין ראוי לו],\u0006 שאין מקריבים על המזבח הפנימי לעולם, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יקדש, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאף זה אם עלה — לא ירד.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003קטרת זרה\u0004 קטורת שאסור להקטירה על מזבח הקטורת \u0003שעלה לגבי מזבח\u0004 — \u0003תרד, שאין לך מקדש פסולין אלא מזבח החיצון בראוי לו.\u0004 ונלמד מכאן ש\u0003חיצון\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מקדש פסולים, \u0003פנימי\u0004 — \u0003לא\u0004 מקדש!","ומשיבים: \u0003תריץ הכי\u0004 \u0005[ישב\u0006 את הברייתא \u0005כך]:\u0006 \u0003קטרת זרה שעלתה למזבח החיצון תרד, שאין מזבח החיצון מקדש פסולין אלא\u0004 בדבר \u0003הראוי לו, והפנימי\u0004 מקדש כל דבר, \u0003בין ראוי לו בין שאין ראוי לו.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003האי\u0004 \u0005[זה]\u0006 המזבח החיצון דינו כדין \u0003רצפה,\u0004 שהרי הוא בנוי כחלק מבנין בית המקדש, \u0003והאי\u0004 \u0005[וזה]\u0006 המזבח הפנימי, הוא \u0003כלי שרת\u0004 וקדושתו מרובה יותר.","\u0003השוחט את הזבח\u0004 על מנת \u0003לזרוק דמו בחוץ או\u0004 על מנת לזרוק \u0003מקצת דמו בחוץ, להקטיר אימוריו בחוץ או מקצת אימוריו בחוץ, לאכול בשרו בחוץ או כזית מבשרו בחוץ, או לאכול כזית מעור האליה\u0004 (זנב הכבש) \u0003בחוץ,\u0004 בכל אחד מהמקרים האלה — \u0003פסול, ואין בו כרת.\u0004","אבל אם התכוון \u0003לזרוק דמו למחר,\u0004 או \u0003מקצת דמו למחר, להקטיר אימוריו למחר או מקצת אימוריו למחר, לאכול בשרו למחר או כזית מבשרו למחר, או לאכול כזית מעור האליה למחר\u0004 — הרי הוא \u0003פיגול ו\u0004האוכלים אותו \u0003חייבין עליו כרת.\u0004","במשנה נזכר כי השוחט את הזבח על מנת לאכול מעור האליה בחוץ — הרי זה פסול, ואם חוץ לזמנו — פיגול. \u0003סברוה\u0004 \u0005[סברו\u0006 הלומדים\u0005]\u0006 ש\u0003עור אליה\u0004"],["\u0003כאליה\u0004 עצמה \u0003דמי\u0004 \u0005[נחשב],\u0006 שבכבש שלמים, שבשרו נאכל ואלייתו מוקטרת עם האימורים, עור האליה מוקטר עמה. \u0003ו\u0004לפי זה, השוחט על מנת לאכול את עור האליה חוץ למקומו או חוץ לזמנו, \u0003הא קא\u0004 \u0005[הריהו]\u0006 \u0003מחשב מאכילת מזבח לאדם\u0004 שהוא שוחט על מנת לאכול דבר שדרכו להקטיר, ומדוע נאמר במשנתנו כי יש לו דין מחשבת פסול?","\u0003אמר שמואל: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כדעת \u0005מי היא]?\u0006 דעת \u0003ר'\u0004 \u0003אליעזר היא,\u0004 ש\u0003אמר: מחשבין מאכילת מזבח לאכילת אדם ומאכילת אדם לאכילת מזבח.\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003השוחט את הזבח\u0004 על מנת \u0003לאכול דבר שאין דרכו לאכול,\u0004 או \u0003להקטיר דבר שאין דרכו להקטיר\u0004 — \u0003כשר, ור' אליעזר\u0004 \u0003פוסל.\u0004","ומקשים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת\u0006 אותה\u0005]\u0006 את משנתנו? \u0003כר' אליעזר. אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה],\u0006 ששנינו במשנה להלן, \u0003זה הכלל: כל השוחט, והמקבל, והמוליך, והזורק, לאכול דבר שדרכו לאכול ולהקטיר דבר שדרכו להקטיר\u0004 חוץ למקומו — פסול וכו', חוץ לזמנו — פיגול.","ומכאן נדייק: לאכול \u0003דבר שדרכו לאכול\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם חישב על מנת לאכול \u0003שאין דרכו לאכול\u0004 אלא להקטיר — \u0003לא, אתאן לרבנן\u0004 \u0005[הגענו\u0006 איפוא \u0005ל\u0006שיטת \u0005חכמים],\u0006 ולפי הסברך נמצא כי \u0003רישא\u0004 \u0005[ההתחלה]\u0006 היא כדעת \u0003ר' אליעזר וסיפא רבנן\u0004 \u0005[ו\u0006ה\u0005סוף\u0006 כדעת \u0005חכמים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 אכן כך צריך לפרש.","\u0003רב הונא אמר: עור אליה לאו\u0004 \u0005[לא]\u0006 \u0003כאליה דמי\u0004 \u0005[נחשב]\u0006 ואינו מוקטר עמה, אלא מן הנאכלים הוא, ומשנתנו כולה לשיטת חכמים היא. \u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב הונא?\u0004 שנאמר: \"והקריב מזבח השלמים אשה לה' \u0003חלבו האליה\"\u0004 (ויקרא ג, ט) — דווקא החלב (השומן) של האליה, \u0003ולא עור האליה.\u0004","\u0003רב חסדא אמר: לעולם עור האליה כאליה דמי\u0004 \u0005[נחשב]\u0006 והוא מוקטר יחד עמה, \u0003והכא במאי עסקינן\u0004 \u0005[וכאן,\u0006 במשנתנו, \u0005במה אנו עוסקים]?\u0006 לא באליה של כבש, אלא \u0003באליה של גדי\u0004 שהיא אינה עולה על המזבח, אלא נאכלת.","ומעירים: \u0003כולהו\u0004 \u0005[כולם],\u0006 רב הונא ורב חסדא, \u0003כ\u0004דעת \u0003שמואל לא אמרי\u0004 \u0005[אינם אומרים],\u0006 כי להעמיד משנה באופן ש\u0003רישא\u0004 \u0005[תחילתה]\u0006 כדעת \u0003ר' אליעזר וסיפא רבנן\u0004 \u0005[וסופה\u0006 כדעת \u0005חכמים]\u0006 \u0003לא מוקמי\u0004 \u0005[אין\u0006 הם \u0005מעמידים].\u0006 וכן שמואל ורב חסדא \u0003כרב הונא לא אמרי\u0004 \u0005[אין אומרים],\u0006 כי \u0003עור אליה כאליה דמי\u0004 \u0005[נחשב]\u0006 \u0003קא משמע להו\u0004 \u0005[נשמע להם].\u0006","ושואלים: שמואל ורב הונא \u0003כ\u0004דעת \u0003רב חסדא מאי טעמא לא אמרי\u0004 \u0005[מה טעם אינם אומרים]\u0006 שמשנתנו עוסקת בעור אליה של גדי? ומשיבים: כי לפי דברי רב חסדא \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 התנא במשנתנו? ש\u0003עור אליה כאליה דמי\u0004 \u0005[נחשב],\u0006 והוא בכלל בשר הנאכל? הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר דבר זה במסכת חולין: \u0003ואלו שעורותיהן\u0004 נחשבים \u0003כבשרן\u0004 לענין טומאה, מתוך שהם רכים וראויים לאכילה, ובתוך אלה מנו \u0003עור שתחת האליה!\u0004","ומשיבים: \u0003ורב חסדא,\u0004 מה הוא אומר? לדעתו \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר גם כאן, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שעור האליה נחשב כאליה, הרי זה \u0003לענין טומאה,\u0004 כיון \u0003דרכיך\u0004 \u0005[ש\u0006הוא \u0005רך]\u0006 וניתן לאכילה הוא \u0003מצטרף, אבל הכא\u0004 \u0005[כאן]\u0006 לענין אכילת קדשים \u0003אימא\u0004 \u0005[אמור],\u0006 כיון שנאמר בקדשים שניתנו לכהנים \u0003\"למשחה\"\u0004 (במדבר יח, ח) וכוונתו \u0003לגדולה,\u0004 שיאכלו אותם \u0003כדרך שהמלכים אוכלין, ולא עבידי\u0004 \u0005[ואין עשויים]\u0006 \u0003מלכים דאכלי הכי\u0004 \u0005[שיאכלו כך]\u0006 את עור האליה, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייכלל בין הקדשים הנאכלים, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם לענין זה נחשב העור כאליה עצמה, והוא קרב על גבי המזבח.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003השוחט את העולה\u0004 (שבשרה מוקטר על המזבח, אבל לא עורה) \u0003להקטיר כזית מעור שתחת\u0004 \u0003האליה, חוץ למקומו\u0004 — הרי הוא \u0003פסול ואין בו כרת, חוץ לזמנו\u0004 — \u0003פיגול וחייבין עליו כרת,\u0004 כי עור זה מוקטר יחד עם הבשר.","\u0003אלעזר בן יהודה איש אבלים אומר משום\u0004 (בשם) \u0003ר' יעקב, וכן היה ר' שמעון בן יהודה איש כפר עיכוס אומר משום ר' שמעון: אחד עור בית הפרסות\u0004 של \u0003בהמה דקה, ואחד עור הראש של עגל הרך, ואחד עור שתחת האליה, ו\u0004כן \u0003כל שמנו חכמים גבי טומאה: \"ואלו שעורותיהן כבשרן\",\u0004 וכוונת הדברים \u0003להביא\u0004 להוסיף על מה שאמרנו גם את \u0003עור של בית הבושת\u0004 (פתח הרחם של נקבה), בכל אלו, אם התכוון לשחוט את הבהמה על מנת להקטירם \u0003חוץ למקומו\u0004 — \u0003פסול ואין בו כרת,\u0004 \u0003חוץ לזמנו\u0004 — \u0003פיגול וחייבין עליו כרת.\u0004","ונדייק: ב\u0003עולה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נאמר דין זה, שעור האליה קרב על גבי המזבח, כיון שכל בשרה עולה למזבח, \u0003אבל זבח\u0004 כגון שלמים, שמקריבים ממנו רק אימורים — \u0003לא.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רב הונא\u0004 הסבור שעור האליה בכבש שלמים אינו מוקטר כאליה \u0003—\u0004 \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003עולה\u0004 דווקא לגבי מחשבת הקטרה, \u0003אלא ל\u0004דעת \u0003רב חסדא\u0004 שעור האליה מוקטר כאליה גם בשלמים, \u0003מאי איריא דתני\u0004 \u0005[מה שייך\u0006 מדוע דווקא \u0005שנה]\u0006 \u0003עולה? ליתני\u0004 \u0005[שישנה]\u0006 בלשון כללית: \u0003זבח!\u0004","ומשיבים: \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רב חסדא: איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 מדובר גם פה, כמו במשנתנו, \u0003באליה של\u0004 \u0003גדי,\u0004 הנאכלת כשאר זבחים, ורק בעולה היא מוקרבת למזבח. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 ותקן בברייתא: לא עולה, אלא \u0003זבח.\u0004","שנינו במשנה שהמתכוון לאכול או לזרוק חוץ למקומו הריהו \u0003פסול ואין בו כרת,\u0004 חוץ לזמנו — פיגול וחייבים עליו כרת. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שיש להבחין בין זה לזה? \u0003אמר שמואל: תרי קראי כתיבי\u0004 \u0005[שני מקראות כתובים].\u0006","ושואלים: \u0003מאי\u0004 \u0003היא\u0004 \u0005[מה הוא\u0006 דבר זה\u0005]?\u0006 \u0003אמר רבה:\u0004 הכוונה היא לשני מקראות המופיעים יחד באותו פסוק, שנאמר: \"ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא ירצה, המקריב אותו לא יחשב לו פגול יהיה, והנפש האוכלת ממנו עונה תשא\" (ויקרא ז, יז), ודייקו חכמים (כמבואר להלן) שאין מדובר באכילה לאחר הזמן, אלא בעושה אחת עבודות הקרבן במחשבה לאכול לאחר זמנו. מה שנאמר: \"ואם האכל יאכל... ביום ה\u0003שלישי\"\u0004 — \u0003זהו\u0004 המחשב לאוכלו \u0003חוץ לזמנו,\u0004 ומה שנאמר בהמשך:","\u0003\"פיגול\u0004 יהיה\" — \u0003זהו\u0004 רמז לפסול אחר, שמחשב לאוכלו \u0003חוץ למקומו.\u0004 ובמה שנאמר שם: \u0003\"והנפש האוכלת ממנו\u0004 עונה תשא\" (כלומר, עונש כרת) יש מיעוט \"ממנו\" — מ\u0003אחד\u0004 מן החטאים הנזכרים \u0003ולא שנים, זהו\u0004 במחשב \u0003חוץ לזמנו,\u0004 שדווקא בו יש עונש כרת, \u0003ולמעוטי\u0004 \u0005[ולמעט]\u0006 \u0003חוץ למקומו.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 להיפך: \u0003\"והנפש האוכלת ממנו\"\u0004 — \u0003זהו חוץ למקומו,\u0004 שהוא בכרת, \u0003ולמעוטי\u0004 \u0005[ולמעט]\u0006 \u0003חוץ לזמנו!\u0004 ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003חוץ\u0004 \u0003לזמנו עדיף,\u0004 ש\u0003פתח ביה\u0004 \u0005[בו]\u0006 הכתוב. ודוחים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003חוץ\u0004 \u0003למקומו עדיף, דסמיך ליה\u0004 \u0005[שסמוך לו]\u0006 לפי דרשה זו של הכתוב!","\u0003אלא אמר אביי: כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק בר אבדימי [אמר רב]:\u0004 כשאמר שמואל ששני מקראות כתובים בענין זה, \u0003סמיך אדתני תנא\u0004 \u0005[סמך\u0006 שמואל \u0005על\u0006 מה \u0005ששנה התנא]:\u0006 \u0003כשהוא אומר \"שלישי\" בפרשת \"קדשים תהיו\"\u0004, שנאמר שם: \"ואם האכל יאכל ביום השלישי פיגול הוא לא ירצה\" (ויקרא יט, ז), \u0003שאין תלמוד לומר\u0004 כלומר, לכאורה אין צורך בכתוב זה, \u0003שהרי כבר נאמר\u0004 קודם: \"\u0003ואם האכל יאכל מבשר זבח השלמים ביום השלישי\"\u0004 (ויקרא ז, יח)."],["אלא \u0003אם אינו ענין לחוץ לזמנו תנהו לענין חוץ למקומו. ו\u0004לענין כרת, \u0003מיעט רחמנא\u0004 \u0005[ומיעטה התורה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003נותר \"ואכליו עונו ישא...\u0004 ונכרתה הנפש ההיא מעמיה\" (ויקרא יט, ח) עליו מדברים בעיקר אותם פסוקים, לומר: רק אוכלו של נותר בכרת, \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חוץ למקומו.\u0004","ומקשים, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003\"ואכליו עונו ישא\" זהו חוץ למקומו,\u0004 האמור לפי דרשה זו בפסוק הסמוך, \u0003ולמעוטי\u0004 \u0005[ולמעט]\u0006 \u0003נותר מכרת!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003נותר הוה ליה\u0004 \u0003לאוקמי\u0004 \u0005[היה לו להעמיד אותו]\u0006 שיהיה \u0003בכרת,\u0004 כדי \u0003למגמר\u0004 \u0005[ללמוד]\u0006 על ידי גזירה שווה של המלים \u0003\"עון\" \"עון\", ל\u0004מחשב \u0003חוץ לזמנו\u0004 שנאמר גם בו לשון עוון (ויקרא ז, יח), שעונשו בכרת, ומדוע? משום \u0003דדמי ליה\u0004 \u0005[שדומה לו]\u0006 דין נותר לדין מחשב חוץ לזמנו \u0003בז\"ב\u0004 (זמן, במה), ששניהם דברים התלויים בזמן, וכן שניהם נוהגים אף בבמה ולא רק במקדש.","ודוחים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003חוץ למקומו הוה ליה לאוקמי\u0004 \u0005[היה לו להעמיד אותו]\u0006 \u0003בכרת,\u0004 וממנו \u0003למגמר\u0004 \u0005[ללמוד]\u0006 בגזירה שווה \u0003\"עון\" \"עון\" לחוץ לזמנו, דדמי ליה\u0004 \u0005[שדומה לו]\u0006 \u0003ב\u0004ארבעה אופנים, שסימנם \u0003מקד\"ש\u0004 שהוא ראשי תיבות: מחשבה, קצת, דם, שלישי. מחשבה — שפוסל קדשים על ידי מחשבה בלבד, קצת — שגם אם חשב על מקצת הקרבן הריהו נפסל כולו בכך, דם — ששניהם פוסלים בעבודת הדם. שלישי — בשניהם מיותר \"ביום השלישי\" לגזירה שווה!","\u0003אלא,\u0004 מכאן יש ללמוד שהפסוק \"ואוכליו עוונו ישא\" מדבר בנותר — ממה ש\u0003אמר ר' יוחנן:\u0004 כך \u0003תני\u0004 \u0005[שנה]\u0006 \u0003זבדי בר לוי, אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה \u0003\"קדש\" \"קדש\", כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \"ואוכליו עוונו ישא כי \u0003את קדש ה' חלל ונכרתה\"\u0004 (ויקרא ז, ח), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ושרפת את הנותר\u0004 \u0003ב\u0004\u0003אש...\u0004 קדש הוא\" (שמות כט, לד), \u0003מה להלן\u0004 בספר שמות מדובר ב\u0003נותר אף כאן\u0004 בפסוק זה מדובר ב\u0003נותר.\u0004","\u0003ו\u0004לפי זה נמצא איפוא כי \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003נותר\u0004 שנאמר בו \u0003\"ואכליו עונו ישא\"\u0004 שרק אוכל נותר בעונש זה, \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חוץ למקומו מכרת.\u0004","ושבים לעיקר הדרשה, ושואלים: \u0003ומאי חזית דקרא אריכא\u0004 \u0005[ומה רואה אתה\u0006 לומר \u0005שהמקרא הארוך]\u0006 האמור בפרשת צו (\"אם האכל יאכל מבשר זבח שלמיו\" וכו'. ויקרא ז, יח) מדבר \u0003בחוץ לזמנו, ו\"שלישי\"\u0004 שנאמר ב\u0003פרשת \"קדשים תהיו\"\u0004 (ויקרא יט, ז) מדבר ב\u0003חוץ למקומו? איפוך אנא\u0004 \u0005[אהפוך אני],\u0006 ואומר שהפסוק הארוך מדבר בחוץ למקומו, והקצר מדבר בחוץ לזמנו!","ומשיבים: \u0003מסתברא, אריכא\u0004 \u0005[מסתבר\u0006 לומר שהמקרא \u0005הארוך]\u0006 מדבר \u0003ב\u0004מחשב \u0003חוץ לזמנו,\u0004 שכך נמצא \u0003דגמר\u0004 \u0005[ש\u0006הוא \u0005לומד]\u0006 דין כרת בגזירה שווה \u0003\"עון\" \"עון\" מנותר, דדמי ליה\u0004 \u0005[שדומה לו]\u0006 \u0003בז\"ב\u0004 בזמן ובבמה.","ודוחים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 את המקרא \u0003אריכא\u0004 \u0005[הארוך]\u0006 נפרש שמדבר \u0003בחוץ למקומו, ו\"שלישי\"\u0004 שב\u0003\"קדשים תהיו\"\u0004 נפרש שמדבר \u0003בחוץ לזמנו,\u0004 שהרי, כאמור, נותר ומחשב חוץ לזמנו יש בהם דמיון רב (מקד\"ש כמבואר לעיל), ו\u0003משום דדמי ליה\u0004 \u0005[שדומה לו]\u0006 \u0003סמכיה וקא ממעט ליה\u0004 \u0005[סמך אותו\u0006 הכתוב אליו \u0005וממעט אותו]\u0006 במלה \"ואוכליו\", לומר שאין בו עונש כרת! ואם כן, לא מצאנו ראיה גמורה לדרשה.","\u0003אלא אמר רבא:\u0004 יש לחזור ולהבין כפי שהוסבר מתחילה, כי דין מחשבת חוץ לזמנו ודין מחשבת חוץ למקומו \u0003כולהו מקרא אריכא אתיין\u0004 \u0005[כולם מן הפסוק הארוך\u0006 בפרשת צו הם \u0005באים].\u0006 ומביאים דרשת כתוב זה לפרטיו. מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"אם \u0003האכל יאכל\"\u0004 (ויקרא ז, יח), וכמבואר להלן עוסק במחשבת חוץ לזמנו, בא ללמדנו ש\u0003בשתי אכילות הכתוב מדבר, אחד אכילת אדם ואחד אכילת מזבח\u0004 (הקטרה), שאם חישב בכל אחת מהן — מפגל.","\u0003\"מבשר זבח שלמיו\"\u0004 בא ללמד: \u0003מה שלמים\u0004 הם דבר שיש בו \u0003מפגלין ומתפגלין,\u0004 גם דם שבעבודתו מפגלים את הבשר, וגם בשר המתפגל בעבודת הדם, \u0003אף כל\u0004 הקרבנות שמתייחס אליהם פסוק זה, הם קרבנות שיש בהם גם \u0003מפגלין ו\u0004גם \u0003מתפגלין.\u0004","\"ביום ה\u0003שלישי\"\u0004 — \u0003זה חוץ לזמנו\u0004 לאחר זמן אכילת שלמים שהוא לשני ימים, ללמד שעל פסול זה מדובר כאן.","ומה שנאמר \u0003\"לא ירצה\"\u0004 מלמד שפסול זה נקבע בשלב בו הקרבן מרצה. ומכאן יש ללמוד \u0003ש\u0004\u0003כהרצאת\u0004 (ריצוי וכפרה של) קרבן \u0003כשר כן הרצאת פסול, ומה הרצאת כשר\u0004 אינה מרצה \u0003עד שיקריבו כל מתיריו,\u0004 וייזרק הדם כראוי, \u0003אף הרצאת פסול\u0004 אינה נקבעת לפיגול \u0003עד שיקריבו כל מתיריו\u0004 וייזרק הדם כראוי.","ומה שנאמר \u0003\"המקריב\"\u0004 — בא לומר שמדובר כאן \u0003ב\u0004דבר שכבר בזמן ה\u0003הקרבה הוא נפסל,\u0004 בגלל המחשבה, \u0003ואינו נפסל ב\u0004יום ה\u0003שלישי\u0004 עצמו. וההדגשה \u0003\"אותו\"\u0004 — באה למעט ולומר כי בפסול \u0003בזבח הכתוב מדבר, ואינו מדבר בכהן\u0004 שלא הכהן הוא הנפסל.","\u0003\"לא יחשב\"\u0004 —"],["— \u0003לא יערב בו מחשבות אחרות,\u0004 כי מחשבה אחרת של פסול מועילה ופוגמת את תוקפה של מחשבת פיגול.","\u0003\"פגול\"\u0004 — \u0003זה\u0004 המחשב מחשבת \u0003חוץ למקומו.\u0004","\u0003\"יהיה\"\u0004 (ולא \"יהיו\") — הרי זה \u0003מלמד שמצטרפין\u0004 חצאי כזית של מחשבת חוץ למקומו וחוץ לזמנו \u0003זה עם זה\u0004 לכדי שיעור שלם לפסול את הקרבן.","\u0003\"והנפש האכלת ממנו\u0004 עוונה תשא\" — \"ממנו\" הרי זה מיעוט, לומר שהעונש האמור ב\"עוונה תשא\" מתייחס לחטא \u0003אחד ולא שנים\u0004 האמורים בפסוק זה, \u0003ואיזה זה?\u0004 שמחשב מחשבת \u0003חוץ לזמנו, דגמר\u0004 \u0005[שלומד]\u0006 שעונש זה כרת הוא בגזירה שווה \u0003\"עון\" \"עון\" מנותר\u0004 (ויקרא יט, ח), משום \u0003דדמי ליה\u0004 \u0005[שדומה לו]\u0006 \u0003בז\"ב,\u0004 כלומר, שהוא פסול התלוי בזמן, וישנו גם בבמה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: לדידך\u0004 \u0005[לשיטתך],\u0006 \u0003\"שלישי\"\u0004 שב\u0003פרשת \"קדשים תהיו\"\u0004 (ויקרא יט, ז) \u0003מאי דרשת ביה\u0004 \u0005[מה אתה דורש בו]?\u0006 השיב לו רבא: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 דבר \u0005נצרך לו]\u0006 שאין מחשבה חוץ למקומו שייכת אלא \u0003למקום שיהא משולש, בדם\u0004 \u0003בבשר ובאימורין,\u0004 שלגבי שלושתם הוא מוגדר כחוץ למקומו.","ומקשים: \u0003תיפוק\u0004 \u0005[תצא]\u0006 \u0003לי\u0004 הלכה זו \u0003מקרא קמא\u0004 \u0005[מן המקרא הראשון]\u0006 \u0003\"אם האכל יאכל\"\u0004 בפרשת צו, \u0003מדאפקיה רחמנא\u0004 \u0005[מפני שהוציא אותו הכתוב]\u0006 \u0003בלשון \"שלישי\"\u0004 (ויקרא ז, יח) שהרי לשיטת רבא משם נלמד גם דין חוץ למקומו!","\u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה\u0006 הזו \u0005לפני]\u0006 \u0003רב מתנה,\u0004 \u0003אמר לי: אי מהתם הוה אמינא\u0004 \u0005[אם משם הייתי אומר]:\u0006 \u0003\"שלישי\"\u0004 — הרי הוא \u0003פרט, \"פגול\"\u0004 — הוא \u0003כלל, ו\u0004לפי כללי מדרש הכתובים, כשיש פרט וכלל \u0003נעשה כלל מוסף על הפרט, ואיתרבו\u0004 \u0005[ויתרבו]\u0006 גם \u0003שאר\u0004 ה\u0003מקומות\u0004 שאינם \"משולשים\", \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שדווקא בזה ולא באחר.","עד כאן שיטות האמוראים בענין זה. ומעתה מביאים דברי התנאים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"ואם האכל יאכל מבשר זבח שלמיו\u0004 ביום השלישי לא ירצה\" (ויקרא ז, יח), \u0003אמר ר' אליעזר: כוף אזנך לשמוע\u0004 מה פירושו האמיתי של הפסוק: \u0003במחשב\u0004 \u0003לאכול מזבחו ביום השלישי הכתוב מדבר.\u0004 ושמא תאמר: \u0003או אינו אלא\u0004 מדבר כמשמעו, \u0003באוכל מזבחו ליום\u0004 ה\u0003שלישי\u0004 שאין הקרבן מרצה? הרי זה בלתי אפשרי, \u0003אמרת: אחר שהוא כשר\u0004 שהיה הקרבן כשר בימים הראשונים, \u0003יחזור ויפסל\u0004 למפרע, אם ייאכל אחר כך ביום השלישי?","\u0003אמר לו ר' עקיבא: הן,\u0004 דבר זה אפשרי, הרי \u0003מצינו בזב וזבה\u0004 שפסקו מזיבתם, \u0003ושומרת יום כנגד יום\u0004 שראתה דם זיבה יום אחד וביום שאחר כך שוב לא ראתה, \u0003שהן בחזקת טהרה\u0004 לאחר שטבלו, \u0003וכיון שראו\u0004 זיבה באותו יום \u0003סתרו\u0004 את מה שהיה קודם לכן, ומה שנגעו בו טמא למפרע כאילו לא טבלו. \u0003אף אתה אל תתמה על זה\u0004 שעבר זמנו, \u0003שאף על פי שהוכשר\u0004 — \u0003שיחזור ויפסל\u0004 למפרע.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אליעזר ראיה נוספת: \u0003הרי הוא אומר\u0004 בפסוק זה \u0003\"המקריב\u0004 אותו לא ירצה\", ללמדנו כי מדובר על דבר שכבר \u0003בשעת הקרבה הוא נפסל ואינו נפסל ב\u0004יום ה\u0003שלישי.\u0004 ושמא תאמר: \u0003או אינו אומר \"המקריב\" אלא זה כהן המקריב,\u0004 שהוא הנפסל על ידי כך? אם כן די היה לכתוב \"המקריב לא ירצה\", \u0003כשהוא אומר \"אתו\"\u0004 משמע ש\u0003בזבח הוא\u0004 \u0003מדבר, ואינו מדבר בכהן.\u0004","\u0003בן עזאי אומר: \"אתו\" מה תלמוד לומר? לפי שנאמר:\u0004 \"כי תדור נדר לה' אלקיך \u0003לא תאחר לשלמו\"\u0004 (דברים כג, כב), \u0003יכול אף מאחר נדרו\u0004 יהיה \u0003בלא ירצה? תלמוד לומר: \"אתו\"\u0004 למעט, \u0003אותו\u0004 האמור כאן הוא \u0003בלא ירצה,\u0004 שאין דמו מכפר, \u0003ואין המאחר נדרו בלא ירצה,\u0004 אלא מביא קרבנו ומתרצה בו.","\u0003אחרים אומרים:\u0004 הראיה שפסוק זה נאמר בפיגול ולא בנותר, היא ממה שנאמר \u0003\"לא יחשב\"\u0004 לומר ש\u0003במחשבה\u0004 לאוכלו לאחר זמנו \u0003הוא נפסל,\u0004 \u0003ואינו נפסל\u0004 באכילתו לאחר זמנו \u0003בשלישי.\u0004","ושואלים: \u0003ובן עזאי,\u0004 שדרש \"אותו\" לענין אחר, מה שלמד ר' אליעזר מ\"אותו\" ש\u0003בזבח הכתוב מדבר ואינו בכהן, מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר \u0003מ\u0004כמו שלמדו אותו \u0003אחרים,\u0004 מ\"לא יחשב\", שאינו נפסל בשלישי, וזה לא ניתן להיאמר אלא על הזבח, ולא על הכהן. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]\u0006 \u0003\"לא ירצו\", ו\"לא ירצה\"\u0004 משמע כי \u0003זיבחא\u0004 \u0005[זבח]\u0006 \u0003הוא,\u0004 ששייכת בו לשון ריצוי, ואינו מדבר בכהן.","ושואלים: \u0003ובן עזאי,\u0004 אותה הלכה ש\u0003אותו בלא ירצה ואין מאחר נדרו בלא ירצה, מהכא נפקא\u0004 \u0005[מכאן\u0006 היא \u0005יוצאת]?\u0006 \u0003מ\u0004דברי \u0003אחרים נפקא\u0004 \u0005[\u0006היא \u0005יוצאת]!\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אחרים אומרים: יכול יהא בכור שעיברה\u0004 (שעברה) \u0003שנתו\u0004 כלומר, שהקריבו אותו לאחר השנה הראשונה לחייו,"],["\u0003כפסולי המוקדשין\u0004 בעלי מומים \u0003ויפסל?\u0004","\u0003תלמוד לומר \"ואכלת לפני ה' אלהיך... מעשר דגנך\u0004 תירושך ויצהרך ובכורות בקרך וצאנך\" (דברים יד, כג), \u0003מקיש בכור למעשר, מה מעשר אינו נפסל משנה\u0004 \u0003לחבירתה, אף בכור אינו נפסל משנה לחבירתה!\u0004","ומשיבים: עדיין \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 גם כתוב זה, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים לגבי \u0003בכור, דלאו בר הרצאה\u0004 \u0005[שלא בן ריצוי]\u0006 \u0003הוא,\u0004 שהרי אינו בא לכפר, \u0003אבל קדשים\u0004 אחרים ש\u0003בני הרצאה נינהו\u0004 \u0005[הם]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא לירצו\u0004 \u0005[ירצו],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא.","ומקשים עוד: \u0003ואכתי מהתם נפקא\u0004 \u0005[ועדיין משם יוצאת\u0006 הלכה זו\u0005]?\u0006 הלוא נאמר: \"כי תדור נדר לא תאחר לשלמו כי דרש ידרשנו ה' אלקיך מעמך \u0003והיה בך חטא\"\u0004 (דברים כג, כב), לומר: בך חטא \u0003ולא בקרבנך חטא!\u0004","ומסבירים: \u0003ובן עזאי, ההוא מבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 ללימוד אחר: \u0003\"והיה בך חטא\"\u0004 להדגיש: \u0003ולא באשתך חטא.\u0004 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ואמר ר' אלעזר\u0004 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003זאת\u0004 \u0003ר' יוחנן: אין אשתו של אדם מתה\u0004 \u0003אלא אם כן מבקשין ממנו ממון\u0004 שנדר \u0003ואין לו, שנאמר: \"אם אין לך לשלם\u0004 \u0003למה יקח משכבך מתחתיך\"\u0004 (משלי כב, כו), אם כן \u0003בהאי עון\u0004 \u0005[בעון זה]\u0006 של \u0003\"בל תאחר\" נמי\u0004 \u0005[גם כן]\u0006 \u0003מתה, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שעל חטא זה אין אשתו נענשת.","בברייתא בעמוד הקודם נאמר, \u0003אחרים אומרים:\u0004 מן המלים \"לא יחשב\" למדים כי \u0003במחשבה הוא נפסל\u0004 הקרבן בפסוק זה, \u0003ואינו נפסל ב\u0004יום ה\u0003שלישי.\u0004 ושואלים: \u0003ור' אליעזר,\u0004 שמוכיח דבר זה באופן אחר, הביטוי \u0003\"לא יחשב\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006","ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו\u0006 הדבר\u0005]\u0006 \u0003לכ\u0004מו שאמר \u0003ר' ינאי,\u0004 ש\u0003אמר\u0004 \u0003ר' ינאי: מנין למחשבות שמוציאות זו מזו,\u0004 ואם חשב גם מחשבת פסול, כגון חוץ למקומו, אין הקרבן נעשה פיגול? \u0003שנאמר: \"לא יחשב\", לא יערב בו מחשבות אחרות.\u0004","\u0003ורב מרי מתני\u0004 \u0005[היה שונה]\u0006 כך, \u0003אמר ר' ינאי: מנין למחשב בקדשים\u0004 מחשבה שאינה ראויה \u0003שהוא לוקה\u0004 כדין העובר על מצות לא תעשה? \u0003תלמוד לומר \"לא יחשב\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב מרי:\u0004 הלוא מחשבת פיגול \u0003לאו שאין בו מעשה\u0004 \u0003הוא, וכל לאו שאין בו מעשה אין לוקין עליו! אמר ליה\u0004 \u0005[לו]:\u0006 שיטת \u0003ר'\u0004 \u0003יהודה היא,\u0004 ש\u0003אמר: לאו שאין בו מעשה\u0004 גם כן \u0003לוקין עליו.\u0004","\u0003זה הכלל: כל השוחט, ו\u0004כן \u0003המקבל, והמהלך, והזורק\u0004 על מנת \u0003לאכול דבר שדרכו לאכול\u0004 (בשר הקרבן, הנאכל לבעלים או לכהנים), \u0003ולהקטיר דבר שדרכו להקטיר\u0004 על גבי המזבח, כגון האימורים, בשיעור \u0003כזית,\u0004 אם על מנת לעשות זאת \u0003חוץ למקומו\u0004 — הרי זה \u0003פסול ואין בו כרת,\u0004 אם לעשות זאת \u0003חוץ לזמנו\u0004 — \u0003פגול וחייבין עליו כרת, ובלבד שיקריב\u0004 את \u0003המתיר\u0004 של הקרבן כלומר, את הדם, \u0003כמצותו.\u0004","\u0003כיצד\u0004 נחשב ש\u0003קרב\u0004 \u0003המתיר כמצותו?\u0004 \u0003שחט בשתיקה\u0004 (בסתם) \u0003קבל\u0004 את הדם \u0003והלך וזרק\u0004 במחשבה \u0003חוץ לזמנו, או ששחט\u0004 במחשבה \u0003חוץ לזמנו וקבל והלך וזרק בשתיקה, או ששחט וקבל והלך וזרק חוץ לזמנו\u0004 — \u0003זהו שמקריב\u0004 את \u0003המתיר כמצותו,\u0004 שהרי חוץ מן המחשבה של חוץ לזמנו נעשתה עבודת המתיר בכשרות.","\u0003כיצד לא קרב המתיר כמצותו?\u0004 כאשר בנוסף למחשבת חוץ לזמנו, היתה מחשבה אחרת הפוסלת את הקרבן, כאשר \u0003שחט\u0004 במחשבה \u0003חוץ למקומו, קבל והלך\u0004 או הלך \u0003וזרק\u0004 במחשבה \u0003חוץ לזמנו. או ששחט\u0004 במחשבה \u0003חוץ לזמנו קבל והלך וזרק חוץ\u0004 \u0003למקומו, או ששחט וקבל והלך וזרק חוץ למקומו,\u0004 וכן","\u0003הפסח והחטאת ששחטן שלא לשמן\u0004 (ונפסלו על ידי כך, כמבואר בראש המסכת) \u0003וקבל והלך וזרק חוץ לזמנו, או ששחט\u0004 במחשבת \u0003חוץ לזמנו קיבל והלך וזרק\u0004 (או הלך) \u0003שלא לשמן, או ששחט וקבל והלך וזרק דמן\u0004 \u0003שלא לשמן\u0004 — \u0003זהו שלא קרב המתיר כמצותו.\u0004","אם עשה אחת מן העבודות על מנת \u0003לאכול כזית\u0004 (שהוא שיעור האכילה הקטן ביותר) \u0003בחוץ\u0004 ו\u0003כזית למחר, כזית למחר\u0004 ו\u0003כזית בחוץ,\u0004 ואפילו אם שחט על מנת לאכול \u0003כחצי זית בחוץ\u0004 ו\u0003כחצי זית למחר, כחצי זית למחר\u0004 ו\u0003כחצי זית בחוץ,\u0004 למרות שאין שיעור אכילה בכל אחת מן המחשבות הפסולות — בכל המקרים הללו \u0003פסול ואין בו כרת.\u0004","על כל ההלכות האמורות במשנה, \u0003אמר ר' יהודה:\u0004 אינו כן, אלא \u0003זה הכלל: כל שמחשבת הזמן\u0004 שהוא חושב לאכול או להקריב שלא בזמנו \u0003קדמה למחשבת המקום\u0004 — הרי הוא \u0003פגול וחייבין עליו כרת,\u0004 \u0003ו\u0004רק \u0003אם מחשבת המקום קדמה למחשבת הזמן\u0004 — \u0003פסול\u0004 \u0003ואין בו כרת. וחכמים אומרים: זה וזה\u0004 כל שהיתה מחשבה פוסלת אחרת — \u0003פסול ואין בו כרת.\u0004 וכל זה שחשב שתי מחשבות שונות באכילה. אבל אם עשה אחת מן העבודות על מנת \u0003לאכול כחצי זית\u0004 ו\u0003להקטיר כחצי כזית\u0004 שלא בזמנו או לא במקומו — \u0003כשר,\u0004 משום \u0003שאין אכילה והקטרה מצטרפין.\u0004","על המחלוקת בסופה של המשנה, שלדעת ר' יהודה אם הקדים מחשבת הזמן למחשבת המקום הרי זה פיגול, ולדעת חכמים בכל מקרה הרי זה פסול בלבד, \u0003אמר אילפא: מחלוקת\u0004 זו \u0003בשתי עבודות\u0004 שונות, כשבעבודה הראשונה חושב מחשבת חוץ לזמנו ובשניה מחשבת חוץ למקומו, \u0003אבל בעבודה אחת\u0004 — \u0003דברי הכל עירוב מחשבות הוי\u0004 \u0005[הוא],\u0006 ואף לדעת ר' יהודה אין כאן עבודה במחשבת פיגול. \u0003ור' יוחנן אמר: אף בעבודה אחת מחלוקת,\u0004 שלדעת ר' יהודה בכל מקרה הולכים אחר המחשבה הראשונה.","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אילפא מדרישא\u0004 \u0005[מכיון שראשה\u0006 של המשנה\u0005]\u0006 מדבר \u0003בשתי עבודות\u0004 שונות, כפי ששנינו: שחט בשתיקה, קיבל וכו' חוץ לזמנו — \u0003סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 \u0003בשתי עבודות. אלא ל\u0004דעת \u0003ר' יוחנן, רישא\u0004 \u0005[ראשה]\u0006 \u0003בשתי עבודות וסיפא\u0004 \u0005[וסופה]\u0006 \u0003בעבודה אחת?\u0004"],["ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003רישא\u0004 \u0005[ראשה]\u0006 \u0003בשתי עבודות\u0004 כפי שנתפרש בה, \u0003סיפא\u0004 \u0005[סופה]\u0006 שנחלקו בסתם — \u0003בין בעבודה אחת בין בשתי עבודות.\u0004","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אמר ר' יהודה, זה הכלל: אם מחשבת הזמן קדמה למחשבת המקום\u0004 — \u0003פיגול וחייבין עליו כרת.\u0004 ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' יוחנן, היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 בלשון \u0003\"זה הכלל\",\u0004 שבא לכלול כל המקרים, בין בשתי עבודות בין בעבודה אחת. \u0003אלא לאילפא מאי\u0004 \u0005[מה]\u0006 משמעות ההדגשה \u0003\"זה הכלל\"?\u0004 מה היא באה להוסיף? ואומרים: אכן לשיטתו \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","ומביאים דיון על משנה במסכת תמורה, הנוגע למשנתנו. \u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 אמר על בהמה: \u0003\"הרי זו תמורת עולה תמורת שלמים\"\u0004 — \u0003הרי זו\u0004 נעשית \u0003תמורת עולה,\u0004 שכיון שאמר \"תמורת עולה\" חלה עליה קדושת עולה ואינה יכולה להיעשות שלמים, \u0003דברי ר' מאיר.\u0004","\u0003אמר ר' יוסי: אם לכך נתכוון תחילה,\u0004 שתהיה גם תמורת עולה וגם תמורת שלמים, \u0003הואיל ואי אפשר להוציא שתי שמות כאחת\u0004 ובהכרח חייב לומר דבר אחד קודם \u0003—\u0004 \u0003דבריו קיימין,\u0004 ונעשית תמורת עולה ושלמים יחד, \u0003ו\u0004רק \u0003אם משאמר \"הרי זו תמורת עולה\"\u0004 חזר \u0003ונמלך\u0004 (התחרט) \u0003ואמר \"הרי זו תמורת שלמים\"\u0004 — במקרה זה \u0003הרי זו עולה.\u0004","\u0003איבעיא\u0004 \u0003להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 אם אמר את שני הדברים בדיבור אחד: \u0003\"הרי זו תמורת עולה ושלמים\", מהו?\u0004 או אם אמר \u0003\"לחצות\"\u0004 כלומר, שפירש שתחול קדושה למחצה, אלא שהזכיר תחילה עולה, \u0003מהו?\u0004","\u0003אמר אביי: בהא\u0004 \u0005[בזו]\u0006 \u0003ודאי מודה ר' מאיר\u0004 שחלות שתי הקדושות, ואין היא תמורת עולה בלבד. \u0003רבא אמר: עדיין היא מחלוקת\u0004 אפילו בזו, שהואיל והזכיר בתחילה עולה, חלה קדושת עולה על הבהמה כולה.","\u0003אמר רבא לאביי, לדידך דאמרת בהא\u0004 \u0005[לשיטתך שאתה אומר שבזו]\u0006 \u0003ודאי מודה ר' מאיר,\u0004 יש להקשות ממשנתנו, ש\u0003הרי שחיטה\u0004 ששוחט לאכול כזית למחר כזית בחוץ, \u0003דלכי\u0004 \u0005[שכמו]\u0006 \u0003\"לחצות\"\u0004 היא \u0003דמי\u0004 \u0005[נחשבת],\u0006 שהרי השחיטה מעשה אחד הוא, כמו שממיר בלשון \"לחצות\", שכוונתו להחיל את שתי הקדושות כאחת, \u0003ופליגי\u0004 \u0005[וחלוקים\u0006 בה\u0005],\u0006 שר' יהודה סבור כי הולכים רק אחר דבריו הראשונים, והוא פיגול!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003אינה לשחיטה אלא לבסוף,\u0004 שמעשה השחיטה חל כאחת ברגע האחרון? לא, באמת \u0003ישנה לשחיטה מתחילה ועד סוף,\u0004 שאנו רואים את כל השחיטה כמעשה שיש בו שלבים שונים, \u0003ומשנתינו\u0004 מדברת ש\u0003אמר: סימן ראשון\u0004 (קנה הנשימה) אני שוחט במחשבה לאכול \u0003חוץ לזמנו, סימן שני\u0004 (הושט) במחשבה לאכול \u0003חוץ למקומו.\u0004","ומקשים: \u0003הרי קמיצה\u0004 של קומץ המנחה \u0003דלכי\u0004 \u0005[שכמו]\u0006 \u0003לחצות\u0004 הוא \u0003דמי\u0004 \u0005[נחשב],\u0006 שאין היא אלא פעולה אחת בלבד, \u0003ופליגי\u0004 \u0005[וחלוקים\u0006 בכך\u0005]\u0006 ר' יהודה וחכמים במסכת מנחות כשאמר \"על מנת לאכול כזית למחר כזית בחוץ\"!","ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 הואיל ולא נאמרו הדברים במפורש, יש לומר שאינם חולקים במחשב כן בקמיצה, אלא בהקטרה של שני מתירי המנחה, הקומץ והלבונה, ובאופן \u0003שהקטיר קומץ מנחה\u0004 במחשבת \u0003חוץ לזמנו, קומץ לבונה\u0004 במחשבת \u0003חוץ למקומו.\u0004","ומקשים: \u0003הרי קומץ\u0004 של \u0003מנחת חוטא, דליכא\u0004 \u0005[שאין]\u0006 \u0003לבונה\u0004 \u0003בהדיה\u0004 \u0005[יחד איתה],\u0006 שאין במנחת חוטא לבונה, \u0003ופליגי\u0004 \u0005[וחלוקים\u0006 בכך\u0005],\u0006 שהרי לא חילקה שם המשנה בין מנחה למנחה!","ענה לו: באמת \u0003לא פליגי\u0004 \u0005[אין חלוקים]\u0006 בזה. \u0003אמר רב אשי: אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר פליגי\u0004 \u0005[\u0006ש\u0005חולקים\u0006 בכך\u0005],\u0006 אפשר לומר ש\u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 \u0003בפסיעות,\u0004 כשחישב כן בעבודת ההולכה של הקומץ למזבח, שבפסיעה אחת שהלך למזבח חושב מחשבה אחת, ופסיעה שניה במחשבה האחרת, ואין זה דומה ל\"לחצות\", שם חלים דבריו כאחת.","\u0003רב שימי\u0004 \u0003בר אשי מתני\u0004 \u0005[היה שונה]\u0006 \u0003כ\u0004דברי \u0003אביי,\u0004 שבדיבור אחד ממש, כגון לחצות, לא חלק ר' מאיר, ושתי הקדושות חלות על הבהמה. \u0003רב הונא בר נתן מתני\u0004 \u0005[היה שונה]\u0006 \u0003כ\u0004דברי \u0003רבא,\u0004 שגם במקרה כזה ר' מאיר חולק.","ובהמשך לענין זה מסופר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: ר' מאיר\u0004 שאמר: \"תמורת עולה ותמורת שלמים\" — תמורת עולה היא, \u0003בשיטת ר' יהודה אמרה,\u0004 ש\u0003אמר: תפוס לשון ראשון,\u0004 ומה היא שיטת ר' יהודה?","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אמר ר' יהודה, זה הכלל: אם מחשבת\u0004 \u0003הזמן קדמה את מחשבת המקום\u0004 — \u0003פיגול, וחייבין עליו כרת.\u0004"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב דימי: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר בר חנה אמר\u0004 בשם \u0003ר' יוחנן: כי מגעת להו\u0004 \u0005[כאשר אתה מקרב אותם]\u0006 את דבריהם, יכול אתה לומר כי \u0003ר' מאיר ור' יוסי\u0004 החלוק עליו במשנה בענין תמורה \u0003בהדי הדדי לא פליגי\u0004 \u0005[אינם חולקים זה עם זה],\u0006 ששניהם אינם אומרים \"תפוס לשון ראשון\", כאשר יבואר להלן. ואם כן, ר' מאיר אינו בשיטת ר' יהודה!","על כך תמה רב דימי: \u0003ולא פליגי\u0004 \u0005[ו\u0006כי \u0005אינם חולקים]?\u0006 \u0003והא מיפלג פליגי\u0004 \u0005[והרי חלוקים\u0006 הם\u0005]\u0006 כאמור במשנה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פליגי במאי\u0004 \u0003דפליגי\u0004 \u0005[חלוקים\u0006 הם \u0005במה ש\u0006הם \u0005חלוקים],\u0006 במקרה זה, \u0003ולא פליגי במאי דלא פליגי\u0004 \u0005[ואינם חלוקים במה שאינם חלוקים]\u0006 כלומר, יש להבין את מחלוקתם באופן שונה.","וכפי ש\u0003אמר ר' יצחק בר יוסף אמר ר' יוחנן: הכל,\u0004 גם ר' מאיר וגם ר' יוסי, \u0003מודים היכא דאמר\u0004 \u0005[במקום שאומר]\u0006 \u0003\"תחול זו ואחר כך תחול זו\",\u0004 תמורת עולה ואחר כך תמורת שלמים — \u0003דברי הכל\u0004 קדושת שלמים \u0003לא חיילא\u0004 \u0005[אינה חלה],\u0006 וגם לא לדעת ר' יוסי, לפי שכבר חלה עליה קדושת עולה. וכן מצד אחר, אם אומר \u0003\"לא תחול זו אלא אם כן חלה זו\"\u0004 — ל\u0003דברי הכל,\u0004 וגם לדעת ר' מאיר, \u0003חיילא\u0004 \u0005[חלה]\u0006 גם קדושת שלמים.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה במקרה המסויים \u0003דאמר\u0004 \u0005[שאומר]\u0006 \u0003\"תמורת עולה תמורת שלמים\", ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003מדהוה ליה למימר\u0004 \u0005[מ\u0006כיון \u0005ש\u0006אם היה רוצה להחיל את שתי הקדושות \u0005היה לו לומר]\u0006 \u0003\"תמורת עולה ושלמים\", ואמר\u0004 במקום זה \u0003\"תמורת עולה תמורת שלמים\"\u0004 — \u0003שמע מינה מיהדר קא הדר ביה\u0004 \u0005[למד מכאן\u0006 ש\u0005הוא חוזר בו],\u0006 שהתכוון מתחילה רק לתמורת עולה בלבד, ואחר כך התחרט ורצה להחיל עליה קדושת שלמים, וזה אינו יכול לעשות עוד.","\u0003ור' יוסי\u0004 משיב על כך: \u0003אי אמר\u0004 \u0005[אם היה אומר]\u0006 \u0003\"תמורת עולה ושלמים\", הוה אמינא\u0004 \u0005[הייתי אומר,\u0006 מפרש\u0005]\u0006 את דבריו כך: \u0003פלגא\u0004 \u0005[חצי\u0006 בהמה\u0005]\u0006 הוא \u0003תמורת עולה ופלגא\u0004 \u0005[וחצי]\u0006 \u0003תמורת שלמים\u0004 — \u0003להכי\u0004 \u0005[משום כך]\u0006 \u0003אמר \"תמורת\u0004 \u0003עולה תמורת שלמים\", למימרא\u0004 \u0005[לומר]\u0006 ש\u0003כולה עולה וכולה שלמים הויא\u0004 \u0005[היא].\u0006 ונמצא לדרך זו, כי גם ר' מאיר אינו סבור שתפוס לשון ראשון!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי לאביי: \u0003הוא,\u0004 רבה בר בר חנה, \u0003אמר\u0004 בשם ר' יוחנן: \u0003לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 \u0003ואנא אמינא: פליגי\u0004 \u0005[ואני אומר: חלוקים\u0006 הם\u0005],\u0006 ור' מאיר חולק איפוא בשיטת ר' יהודה במשנתנו.","ושבים לדון במחלוקת ר' יהודה וחכמים שבמשנתנו. \u0003אמר עולא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אושעיא: אפשר ידעין\u0004 \u0003חברין בבלאה\u0004 \u0005[האם יודעים חברינו הבבליים]\u0006 האם \u0003\"כזית\" \"כזית\" תנן\u0004 \u0005[שנינו]\u0006 במשנתנו שאמר: \"הריני שוחט על מנת לאכול כזית חוץ לזמנו, כזית חוץ למקומו\", ובזה אמר ר' יהודה שחל על הקרבן דין פיגול מתחילה, \u0003או \"כזית\u0004 חוץ לזמנו \u0003וכזית\u0004 חוץ למקומו\" \u0003תנן\u0004 \u0005[שנינו]\u0006 בו' החיבור?","וביאור משמעות השאלה: האם \u0003\"כזית כזית\" תנן\u0004 \u0005[שנינו],\u0006 \u0003אבל\u0004 אם אמר \u0003\"כזית\u0004 חוץ לזמנו \u0003וכזית\u0004 חוץ למקומו\" בו' החיבור — \u0003דברי הכל עירוב מחשבות הוי\u0004 \u0005[הוא],\u0006 וגם לדעת ר' יהודה אין זה פיגול אלא רק פסול. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003\"כזית וכזית\" תנן\u0004 \u0005[שנינו],\u0006 ש\u0003לר' יהודה,\u0004 למרות שהו' מחברת, מכל מקום \u0003פרטא הוי\u0004 \u0005[\u0006לשון \u0005פרט הוא],\u0006 שמגדיר כל פרט לעצמו, ולכן חל על הקרבן דין פיגול כשאמר \"כזית חוץ לזמנו\", ואין מעורבת בו האמירה השניה של חוץ למקומו, \u0003וכל שכן\u0004 שיהא הדין כן לדעתו אם אמר \u0003\"כזית כזית\",\u0004 שם אין אפילו ו' המחברת בין שתי האמירות?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, \u0003דבעא מיניה\u0004 \u0005[ששאל אותו]\u0006 \u0003לוי מרבי:\u0004 אם \u0003חישב לאכול\u0004 \u0003\"כזית למחר בחוץ\", מהו? אמר לו:\u0004 \u0003זו שאילה!\u0004 שאלה גדולה ויפה היא. ותשובתה, שאף לדעת ר' יהודה \u0003עירוב מחשבות הוי\u0004 \u0005[הוא],\u0006 ואין זה פיגול.","\u0003אמר לפניו\u0004 לרבי \u0003שמעון ברבי:\u0004 מה גדולה יש בשאלה זו, וכי \u0003לא משנתינו היא?\u0004 שהרי שנינו: \u0003לאכול כזית בחוץ כזית למחר, כזית למחר כזית\u0004 \u0003בחוץ, כחצי זית בחוץ כחצי זית למחר, כחצי זית למחר כחצי זית בחוץ\u0004 — הרי זה \u0003פסול ואין בו כרת,\u0004 ועל כך חלק ר' יהודה ואמר, שאם מחשבת הזמן קדמה הרי זה פיגול. ויש לדייק: דווקא במקרה זה חולק ר' יהודה, \u0003הא אידך\u0004 \u0005[אבל\u0006 נוסח \u0005אחר]\u0006 כגון \"כזית למחר בחוץ\" — \u0003עירוב מחשבות הוי\u0004 \u0005[הוא],\u0006 וכיון שאפשר לדייק דבר זה באופן פשוט מן המשנה, מה גדולה יש בשאלה זו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי לר' שמעון בנו: \u0003הוא,\u0004 לוי, \u0003שאל בי\u0004 (אותי) \u0003דבר חכמה, ואת אמרת\u0004 \u0005[ואתה אומר לי]\u0006 \u0003משנתינו. לדידך דאתניתך תרתי\u0004 \u0005[לך שלימדתי אותך שתים],\u0006 ששניתי לך גם \"כזית כזית\" וגם נוסח \"כזית וכזית\" \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003לך,\u0004 שמנוסח זה מכאן אפשר לדייק תשובה לשאלה.","\u0003לדידיה דלא אתניתיה\u0004 \u0005[ל\u0006גרסה \u0005שלו שלא שניתי לו]\u0006 \u0003אלא\u0004 \u0005חדא\u0006 \u0005[אחת],\u0006 \u0003ושמעינהו לרבנן דקא גרסי תרתי\u0004 \u0005[ו\u0006הוא \u0005שמע את החכמים שהם גורסים שתים],\u0006 כפי ששניתי לך, גם \"כזית כזית\" וגם \"כזית וכזית\". \u0003וסבר\u0004 \u0005[וסבור\u0006 היה\u0005]\u0006 כלומר, היה מסתפק בשאלה: \u0003דידי דווקא\u0004 \u0005[\u0006האם גרסתי \u0005שלי,\u0006 ששנה לי רבי, היא ה\u0005מדוייקת],\u0006 שרק בזה חולק ר' יהודה, \u0003ודידהו\u0004 \u0005[ושלהם]\u0006 הנוסח הנוסף שהם גורסים \u0003עירוב מחשבות הוי\u0004 \u0005[הוא].\u0006 \u0003או דלמא דידהו דווקא\u0004 \u0005[שמא\u0006 הנוסח \u0005שלהם\u0006 הוא ה\u0005מדוייק]\u0006 שגם ב\"כזית כזית\" וגם ב\"כזית וכזית\" חולק ר' יהודה, \u0003ולדידי\u0004 \u0005[ול\u0006גרסה \u0005שלי]\u0006 \u0003שיורי\u0004 \u0005[שיור]\u0006 \u0003שייר לי\u0004 ולא הביא את כל המקרים בהם ר' יהודה חולק, \u0003ומדשייר לי לדידי הא\u0004 \u0005[ומכיון ששייר לי ל\u0006גרסה \u0005שלי\u0006 דבר \u0005זה]\u0006 ששנה להם, אולי \u0003שייר להו לדידהו נמי בהך\u0004 \u0005[שייר להם ל\u0006גרסה \u0005שלהם גם כן את זו]\u0006 \"כזית למחר בחוץ\", ואולי גם בזה חלוק ר' יהודה.","עד כאן סיפור המעשה, ומכאן אנו יכולים להסיק לגבי שאלתו של עולא, מה נוסח המשנה של רבי, שיש לשאול: \u0003והי אתנייה\u0004 \u0005[ואיך שנה לו]\u0006 רבי ללוי, שיכול היה לוי לסבור כן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003\"כזית וכזית\" אתנייה\u0004 \u0005[שנה לו],\u0006 שר' יהודה סבור שאין כאן עירוב מחשבות, למרות ו' החיבור — \u0003האי לאו שיורא הוא\u0004 \u0005[זה אינו שיור]\u0006 מה שלא שנה גם \"כזית כזית\", כי הוא מובן מאליו. \u0003אלא\u0004 צריך לומר \u0003ש\u0004\u0003\"כזית כזית\" אתנייה\u0004 \u0005[שנה לו],\u0006 ומסופק היה לוי האם גם ב\"כזית וכזית\" חולק ר' יהודה.","ושואלים: אם אכן היה הנוסח ששנה לו רבי, מדוע שאל לוי מה יהא הדין ב\"כזית למחר בחוץ\"? \u0003ותיבעי ליה\u0004 \u0005[ותישאל לו]\u0006 שאלה מוקדמת יותר: מה יהא הדין לדברי ר' יהודה אם אמר \u0003\"כזית וכזית\"!\u0004","ומשיבים: \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 לוי: \u0003איבעי מיניה חדא דשמענא תרתי\u0004 \u0005[אשאל אותו\u0006 שאלה \u0005אחת שאשמע ממנה שתים].\u0006 \u0003דאי בעינא\u0004 \u0005[שאם אשאל אותו]\u0006 מה דעת ר' יהודה במקרה של \u0003\"כזית וכזית\", הא ניחא אי אמר לי כללא\u0004 \u0005[זה יהא נוח אם יאמר לי\u0006 שהוא עושה את שני הדיבורים ל\u0005כלל\u0006 אחד\u0005]\u0006 לדעת ר' יהודה, ויש כאן עירוב מחשבות, שאז יובן מכאן כי \u0003כל שכן \"כזית למחר בחוץ\",\u0004 שהוא ביטוי אחד. \u0003אלא אי אמר לי פרטא\u0004 \u0005[אם יאמר לי\u0006 ש\u0005פרט\u0006 הוא\u0005]\u0006 ששני דיבורים נפרדים הם, ואף בזה חולק ר' יהודה, \u0003אכתי\u0004 \u0005[עדיין]\u0006 השאלה \u0003\"כזית למחר בחוץ\" קא מיבעיא\u0004 \u0005[תישאל]\u0006 \u0003לי\u0004 ומוטב איפוא לשאול שאלה שתענה על שני המקרים כאחד, שאם חולק הוא ב\"כזית למחר בחוץ\" ואין בזה עירוב מחשבות — כל שכן ב\"כזית וכזית\".","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ששיקול זה הנחה את לוי — לא הרויח דבר, שהרי \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 \u0003התינח אי אמר ליה\u0004 \u0005[זה יהיה נוח אם אומר\u0006 \u0003לו]\u0004 \u0003\"כזית למחר בחוץ\" פרטא\u0004 \u0005[פרט\u0006 הוא\u0005],\u0006 שהם נחשבים כשני דיבורים נפרדים — \u0003כל שכן \"כזית וכזית\", אלא אי אמר ליה כללא\u0004 \u0005[אם\u0006 היה \u0005אומר לו\u0006 ש\u0005כלל\u0006 הוא\u0005],\u0006 \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003\"כזית וכזית\" מיבעי ליה\u0004 \u0005[תישאל לו]\u0006 מה דעת ר' יהודה בזה!","ומשיבים: \u0003אם כן\u0004 היתה התשובה, ש\"כזית למחר בחוץ\" כלל הוא, היה מקבל ממילא את התשובה לשאלתו השניה גם כן, שכן אז \u0003מרתח רתח\u0004 \u0005[היה כועס\u0006 עליו\u0005]\u0006 רבי, על שלא שאל כהוגן, וכך היה אומר לו:"],["\u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 \u0003\"כזית וכזית\" כללא\u0004 \u0005[כלל\u0006 הוא\u0005],\u0006 ועירוב מחשבות יש כאן גם לדעת ר' יהודה, \u0003\"כזית למחר בחוץ\" מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 כך היה אומר רבי, אם \u0003\"כזית למחר בחוץ\" פרטא\u0004 \u0005[\u0006לשון \u0005פרט\u0006 הוא\u0005],\u0006 ור' יהודה אומר שאין כאן עירוב מחשבות, \u0003\"כזית כזית\" מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]?\u0006","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 אם חשב על אכילת \u0003חצי זית חוץ לזמנו,\u0004 ועל \u0003חצי זית\u0004 אחד \u0003חוץ למקומו, ו\u0004על \u0003חצי זית\u0004 אחר \u0003חוץ לזמנו,\u0004 מה יהא הדין? \u0003אמר רבא: ויקץ כישן הפיגול\u0004 כלומר, כיון שחשב על שני חצאי הזיתים לאוכלם שלא בזמנו הרי הם מצטרפים, ונעשה כאילו חשב על כזית שלם. וחצי הזית של מחשבת חוץ למקומו אינו נחשב לבטל מחשבת פיגול, כיון שהוא חצי שיעור. \u0003ורב המנונא אמר: עירוב מחשבות הוי\u0004 \u0005[הוא],\u0006 שמחשבת חוץ למקומו שנתערבה מתחילה במחשבת חוץ לזמנו מונעת שיחול שם פיגול על כך.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את דעתי זו? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 לגבי טומאת אוכלין (ששיעורה בכביצה): \u0003כביצה\u0004 של \u0003אוכל\u0004 שטמא בדרגת \u0003ראשון\u0004 לטומאה, \u0003וכביצה אוכל\u0004 שטמא בדרגת \u0003שני\u0004 לטומאה, \u0003שבללן זה בזה\u0004 — הרי זה כולו \u0003ראשון\u0004 לטומאה, ועושה את הנוגע בו שני לטומאה. אם \u0003חלקן\u0004 את התערובת לשנים, ובכל אחד מן החלקים מחצה אוכל ראשון ומחצה אוכל שני — \u0003זה שני וזה שני,\u0004 שהרי אין בכל אחד מהם שיעור ביצה של אוכל ראשון לטומאה, ואוכלים טמאים בדרגה שונה מצטרפים לטמא כטומאה הקלה שבשניהם. \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003חזר ועירבן\u0004 — \u0003ראשון הוי\u0004 \u0005[הוא].\u0006","\u0003ממאי\u0004 \u0005[מנין]\u0006 אני יודע זאת? \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 ב\u0005סוף\u0006 אותה משנה\u0005]:\u0006 אם \u0003נפל זה בעצמו וזה בעצמו\u0004 כל אחד מן החלקים, שהוא שני לטומאה, \u0003על ככר של תרומה\u0004 — \u0003פסלוה,\u0004 כדין שני לטומאה, שפוסל תרומה לאכילה ואינו מטמאה (לטמא תרומה אחרת). אבל אם \u0003נפלו שניהן כאחת\u0004 על ככר של תרומה — נצטרף שיעור ביצה של ראשון לטומאה שיש בשניהם, ו\u0003עשאוה\u0004 את כיכר התרומה \u0003שניה\u0004 ופוסלת תרומה שנגעה בה. הרי שטומאה ראשונה שהיתה מתחילה ונתערבה, חזרה ונעורה כשהיה בה שיעור ראוי. והוא הדין למחשבת חוץ לזמנו של חצי זית ראשון שמצטרפת למחשבת חצי זית אחרון, למרות שנתערבה תחילה במחשבת חצי זית של חוץ למקומו, ואז עוד לא היה בה דין פיגול.","\u0003ורב המנונא אמר:\u0004 יש הבדל בין הדברים, \u0003התם איכא שיעורא\u0004 \u0005[שם יש שיעור]\u0006 מתחילה של ראשון לטומאה, ולכן הוא חוזר ומצטרף, אבל \u0003הכא ליכא שיעורא\u0004 \u0005[כאן אין\u0006 מתחילה \u0005שיעור]\u0006 כזית כדי לפגל.","\u0003אמר רב המנונא:\u0004 \u0003מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה\u0006 את דעתי\u0005],\u0006 שמחשבת חוץ לזמנו שנתערבה במחשבת חוץ למקומו, שוב אינה מצטרפת למחשבת חוץ לזמנו? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 חצי שיעור מן \u0003האוכל שנטמא\u0004 \u0003באב הטומאה\u0004 (והוא עכשיו ראשון לטומאה) \u0003ו\u0004חצי \u0003נטמא בולד הטומאה\u0004 (והוא עכשיו שני לטומאה) — \u0003מצטרפין זה עם זה\u0004 לשיעור ביצה \u0003לטמא בקל שבשניהם\u0004 כלומר, כשני לטומאה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן שבכל מקרה הדין כן, \u0003אף על גב דהדר מלייה\u0004 \u0005[אף על פי שחזר ומילא\u0006 והשלים \u0005אותו]\u0006 את שנטמא באב הטומאה לכדי שיעור ביצה, מאחר שכבר בטל ממנו דין ראשון לטומאה, ואינו חוזר וניעור? והוא הדין למחשבת חוץ לזמנו של כחצי זית ראשון!","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר דווקא במקרה ש\u0003לא הדר מלייה\u0004 \u0005[חזר ומילא אותו]!\u0006 שאלה זו לא הוכרעה, ומביאים מקרים דומים.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר:\u0004 חישב על \u0003חצי זית חוץ למקומו ו\u0004על \u0003חצי זית חוץ לזמנו ו\u0004על \u0003חצי זית חוץ לזמנו\u0004 — \u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא:\u0004 הרי זה \u0003פיגול,\u0004 כי \u0003אין חצי זית\u0004 של חוץ למקומו \u0003מועיל\u0004 כדי למנוע את הפיגול \u0003במקום\u0004 שיש מחשבת \u0003כזית\u0004 חוץ לזמנו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר\u0004 בנוסח אחר: חישב על \u0003חצי זית חוץ לזמנו ו\u0004על \u0003חצי זית חוץ לזמנו ו\u0004על \u0003חצי זית חוץ למקומו\u0004 — \u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: פיגול,\u0004 כי \u0003אין חצי זית מועיל במקום כזית.\u0004","ואילו \u0003רב אשי מתני הכי\u0004 \u0005[היה שונה כך]:\u0006 חישב על \u0003חצי זית חוץ לזמנו, ו\u0004על \u0003כזית\u0004 אחר חישב עליו \u0003חציו חוץ למקומו וחציו חוץ לזמנו\u0004 — \u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: פיגול,\u0004 ש\u0003אין חצי זית מועיל במקום כזית.\u0004","\u0003אמר ר'\u0004 \u0003ינאי: חישב\u0004 על הבשר \u0003שיאכלוהו כלבים למחר\u0004 — הרי \u0003זה\u0004 \u0003פיגול,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת איזבל יאכלו הכלבים בחלק יזרעאל\"\u0004 (מלכים ב ט, י), משמע שזה נחשב לאכילה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אמי: אלא מעתה,\u0004 אם \u0003חישב שתאכלהו אש\u0004 (של חולין) \u0003למחר,\u0004 שגם בזה נאמר לשון אכילה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תאכלהו אש לא נפח\"\u0004 (איוב כ, כו), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהוא \u0003פיגול? וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 ש\u0005כך הוא גם כן],\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 חשב \u0003לאכול כחצי זית ולהקטיר חצי כזית\u0004 — \u0003כשר, שאין אכילה והקטרה מצטרפין,\u0004 משמע שאכילת האש אינה נחשבת לאכילה!","ומשיבים: \u0003אי דאפקה\u0004 \u0005[אם שהוציא]\u0006 את הדברים \u0003בלשון אכילה\u0004 — \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006 היה הדין\u0005]\u0006 שהיו מצטרפים אכילה והקטרה. אבל \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנה \u0005במה אנו עוסקים]\u0006 — \u0003דאפקה\u0004 \u0005[שהוציאה]\u0006 \u0003בלשון הקטרה,\u0004 שאז \u0003לשון אכילה לחוד ולשון הקטרה לחוד.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 אם \u0003חישב לאכול כזית בשני בני אדם\u0004 שכל אחד מהם יאכל מחר חצי זית, \u0003מהו? בתר\u0004 \u0005[אחר]\u0006 ה\u0003מחשבה אזלינן\u0004 \u0005[אנו הולכים],\u0006 \u0003דאיכא\u0004 \u0003שיעורא\u0004 \u0005[שיש שיעור]\u0006 שלם של אכילה במחשבה זו, \u0003או בתר\u0004 \u0005[אחר]\u0006 האנשים ה\u0003אוכלין אזלינן\u0004 \u0005[אנו הולכים],\u0006 \u0003ו\u0004הרי \u0003ליכא שיעורא\u0004 \u0005[אין שיעור]\u0006 באכילה של כל אחד מהם?","\u0003אמר אביי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ששנינו: \u0003לאכול כחצי זית ולהקטיר כחצי זית\u0004 — \u0003כשר, שאין אכילה והקטרה מצטרפין,\u0004"],["\u0003הא\u0004 \u0005[הרי]\u0006 אם היה חושב \u0003לאכול ולאכול דומיא\u0004 \u0005[בדומה]\u0006 \u0003לאכול\u0004 כחצי \u0003זית\u0004 \u0003ולהקטיר\u0004 כחצי זית, \u0003והיכי דמי\u0004 \u0005[וכיצד הוא בדיוק]\u0006 — \u0003בשני בני אדם\u0004 שזה יאכל כחצי זית וזה יאכל כחצי זית — היה \u0003מצטרף.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם \u0003חישב לאכול כזית ב\u0004משך זמן שהוא \u0003יתר מכדי אכילת פרס\u0004 (חצי כיכר), \u0003מהו\u0004 הדין? האם \u0003לאכילת גבוה מדמינן ליה\u0004 \u0005[מדמים אנו אותו]\u0006 ובאכילת מזבח (הקטרה) אין שיעור כמה זמן נמשכת השריפה, ובדרך כלל היא נמשכת זמן ארוך יותר, \u0003או לאכילת הדיוט מדמינן ליה\u0004 \u0005[מדמים אנו אותו]\u0006 וביותר משיעור אכילת פרס כזה אין זו נחשבת אכילה? \u0003אמר אביי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003לאכול כחצי זית ולהקטיר כחצי זית\u0004 — \u0003כשר, שאין אכילה והקטרה מצטרפין.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 אם חישב \u0003לאכול ולהקטיר\u0004 אינו מצטרף, \u0003הא\u0004 \u0005[אבל]\u0006 אם היה חושב בכגון זה \u0003לאכול ולאכול\u0004 — היה \u0003מצטרף, והא\u0004 \u0005[והרי]\u0006 \u0003הקטרה\u0004 של כזית בשר \u0003גם\u0004 \u0003ביותר מכדי אכילת פרס הוא,\u0004 משמע שאף אכילת הדיוט בשיעור זמן זה נחשבת לאכילה.","","ודוחים: מכאן אין להוכיח, \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר \u0003ב\u0004מחשב על \u0003היסק גדול,\u0004 שנשרף בו כזית בשר בפחות מכדי שיעור אכילת פרס, ודווקא באופן זה אכילות מצטרפות זו לזו.","שנינו במשנה: שחט על מנת \u0003לאכול כחצי זית ולהקטיר כחצי זית\u0004 — \u0003כשר.\u0004 ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 כשחושב \u0003לאכול ולהקטיר, הא\u0004 \u0005[אבל]\u0006 אם היה חושב \u0003לאכול\u0004 חצי זית \u0003ולאכול\u0004 עוד חצי זית \u0003דבר שאין דרכו לאכול\u0004 — היה \u0003מצטרף.\u0004","אולם \u0003הא קתני רישא\u0004 \u0005[הרי שנה בראשה\u0006 של המשנה\u0005]:\u0006 \u0003לאכול את שדרכו לאכול\u0004 — \u0003מצטרף,\u0004 ויש לדייק: \u0003את שדרכו לאכול\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שאין דרכו\u0004 — \u0003לא\u0004 מצטרף! \u0003אמר ר' ירמיה: הא מני\u0004 \u0005[\u0006הלכה \u0005זו\u0006 שבסוף המשנה, כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: מחשבין מ\u0004דברים הראויים ל\u0003אכילת אדם לאכילת מזבח, ומ\u0004דברים הראויים ל\u0003אכילת מזבח לאכילת אדם, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003השוחט את הזבח\u0004 \u0003לאכול דבר שאין דרכו לאכול,\u0004 או \u0003להקטיר דבר שאין דרכו להקטיר\u0004 חוץ למקומו או חוץ לזמנו — הרי זה \u0003כשר, ור' אליעזר פוסל.\u0004","","\u0003אביי אמר:\u0004 יש לפרש סופה של המשנה \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 הסבורים שאין מחשבת פסול חלה על דבר שאין דרכו לאכול. \u0003ולא תימא\u0004 \u0005[ואל תאמר,\u0006 תדייק\u0005]:\u0006 לאכול כחצי זית ולהקטיר כחצי זית כשר, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003לאכול ולאכול דבר שאין דרכו לאכול\u0004 מצטרף ופיגול. \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003לאכול\u0004 כחצי \u0003זית\u0004 \u0003ולאכול\u0004 כחצי זית \u0003דבר שדרכו לאכול\u0004 — מצטרף, למרות שהן שתי מחשבות נפרדות בשני חצאי זיתים. ושואלים: אם כן, \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 התנא בהלכה זו שלנו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003דבר שדרכו לאכול קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שמצטרף זה לזה — הרי כבר \u0003מרישא שמע מינה\u0004 \u0005[מראש\u0006 המשנה \u0005נלמד]\u0006 דבר זה, שהרי שנינו: \u0003כחצי זית בחוץ כחצי זית למחר\u0004 — \u0003פסול.\u0004 ויש לדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם חשב כ\u0003חצי זית\u0004 שני \u0003למחר\u0004 — יהיה זה \u0003פיגול!\u0004","","\u0003אלא, אי\u0004 \u0005[אם]\u0006 תאמר שבא להשמיענו את עצם ההלכה, שאם חשב \u0003לאכול ולהקטיר\u0004 שאין מצטרפים — הרי \u0003מדוקיא דרישא שמע מינה\u0004 \u0005[מהדיוק של תחילת המשנה נשמע\u0006 דבר זה\u0005],\u0006 ששנינו שם שאם חשב \u0003לאכול דבר שדרכו לאכול\u0004 חוץ לזמנו — \u0003אין\u0004 \u0005[כן]\u0006 פיגול, אבל דבר \u0003שאין דרכו לאכול\u0004 — \u0003לא,\u0004 וממילא אינו מצטרף.","ונדייק מכאן: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה\u0004 שחשב \u0003לאכול ולאכול דבר שאין דרכו לאכול\u0004 — \u0003לא מצטרף,\u0004 למרות שחשב על אכילה, אם חשב \u0003לאכול ולהקטיר מיבעי\u0004 \u0005[נצרכה לומר]\u0006 שאינו מצטרף? ולפי זה אין אנו למדים כל דבר חדש מסופה של המשנה!","ודוחים: גם אם נדייק מתחילת המשנה, שלאכול ולאכול דבר שאין דרכו לאכול מצטרפים, עדיין \u0003לאכול ולהקטיר איצטריך\u0004 \u0005[הוצרך\u0006 לומר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 שחושב לאכול דבר שאין דרכו לאכול \u0003הוא\u0004 שאינו מצטרף, משום \u0003דלאו כי אורחיה קא מחשב\u0004 \u0005[שעל\u0006 אכילה \u0005שלא כדרכו הוא מחשב],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 לאכול ולהקטיר, \u0003דבהאי כי אורחיה ובהאי כי אורחיה\u0004 \u0005[שבזה\u0006 מחשב \u0005כדרכו ובזה כדרכו]\u0006 \u0003אימא ליצטרף\u0004 \u0005[אמור שיצטרף],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאכילה והקטרה אינם מצטרפים.","","\u0003כל הפסולין\u0004 לעבודה \u0003ששחטו\u0004 — \u0003שחיטתן כשרה, שהשחיטה\u0004 בקדשים \u0003כשרה\u0004 לכתחילה \u0003בזרים\u0004 שאינם כהנים, \u0003ובנשים\u0004 אפילו הן ממשפחת כהונה, \u0003ובעבדים\u0004 כנעניים, \u0003ובטמאים, ואפילו בקדשי קדשים, ובלבד שלא יהיו טמאים נוגעין בבשר\u0004 של הבהמה שנשחטה ומטמאים אותו. \u0003לפיכך\u0004 כיון ששחיטתם של פסולים אלה כשירה — \u0003הן פוסלין במחשבה\u0004 אם כששחטו חשבו מחשבת פסול, כגון לאכול את הקרבן חוץ למקומו או חוץ לזמנו."],["\u0003וכולן,\u0004 כל הפסולים לעבודת כהונה, \u0003שקיבלו את הדם\u0004 במחשבה להקריבו \u0003חוץ לזמנו וחוץ למקומו, אם יש\u0004 עדיין \u0003דם הנפש\u0004 בבהמה — \u0003יחזור\u0004 הכהן \u0003הכשר ויקבל\u0004 ויזרוק את הדם על המזבח.","\u0003קיבל הכשר\u0004 את הדם בכלי כדין, \u0003ונתן\u0004 את הכלי \u0003לפסול\u0004 — \u0003יחזיר\u0004 הפסול \u0003לכשר.\u0004 כיוצא בדבר, \u0003קיבל\u0004 הכשר \u0003בימינו\u0004 \u0003ונתן\u0004 אחר כך את הכלי \u0003ל\u0004יד \u0003שמאלו\u0004 (ועבודה היא בימין דווקא) — \u0003יחזיר לימינו.\u0004 וכן \u0003קיבל בכלי קדש ונתן\u0004 \u0003לכלי חול\u0004 — \u0003יחזיר לכלי קדש. נשפך\u0004 הדם \u0003מן הכלי\u0004 שקיבל בו \u0003על הרצפה ואספו\u0004 — \u0003כשר.\u0004","\u0003נתנו\u0004 (זרקו) הפסול את הדם \u0003על גבי הכבש,\u0004 או על קיר המזבח ש\u0003לא כנגד היסוד\u0004 כלומר, במקום שאין שם יסוד, \u0003נתן את\u0004 הדמים \u0003הניתנין למטה\u0004 מחצי המזבח, כגון דם עולה, \u0003למעלן, ואת הניתנין למעלן\u0004 כגון דם חטאת \u0003למטה, ואת הניתנין בפנים\u0004 בהיכל, כגון דם פר ושעיר של יום הכיפורים, נתן \u0003בחוץ\u0004 על מזבח העולה, \u0003ואת הניתנין בחוץ\u0004 נתן \u0003בפנים, אם יש דם הנפש\u0004 עדיין — \u0003יחזור הכשר ויקבל.\u0004","מלשון המשנה שנאמר בה \"כל הפסולים ש\u0003שחטו\"\u0004 בלשון עבר, מדייקים: ב\u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 השחיטה כשירה, \u0003לכתחלה\u0004 — \u0003לא.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במדרש ההלכה: נאמר בקרבן עולה \u0003\"ושחט\u0004 את בן הבקר\" (ויקרא א, ה), ולא נאמר \"ושחט הכהן\", לומר ש\u0003שחיטה בזר\u0004 \u0003כשרה,\u0004 וכפי ששנינו במשנתנו \u0003שהשחיטה כשרה בזרים\u0004 \u0003ובנשים ובעבדים ובטמאים,\u0004 ו\u0003אפילו בקדשי קדשים.\u0004 ויש לשאול: \u0003או\u0004 נאמר כי \"ושחט\" האמור בכתוב \u0003אינו אלא בכהנים?\u0004","על כך יש להשיב: \u0003אמרת\u0004 (אומר אתה): \u0003וכי מאין באתה?\u0004 מהיכן אתה בא לסברה זו, שכהן הוא? \u0003מכלל שנאמר\u0004 לאהרן הכהן: \u0003\"ואתה ובניך אתך תשמרו את כהנתכם לכל דבר המזבח\"\u0004 (במדבר יח, ז).","\u0003יכול אף בשחיטה\u0004 הדין כן? \u0003תלמוד לומר: \"ושחט את בן הבקר לפני ה'\",\u0004 ומיד אחר כך: \u0003\"והקריבו\u0004 בני אהרן\" (ויקרא א, ה), לומר שדווקא \u0003מקבלה ואילך מצות כהונה, לימד על השחיטה שכשרה\u0004 לכתחילה \u0003בכל אדם!\u0004","ומשיבים: באמת \u0003הוא הדין\u0004 ש\u0003אפילו לכתחילה נמי\u0004 \u0005[גם כן]\u0006 מותר לפסולים לשחוט, \u0003ומשום דקא בעי\u0004 \u0003למיתנא\u0004 \u0005[שרצה לשנות]\u0006 גם \u0003טמאים,\u0004 ש\u0003לכתחילה לא\u0004 ישחטו, \u0003גזירה שמא יגעו בבשר\u0004 ויטמאוהו, לכן \u0003תנא\u0004 \u0005[שנה]\u0006 בה לשון \u0003\"ששחטו\",\u0004 שהיא בדיעבד.","ושואלים: \u0003וטמא\u0004 ששחט ב\u0003דיעבד שפיר דמי\u0004 \u0005[טוב,\u0006 כשר, \u0005הוא]?\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במדרש ההלכה: נאמרו שני ציווים ברצף אחד: \u0003\"וסמך\u0004 ידו על ראש העולה... \u0003ושחט\"\u0004 (ויקרא א, ד—ה), ומשמע שמדובר באותו אדם, ללמדנו: \u0003מה סמיכה\u0004 היא \u0003בטהורים, אף שחיטה בטהורים!\u0004 ואומרים: דבר זה הוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 שאסרו לטמא לשחוט, אבל מן התורה כשר.","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003סמיכה? דכתיב\u0004 \u0005[שנאמר\u0006 בה\u0005]:\u0006 \u0003\"לפני ה'\"\u0004כלומר, בעזרה, ואין טמא נכנס לעזרה, \u0003שחיטה נמי\u0004 — \u0003הכתיב\u0004 \u0005[גם כן הרי נאמר]:\u0006 \u0003\"לפני ה'\"\u0004 (ויקרא א,ד—ה), ואם כן איך יכול הטמא להיכנס ולשחוט! ומשיבים: \u0003אפשר דעביד\u0004 \u0005[ש\u0006הוא \u0005עושה]\u0006 \u0003סכין ארוכה\u0004 ועומד בחוץ \u0003ושחיט\u0004 \u0005[ושוחט]\u0006 בפנים.","ומקשים: \u0003סמיכה נמי\u0004 \u0005[גם כן]\u0006 \u0003אפשר דמעייל ידיה וסמיך\u0004 \u0005[שמכניס\u0006 את \u0005ידו\u0006 לפנים \u0005וסומך]!\u0006 ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא\u0006 חכם זה\u0005]\u0006 ש\u0003ביאה במקצת,\u0004 שמכניס רק חלק מגופו, גם כן \u0003שמה ביאה,\u0004 ואסור לטמא להכניס גם חלק מגופו למקדש.","\u0003רב חסדא מתני איפכא\u0004 \u0005[היה שונה להיפך]:\u0006 \u0003\"וסמך... ושחט\", מה שחיטה בטהורין, אף סמיכה בטהורין.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003שחיטה\u0004 שממנה למדים? \u0003דכתיב\u0004 \u0005[שנאמר\u0006 בה\u0005]:\u0006 \u0003\"לפני ה'\",\u0004 ואין טמא נכנס לעזרה,"],["\u0003סמיכה נמי כתיב\u0004 \u0005[גם כן נאמר\u0006 בה\u0005]:\u0006 \u0003\"לפני ה'\"!\u0004 ומשיבים: מכך אי אפשר היה ללמוד שהיא בטהורים דווקא, שהרי \u0003אפשר דמעייל ידיה\u0004 \u0003וסמיך\u0004 \u0005[שמכניס ידו וסומך].\u0006 ואומרים: והרי \u0003שחיטה נמי\u0004 \u0005[גם כן]\u0006 \u0003אפשר דעביד\u0004 \u0005[שעושה]\u0006 \u0003סכין ארוכה ושחיט\u0004 \u0005[ושוחט]!\u0006","ומשיבים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003שמעון התימני היא,\u0004 שהוא סבור שגם השוחט צריך להיות בעזרה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \u0003\"ושחט את בן הבקר לפני ה'\"\u0004 (ויקרא א, ה) ויש ללמוד מכאן שבן הבקר צריך להיות לפני ה', בעזרה, \u0003ולא השוחט לפני ה',\u0004 אלא יכול לעמוד בחוץ ולשחוט בפנים. \u0003שמעון התימני אומר: מנין שיהיו ידיו של שוחט לפנים מן הנשחט? תלמוד לומר: \"ושחט את בן הבקר לפני ה'\",\u0004 ללמד שמי ש\u0003שוחט את בן הבקר יהא לפני ה'.\u0004","ובשאלה האם ביאה במקצת של הטמא לעזרה נחשבת ביאה, \u0003אמר עולא אמר ריש לקיש: טמא שהכניס ידו לפנים\u0004 — \u0003לוקה,\u0004 שעבר על לאו הכתוב בתורה, \u0003שנאמר\u0004 לגבי טומאת יולדת: \u0003\"בכל קדש לא תגע\u0004 ואל המקדש לא תבוא\" (ויקרא יב, ד), \u0003מקיש\u0004 (משווה) הכתוב בפסוק זה \u0003ביאה לנגיעה, מה נגיעה\u0004 אפילו \u0003במקצת\u0004 בחלק מגופו \u0003שמה נגיעה, אף ביאה במקצת\u0004 שמכניס רק חלק מגופו \u0003שמה ביאה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב הושעיא לעולא\u0004 ממה ששנינו בברייתא: \u0003מצורע שחל\u0004 יום \u0003שמיני שלו\u0004 לטהרתו \u0003להיות בערב הפסח, וראה קרי\u0004 (נפלטה ממנו שכבת זרע) \u0003בו ביום וטבל,\u0004 והוא צריך להגיע לשער העזרה, ולהכניס בהונותיו לעזרה כדי שיזו עליהם מדם האשם, וכך יטהר ויוכל לאכול את הפסח בערב.","\u0003אמרו חכמים: אף על פי שאין טבול יום אחר\u0004 של טומאת קרי \u0003נכנס\u0004 למקדש, \u0003זה נכנס\u0004 עד לשער העזרה, ומדוע? \u0003מוטב יבוא\u0004 חיוב \u0003עשה\u0004 של הקרבת קרבן פסח \u0003שיש בו כרת\u0004 למי שמבטלו, \u0003וידחה עשה\u0004 של שילוח הטמאים מן המחנה, \u0003שאין בו כרת.\u0004","\u0003ור' יוחנן\u0004 \u0003אמר: דבר תורה אפילו\u0004 איסור \u0003עשה אין בו\u0004 בטבול יום להיכנס למקדש, \u0003שנאמר: \"ויעמד יהושפט בקהל יהודה וירושלם בבית ה' לפני החצר החדשה\"\u0004 (דברי הימים ב כ, ה), ושאלו: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"חצר החדשה\"? אמר ר' יוחנן: שחידשו בה דברים\u0004 \u0003הרבה, ואמרו: טבול יום אל יכנס למחנה לויה,\u0004 משמע שמן התורה מותר לו להיכנס!","ומעתה, הקושיה על עולא: \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 ש\u0003ביאה במקצת שמה ביאה,\u0004 אם כן \u0003היכי מעייל ידיה\u0004 \u0005[איך\u0006 המצורע כשהוא טבול יום \u0005מכניס\u0006 את \u0005ידיו]\u0006 לעזרה \u0003בבהונות\u0004 כדי להיטהר? והרי במקרה זה \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003עשה שיש בו כרת הוא,\u0004 שהרי טבול יום הנכנס לעזרה חייב כרת!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא לרב הושעיא: \u0003מטונך\u0004 \u0005[ממשאך]\u0006 כלומר, ממה שאתה בא להכביד ולהקשות עלי — משם אני מביא ראיה לשיטתי, כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מצורע,\u0004 שהתירה לו התורה להכניס בהונותיו לעזרה כדי להיטהר, למרות שהוא מחוסר כיפורים, ולכן \u0003הואיל והותר\u0004 בביאה במקצת \u0003לצרעתו הותר\u0004 גם \u0003ל\u0004ענין \u0003קיריו.\u0004 אבל מכל מקום — ביאה במקצת נחשבת ביאה.","בעקבות דברים אלה \u0003אמר רב יוסף: קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003עולא\u0004 שאם היו \u0003רובן\u0004 של ישראל \u0003זבים\u0004 בערב הפסח, ואינם מותרים לעשות את הפסח בטומאה, \u0003ונעשו טמאי מתים,\u0004 ואם היה הציבור, כולו או רובו, טמא מת מותר לו להקריב פסח בטומאה, \u0003הואיל והותרו לטומאתן\u0004 לענין טומאת מת — \u0003הותרו\u0004 גם \u0003לזיבתן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 במצורע שראה קרי, הרי הותר הטמא מתחילה, ושוב אינו נאסר בגלל טומאה אחרת. אבל הזבים הרי מתחילה נדחו מהקרבה, וכשנוספה להם טומאת מת — \u0003טומאה\u0004 (טומאת המת) \u0003אישתראי\u0004 \u0005[הותרה],\u0006 \u0003זיבה\u0004 שכבר היתה בו \u0003לא אישתראי\u0004 \u0005[הותרה]!\u0006","הוסיף ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003דלמא הכי קאמר מר\u0004 \u0005[כך אמר אדוני]\u0006 שכך צריך לתקן את הדברים: אם היו מתחילה \u0003רובן טמאי מתים ונעשו זבים, הואיל והותרו לטומאתן הותרו לזיבתן. אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אין\u0004 \u0005[כן],\u0006 לכך התכוונתי.","ומקשים: \u0003ואכתי לא דמי\u0004 \u0005[ועדיין אינו דומה]\u0006 לדברי עולא, שכן \u0003מצורע היתירא\u0004 \u0005[היתר]\u0006 \u0003הוא, הואיל ואישתרי אישתרי\u0004 \u0005[הואיל והותר הותר],\u0006 אבל \u0003טומאה\u0004 בהקרבת הפסח הלוא רק \u0003דחויה היא\u0004 ולא היתר גמור, ולכן אפשר לומר: \u0003להא אידחאי, להא לא אידחאי\u0004 \u0005[לזה,\u0006 לענין טומאת מת \u0005נדחתה, לזה,\u0006 לענין טומאת זב \u0005לא נדחתה]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אדרבה, איפכא מסתברא\u0004 \u0005[גדולה מזו, ההיפך\u0006 הוא \u0005המסתבר]!\u0006 משום ש\u0003מצורע היתירא\u0004 \u0005[היתר]\u0006 \u0003הוא,\u0004 שהתורה התירה לו במפורש להכניס בהונותיו כדי להיטהר, ולא הותר כן לשאר טמאים, אפשר לומר: \u0003להא אישתראי ולהא לא אישתראי\u0004 \u0005[לזה הותרה\u0006 הכניסה, \u0005ולזה לא הותרה],\u0006 ואילו \u0003טומאה דחויה הוא\u0004 בטמאי מת, וכיון שנדחתה, \u0003מה לי חד דחויא\u0004 \u0005[דחיה אחת]\u0006 \u0003מה לי שתי דחיות?\u0004"],["ומעירים: \u0003מכלל\u0004 הדברים אתה למד \u0003דתרוייהו סבירא להו\u0004 \u0005[ששניהם,\u0006 אביי ורבא, \u0005סבורים הם]\u0006 כי \u0003טומאה\u0004 \u0003דחויה היא בצבור\u0004 ולא הותרה לגמרי. ושבים לדון בדברי עולא, שאמר כי ביאה של טמא במקצת שמה ביאה.","ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003מסייע ליה\u0004 \u0005[לו]\u0006 מה ששנינו בברייתא: \u0003כל הסמיכות שהיו שם\u0004 במקדש, \u0003קורא עליהן אני\u0004 מה ששנו חכמים: \u0003תכף לסמיכה שחיטה,\u0004 שצריך שיהיו תכופים בזמן ובמקום ככל האפשר,","\u0003חוץ\u0004 \u0003מ\u0004סמיכה \u0003זו\u0004 שהמצורע סומך על אשמו, \u0003שהיתה ב\u0004חללו של \u0003שער נקנור,\u0004 ולא בעזרה עצמה, שם נשחט האשם, כיון \u0003שאין מצורע יכול ליכנס לשם עד\u0004 \u0003שמזין עליו\u0004 (עבורו) על המזבח \u0003מדם חטאתו ומדם אשמו.\u0004 \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003ביאה\u0004 \u0003במקצת לא שמה ביאה\u0004 — \u0003ליעייל ידיה ולסמוך\u0004 \u0005[שיכניס ידו\u0006 בפנים \u0005ויסמוך],\u0006 והקרבן יישחט סמוך לפתח!","\u0003אמר רב יוסף:\u0004 אין מכאן ראיה, כי \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' יוסי בר' יהודה\u0004 \u0003היא,\u0004 ש\u0003אמר: מרחק\u0004 \u0005[מרוחק]\u0006 \u0003צפון,\u0004 שהצפון בו שוחטים קדשי קדשים (ואשם בכללם) אינו כולל את כל צפון העזרה, אלא רק את השטח שמצפון למזבח, והוא רחוק יותר מעשרים ושתים אמה מפתח העזרה. וגם אם יכניס המצורע ידיו לעזרה ויסמוך, לא ניתן לשחוט שם את האשם.","ושואלים: \u0003וליעבד\u0004 \u0005[ושיעשו]\u0006 \u0003פישפש\u0004 (דלת קטנה) בכותל העזרה הצפוני, מול המזבח, ושם יכניס ידיו ויסמוך! \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 אי אפשר לעשות שינויים כאלה במקדש, כי נאמר לגבי מבנה המקדש: \u0003\"הכל בכתב מיד ה' עלי השכיל\u0004 \u0003את כל מלאכת התבנית\"\u0004 (דברי הימים א כח, יט).","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 \u0003אמר רב יוסף\u0004 הסבר אחר מדוע לא מכניס המצורע את ידיו לעזרה וסומך, כי \u0003כל הסומך\u0004 על קרבן — \u0003ראשו ורובו מכניס, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 סמיכה ב\u0003כל כחו בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003לא אפשר\u0004 שיסמוך המצורע בעזרה, שביאת כולו היא, ולא ביאה במקצת, ולכן הוא עושה זאת בשער ניקנור.","ושואלים: תנא זה, \u0003מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 ש\u0003סמיכת אשם מצורע דאורייתא\u0004 \u0005[מן התורה\u0006 היא מחוייבת\u0005],\u0006 \u0003ותכף לסמיכה שחיטה\u0004 גם כן \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003ליעול ולסמוך להדיא\u0004 \u0005[שיכנס ויסמוך במישרין\u0006 בפנים\u0005],\u0006 \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה\u0006 במפורש\u0005]\u0006 שכך יעשה!","\u0003אמר רב אדא בר מתנה:\u0004 באמת כך היה צריך להיות מדין תורה, אלא \u0003גזירה\u0004 של חכמים היא, \u0003שמא ירבה בפסיעות\u0004 וייכנס יותר מכדי הצורך, ועל כך יתחייב. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב אדא בר מתנה:\u0004 אמנם \u0003סמיכת אשם מצורע דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005],\u0006 \u0003ו\u0004אולם \u0003תכף לסמיכה שחיטה לאו דאורייתא\u0004 \u0005[אינה מן התורה],\u0006 ולכן הוא יכול לסמוך בחוץ.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: נאמר \u0003\"וסמך... ושחט\"\u0004 (ויקרא א, ה), \u0003מה סמיכה בטהורין\u0004 דווקא, ולא בטמאים — \u0003אף שחיטה בטהורין. ואי אמרת לאו דאורייתא\u0004 \u0005[ואם אומר אתה\u0006 שתיכף לסמיכה שחיטה \u0005אינה מן התורה],\u0006 סמיכה \u0003בטמאין נמי משכחת לה\u0004 \u0005[גם כן אתה מוצא אותה],\u0006 שהרי יכולים הטמאים לסמוך מחוץ לעזרה!","\u0003אלא איפוך\u0004 \u0005[הפוך]\u0006 ואמור כך: \u0003סמיכת אשם מצורע לאו דאורייתא\u0004 \u0005[אינה מן התורה]\u0006 ולכן יכול לעשות זאת בחוץ, \u0003ו\u0004אולם בקרבנות שצריכים סמיכה מן התורה — \u0003תכף לסמיכה שחיטה דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005].\u0006"],["ושבים לדברי עולא בשם ריש לקיש (לעיל זבחים לב,ב) שטמא שהכניס ידו לעזרה לוקה, משום שביאה במקצת שמה ביאה, והקשו על כך מן הברייתא בענין מצורע האומרת שאין בכך כרת. \u0003רבינא אמר:\u0004 מה שנאמר \u0003לענין מלקות איתמר\u0004 \u0005[נאמר],\u0006 שלא אמר ריש לקיש אלא שיש עונש מלקות על המכניס ידו לעזרה, אבל גם הוא מודה שאין בזה חיוב כרת כמו בביאת הטמא כולו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר\u0004 בשם \u0003ר' אבהו:\u0004 מה שאמר ריש לקיש על פסוק זה, \u0003לענין טמא שנגע בקודש איתמר\u0004 \u0005[נאמר]\u0006 הדבר, ואינו מדבר כלל בביאה במקצת למקדש כפי שאמר עולא בשמו.","\u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 שנחלקו לענין \u0003טמא שנגע בקודש, ריש לקיש אמר: לוקה\u0004 על כך, שעבר על לאו הכתוב בתורה, \u0003ר' יוחנן אמר: אינו לוקה.\u0004 ומסבירים את טעמיהם: \u0003ריש לקיש אמר לוקה,\u0004 משום שנאמר \u0003\"בכל קדש לא תגע\"\u0004 (ויקרא יב, ד). \u0003ור' יוחנן אמר אינו לוקה,\u0004 שכן \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \u0003בתרומה כתיב\u0004 \u0005[נאמר],\u0006 ולא בקודש.","ושואלים: \u0003וריש לקיש,\u0004 האם סבור הוא כי \u0003האי קרא להכי הוא דאתא\u0004 \u0005[פסוק זה לזה הוא שבא]?\u0006 \u0003האי מיבעי ליה\u0004 \u0005[זה נצרך לו]\u0006 ל\u0003אזהרה ל\u0004מי שהוא טמא ה\u0003אוכל בשר קודש!\u0004 \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003אזהרה לאוכל בשר קודש מנין? ריש לקיש אמר:\u0004 נאמר \u0003\"בכל קדש לא תגע\"\u0004 (ויקרא יב, ד), וכאשר יבואר להלן הכוונה היא לאכילה.","\u0003ר' יוחנן אמר: תני\u0004 \u0005[שנה]\u0006 החכם \u0003ברדלא, אתיא\u0004 \u0005[באה,\u0006 נלמדה\u0005]\u0006 הלכה זו בגזירה שווה \u0003\"טומאתו\" \"טומאתו\" מביאת מקדש,\u0004 שגם באוכל קודש בטומאה נזכרה המלה \"טומאתו\" (ויקרא ז, כ), וגם בביאת מקדש בטומאה (במדבר יט, יג), ובשניהם יש עונש כרת, \u0003מה להלן\u0004 בביאת מקדש \u0003ענש\u0004 (כרת) \u0003ו\u0004גם \u0003הזהיר\u0004 שיש מצות לא תעשה על כך, \u0003אף כאן\u0004 באכילת קודש בטומאה \u0003ענש ו\u0004גם \u0003הזהיר.\u0004 הרי שלדעת ריש לקיש נאמר איסור זה לענין אכילה!","ומשיבים: לדעת ריש לקיש נלמדים שני הדברים מפסוק זה, \u0003טמא שנגע בקודש\u0004 נלמד \u0003מדאפקה רחמנא\u0004 \u0005[מ\u0006מה \u0005שהוציאה התורה\u0006 את הדבר\u0005]\u0006 \u0003בלשון נגיעה,\u0004 ואילו \u0003אזהרה לאוכל\u0004 נלמדה \u0003מדאיתקש\u0004 \u0005[מ\u0006מה \u0005שהוקשה]\u0006 אכילת \u0003קודש\u0004 בטומאה כניסה \u0003למקדש\u0004 (\"בכל קודש לא תגע ואל המקדש לא תבוא\").","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003ריש לקיש: \"בכל קדש לא תגע\"\u0004 — \u0003אזהרה לאוכל\u0004 קודש בטומאה. \u0003אתה אומר\u0004 שזוהי \u0003אזהרה לאוכל, או אינו אלא לנוגע?\u0004","\u0003תלמוד\u0004 \u0003לומר: \"בכל קדש לא תגע ואל המקדש לא תבא\", מקיש\u0004 (משוה) הכתוב \u0003קודש\u0004 \u0003למקדש, מה\u0004 איסור ביאה ל\u0003מקדש\u0004 הריהו \u0003דבר שיש בו\u0004"],["\u0003נטילת נשמה\u0004 שיש בו עונש כרת, \u0003אף קודש\u0004 שמדובר עליו בפסוק זה הוא ב\u0003דבר שיש בו נטילת נשמה. ואי\u0004 \u0005[ואם]\u0006 \u0003בנוגע\u0004 בלבד, \u0003נטילת נשמה מי איכא\u0004 \u0005[האם יש]?\u0006 \u0003אלא\u0004 מדובר \u0003באכילה\u0004 שבה יש עונש כרת על האוכל בטומאה.","ושואלים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נצרך לו]\u0006 פסוק זה \u0003לטמא שאכל בשר קודש לפני זריקה\u0004 של דם הקרבן על המזבח, כשעדיין אינו מותר באכילה! \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שחלקו בבעיה הבאה: \u0003טמא שאכל בשר קודש לפני זריקה, ריש לקיש אמר: לוקה\u0004 על כך, \u0003ור' יוחנן אמר: אינו לוקה.\u0004","\u0003ריש לקיש אמר: לוקה,\u0004 שנאמר \u0003\"בכל קדש לא תגע\"\u0004 (ויקרא יב, ד) \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם נגע \u0003לפני זריקה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003לאחר זריקה,\u0004 שבכל מקרה הוא מוזהר מן התורה. \u0003ר' יוחנן אמר אינו לוקה,\u0004 כי לשיטתו האיסור לטמא לאכול בשר קודש נלמד \u0003כדתני\u0004 \u0005[כמו ששנה]\u0006 החכם \u0003ברדלא: אתיא\u0004 \u0005[באה,\u0006 נלמדה\u0005]\u0006 האזהרה בגזירה שווה \u0003\"טומאתו\" \"טומאתו\"\u0004 (ויקרא ז, כ. במדבר יט, יג), כמבואר בעמוד הקודם. \u0003וכי כתב ההוא\u0004 \u0005[וכאשר נאמר אותו\u0006 מקרא\u0005]\u0006 (\"טומאתו\") — הרי זה דווקא בבשר המותר באכילה, \u0003לאחר זריקה!\u0004","ומשיבים: לדעת ריש לקיש, \u0003אם כן\u0004 שמדובר בכתוב זה באכילת בשר לאחר זריקה, \u0003לימא קרא\u0004 \u0005[שיאמר המקרא]\u0006 רק \u0003\"בקדש\u0004 לא תגע\", \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 לשון הריבוי \u0003\"בכל קדש\"? שמע מינה תרתי\u0004 \u0005[למד מכאן שתים],\u0006 שבא לרבות בשר קודש לפני זריקה.","\u0003גופא\u0004 \u0005[\u0006ודנים \u0005לגופה]\u0006 של אותה מחלוקת שהזכרנו קודם: \u0003טמא שאכל בשר קודש לפני זריקה, ריש לקיש אמר: לוקה, ר' יוחנן אמר: אינו לוקה. אמר אביי: מחלוקת\u0004 זו היא \u0003בטומאת הגוף\u0004 של האוכל, \u0003אבל בטומאת בשר,\u0004 אם היה הבשר טמא — \u0003דברי הכל לוקה,\u0004 ש","\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"והבשר אשר יגע בכל טמא לא יאכל... והבשר\" (ויקרא ז, יט), ודרשו חכמים: \u0003\"והבשר\"\u0004 — \u0003לרבות עצים ולבונה, דלאו\u0004 \u0005[שלא]\u0006 \u0003בני אכילה נינהו\u0004 \u0005[הם],\u0006 \u0003ואפילו הכי רבינהו קרא\u0004 \u0005[ואפילו כך ריבה אותם המקרא],\u0006 שהם מקבלים טומאה, והאוכלם בטומאת הגוף לוקה, ובודאי נכנס בריבוי זה גם בשר לפני זריקה, שהוא ראוי לאכילה.","\u0003ורבא אמר: מחלוקת\u0004 זו היא \u0003בטומאת הגוף, אבל בטומאת בשר\u0004 — \u0003דברי הכל אינו לוקה, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון דלא קרינא ביה\u0004 \u0005[שאין אנו קוראים בו]\u0006 בבשר שלפני זריקה את הכתוב: \"והנפש אשר תאכל בשר מזבח השלמים... \u0003וטומאתו עליו\u0004 \u0003ונכרתה\"\u0004 (ויקרא ז, כ) שהוא נאמר רק בבשר הראוי להיאכל, \u0003לא קרינא ביה\u0004 \u0005[אין אנו קוראים בו]\u0006 גם את האיסור \u0003\"והבשר אשר יגע בכל טמא לא יאכל\"\u0004 (ויקרא ז, יט).","ומקשים על דברי רבא: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003\"והבשר\"\u0004 (ויקרא ז,יט) — \u0003לרבות עצים ולבונה\u0004 שנטמאו, שאסורים באכילה בטומאה, למרות שאינם ראויים לאכילה, וכל שכן בשר לפני זריקת הדם!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בעצים ולבונה, שחייבים עליהם משום טומאה, \u0005במה אנו עוסקים]\u0006 — \u0003כגון שקדשו בכלי,\u0004 וטעם הדבר — ש\u0003נעשה\u0004 אז \u0003כמי שקרבו כל מתיריו,\u0004 כגון בשר לאחר זריקת הדם, שרק מאותה שעה חייבים על אכילתו.","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל שיש לו מתירים\u0004 כגון בשר הקרבן, שהדם מתירו להקרבה ולאכילה, חייבים עליו משום טומאה \u0003משקרבו מתיריו, כל שאין לו מתירין\u0004 כגון הקומץ והלבונה, שהם מתירים את שיירי המנחה באכילה — חייבים על אכילתו בטומאה \u0003משקדש בכלי.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה הבאה: \u0003המעלה אברי בהמה טמאה על גבי המזבח, ריש לקיש אמר: לוקה\u0004 על כך, \u0003ר' יוחנן אמר: אינו לוקה.\u0004 ומסבירים את טעמיהם: \u0003ריש לקיש אמר לוקה,\u0004 כי בכתוב נאמר שיש מצות עשה להקריב קרבן מן הבקר ומן הצאן (ויקרא א, ב), שהם בכלל בהמה טהורה. ויש לדייק: בהמה \u0003טהורה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003טמאה\u0004 — \u0003לא, ולאו הבא מכלל עשה לוקין עליו. ור' יוחנן אמר אין לוקין עליו,\u0004 כי \u0003לאו הבא מכלל עשה אין לוקין עליו.\u0004","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003ר' ירמיה\u0004 על דברי ריש לקיש, ממה ששנינו בברייתא לענין אחר: נאמר \"כל מפרסת פרסה ושוסעת שסע... בבהמה \u0003אתה תאכלו\"\u0004 (ויקרא יא, ג) — \u0003ולא בהמה טמאה, ולאו הבא מכלל עשה\u0004 — \u0003עשה\u0004 הוא!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב לר' ירמיה בר תחליפא, אסברא\u0004 \u0005[אסביר]\u0006 \u0003לך: באברי בהמה טמאה\u0004 שהעלה על המזבח — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שאינו לוקה, שהרי עשה הוא. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בחיה,\u0004 אם מעלה בשר חיה טהורה על גבי המזבח. \u0003והכי איתמר\u0004 \u0005[וכך נאמר]:\u0006 \u0003ר' יוחנן אמר: עובר בעשה, ריש לקיש אמר: אינו עובר בולא כלום.\u0004","וטעמיהם, \u0003ר' יוחנן אמר עובר בעשה,\u0004 כי התורה ציותה: \u0003בהמה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 תקריבו, ומכאן יש ללמוד: \u0003חיה\u0004 — \u0003לא,\u0004 ולאו הבא מכלל עשה — עשה. \u0003ריש לקיש אמר אינו עובר עליו בולא כלום,\u0004 שכן \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 שנאמר בו שמקריבים מן הבקר ומן הצאן הוא \u0003למצוה,\u0004 שכך צריך לעשות, אבל אין ללמוד מכאן שאם מקריבים חיה יש בכך עבירה.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: \u0003אילו נאמר\u0004 רק \"אדם כי יקריב מכם \u0003קרבן לה'\u0004 מן ה\u0003בהמה\"\u0004 (ויקרא א, ב), \u0003הייתי אומר:\u0004 אף \u0003חיה\u0004 היא \u0003בכלל בהמה, כענין שנאמר: \"זאת הבהמה אשר תאכלו שור שה כשבים ושה עזים איל וצבי\" וגו'\u0004 (דברים יד ד—ה), הרי שבכלל \"הבהמה\" נכללות גם חיות, כגון איל וצבי, על כן \u0003תלמוד לומר:\u0004 \"מן הבהמה, מן ה\u0003בקר ו\u0004מן ה\u0003צאן\"\u0004 (ויקרא א, ב) — \u0003בקר וצאן אמרתי לך\u0004 להביא מן הבהמה, \u0003ולא חיה.\u0004","\u0003יכול לא יביא\u0004 חיה לכתחילה, \u0003ואם הביא כשר? הא למה זה דומה\u0004 לכאורה — \u0003לתלמיד שאמר לו רבו: \"הבא לי חטים\", והביא לו חטים ושעורים, שאינו כמעביר\u0004 (כעובר) \u0003על דבריו אלא מוסיף על דבריו, ו\u0004הרי זה \u0003כשר?\u0004","\u0003תלמוד לומר\u0004 בהמשך שוב: \u0003\"בקר וצאן\"\u0004 (\"מן הבקר... מן הצאן\", ויקרא פסוקים ג, י) לחזור ולהדגיש: \u0003בקר וצאן\u0004 דוקא \u0003אמרתי לך, ולא חיה. הא\u0004 \u0005[הרי]\u0006 \u0003למה זה דומה? לתלמיד שאמר לו רבו: אל תביא לי אלא חיטין, והביא לו חיטין ושעורים, שאינו כמוסיף על דבריו אלא כמעביר על דבריו\u0004 שהרי אמר לו שלא יביא לו אלא חיטים."],["\u0003ופסול\u0004 משום כך. ואם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003ריש לקיש!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ונדחו דבריו.","שנינו במשנה: \u0003וכולן\u0004 כל הפסולים לעבודה \u0003שקיבלו\u0004 את הדם חוץ לזמנו וחוץ למקומו, אם נותר דם הנפש בבהמה — יחזור הכשר ויקבל את הדם. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ריש לקיש מר' יוחנן: פסול\u0004 שזרק את הדם, \u0003מהו שיעשה\u0004 את הדם שנותר בבהמה \u0003שירים\u0004 של דם שנזרק, שאינם ראויים עוד לזריקה. או שמא מה שעשה הפסול אינו נחשב כזריקה, ויחזור ויזרוק?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 זריקה פסולה \u0003עושה שירים אלא\u0004 כשזורק (כהן כשר) את הדם במחשבת \u0003חוץ לזמנו וחוץ למקומו, הואיל ו\u0004הוא \u0003מרצה\u0004 כלומר, הואיל והיא נחשבת כזריקה \u0003ל\u0004ענין \u0003פיגולו.\u0004","ואילו \u0003רב זביד מתני הכי\u0004 \u0005[היה שונה\u0006 את הענין \u0005הזה כך],\u0006 \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ריש לקיש מר' יוחנן: כוס\u0004 של דם \u0003פסול,\u0004 כגון שיצא חוץ לעזרה, ועבר וזרקו, \u0003מהו שיעשה\u0004 את הדם שנותר בבהמה \u0003שירים\u0004 שאינם ראויים עוד לזריקה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003פסול גופיה\u0004 \u0005[עצמו]\u0006 שזרק את הדם \u0003מאי סבירא לך\u0004 \u0005[מה אתה סבור]\u0006 בדינו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003פסול\u0004 שזרק את הדם \u0003משוי\u0004 \u0005[עושה]\u0006 \u0003שירים\u0004 — \u0003כוס פסול נמי משוי\u0004 \u0005[גם כן עושה]\u0006 \u0003שירים, אי\u0004 \u0005[אם]\u0006 \u0003פסול לא משוי\u0004 \u0005[אינו עושה]\u0006 \u0003שירים, כוס פסול נמי לא משוי\u0004 \u0005[גם כן אינו עושה]\u0006 \u0003שירים!\u0004","ואילו \u0003רב ירמיה מדיפתי מתני הכי\u0004 \u0005[\u0006היה \u0005שונה כך],\u0006 \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אביי מרבה:\u0004 אם קיבל הדם ביותר מכוס אחד, והשלים באחד מהם את זריקת הדם על קרנות המזבח, אותו \u0003כוס מהו שיעשה את חבירו, דחוי\u0004 לגמרי, ונשפך לאמה העוברת בעזרה, \u0003או שירים\u0004 שמצוה לשופכם על יסוד המזבח?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 דבר זה \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' אלעזר בר' שמעון ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין שיירי דם חטאת החיצונה: \u0003למעלה,\u0004 בחטאת הנשיא, \u0003הוא אומר: \"את דמו ישפך\u0004 על יסוד מזבח העולה\" (ויקרא ד, כה), \u0003למטה\u0004 בחטאת יחיד \u0003הוא אומר: \"ואת כל דמה ישפך\u0004 אל יסוד המזבח\" (ויקרא ד, לד), ויש כאן הדגשה — \"כל דמה\".","וכך יש להבין את שני הכתובים: \u0003מנין לחטאת שקיבל דמה בארבעה כוסות ונתן מתנה אחת\u0004 על המזבח \u0003מ\u0004כוס \u0003זה ומתנה אחת מ\u0004כוס \u0003זה,\u0004 על כל אחת מקרנות המזבח, מנין \u0003ש\u0004שיירי כל הכוסות \u0003כולן נשפכין ליסוד? תלמוד לומר: \"ואת כל דמה ישפך\".\u0004","\u0003יכול\u0004 אם \u0003נתן ארבע מתנות\u0004 של החטאת \u0003מכוס אחד יהו כולן,\u0004 כל שאר הכוסות, \u0003נשפכין ליסוד? תלמוד לומר: \"ואת דמו\"\u0004 ולא \"כל דמו\", \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד? הוא,\u0004 אותו דם בכוס שהיזו ממנו כדין — \u0003נשפך ליסוד, והן,\u0004 שאר הכוסות — דחויים הם ו\u0003נשפכין לאמה\u0004 (לתעלה העוברת בעזרה).","\u0003ר' אלעזר בר' שמעון אומר: מנין לחטאת שקיבל דמה בארבעה כוסות ונתן ארבע מתנות מכוס אחד, שכולן נשפכין ליסוד? תלמוד לומר: \"ואת כל דמה ישפך\".\u0004 ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואת דמו ישפך\",\u0004 ומשמע — לא כל דמו! \u0003אמר רב אשי:\u0004 \u0003ההוא למעוטי\u0004 \u0005[אותו\u0006 כתוב בא \u0005למעט]\u0006 \u0003שירים שבצואר בהמה,\u0004 שלא נתקבלו כלל בכלי כדי לזורקם, והוא אינו נשפך ליסוד, אלא לאמה.","שנינו במשנה שלושה מקרים דומים: \u0003קיבל הכשר\u0004 את הדם \u0003ונתן לפסול\u0004 — יחזיר לכשר ויזרוק. קיבל בימינו ונתן לשמאלו — יחזיר לימינו. קיבל בכלי קודש ונתן לכלי חול — יחזיר לכלי קודש.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שיאמרו כל המקרים הללו, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק כשנתן ל\u0003פסול, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פסול\"\u0004 כאן? \u0003טמא,\u0004 שאינו דחוי לגמרי, \u0003דחזי\u0004 \u0005[ש\u0006הרי הוא \u0005ראוי]\u0006 \u0003לעבודת ציבור,\u0004 ולכן אין הדם נפסל בכך, \u0003אבל\u0004 אם נתן ל\u0003שמאל\u0004 שאינו ראוי בשום אופן לקבלת הדם והולכתו — \u0003לא.\u0004","\u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 גם בנותן ליד \u0003שמאל\u0004 שיחזיר לימין ויזרוק, היינו אומרים שהוא משום \u0003דאית ליה הכשירא\u0004 \u0005[שיש לו הכשר]\u0006 \u0003ביום הכיפורים,\u0004 שהכהן הגדול מכניס את כף הקטורת בשמאל, \u0003אבל כלי חול\u0004 — \u0003לא.\u0004","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק בנותן ל\u0003כלי חול,\u0004 שאין הדם נפסל בו \u0003משום דחזו לקדושינהו\u0004 \u0005[שראויים\u0006 כלים אלה \u0005לקדש אותם]\u0006 ולעשותם כלי שרת, \u0003אבל הנך\u0004 \u0005[האחרים],\u0006 פסול ושמאל, שאין אפשרות להכשירם — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כולם.","ולגופו של דין המשנה שואלים: \u0003וליהוי ליה\u0004 \u0005[ושיהיה\u0006 הדם נחשב\u0005]\u0006 כ\u0003דחוי\u0004 לאחר שנתקבל ביד הפסול, או בשמאל או בכלי חול! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ירמיה מדיפתי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כדעת \u0003חנן המצרי הוא, דלית ליה\u0004 \u0005[שאין לו]\u0006 כלל דין \u0003דחויין,\u0004 שקרבן שנדחה לשעתו אינו נדחה לגמרי.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003חנן המצרי אומר:\u0004 אם אבד השעיר המשתלח ביום הכיפורים, \u0003אפילו\u0004 היה ה\u0003דם\u0004 של בן זוגו, המוקרב לה', \u0003בכוס\u0004 — אין אותו דם נדחה, אלא \u0003מביא חבירו\u0004 (שעיר אחר להשתלח) \u0003ומזווג לו\u0004 להיות בן זוגו, וזורק את הדם כראוי.","\u0003רב אשי אמר\u0004 הסבר אחר למשנתנו: \u0003כל שבידו\u0004 לתקן \u0003לא הוי\u0004 \u0005[אין זה\u0006 נקרא\u0005]\u0006 \u0003דחוי,\u0004 והרי מדובר כאן כשחוזרים ומקבלים את הדם כראוי.","\u0003אמר רב שייא: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב אשי מסתברא\u0004 \u0005[מסתבר],\u0006 שכן \u0003מאן שמעת ליה דאית ליה\u0004 \u0005[מי שמעת אותו שיש לו,\u0006 שהוא סבור\u0005]\u0006 דין \u0003דחויין? ר' יהודה, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ועוד אמר ר' יהודה:\u0004 אם \u0003נשפך הדם\u0004 של השעיר המוקרב לה' מן הכוס — \u0003ימות המשתלח,\u0004 וכן אם \u0003מת המשתלח\u0004 — \u0003ישפך הדם.\u0004 הרי שסבור הוא שהשעיר המשתלח, או במקרה ההפוך — דם השעיר לה', נדחה לגמרי.","\u0003ושמעינן ליה דאמר\u0004 \u0005[ושמענו אותו ש\u0006הוא \u0005אומר]:\u0006 \u0003כל\u0004 דבר \u0003שבידו לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003דחוי, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 לאחר שנשחטו קרבנות הפסח בעזרה, \u0003כוס אחד היה ממלא מדם התערובת\u0004 שעל הרצפה, \u0003וזורקו זריקה אחת\u0004 על המזבח \u0003כנגד היסוד,\u0004 כדינו של קרבן פסח, שאם נשפך דמו של אחד מהם מן הכלי לרצפה, יוכשר בדרך זו. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שלמרות שנשפך הדם מן הכלי בתחילה, \u0003כל שבידו לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003דחוי.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של הדבר שהזכרנו קודם: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: כוס אחד היה ממלא מדם התערובת, שאם ישפך אחד מהם,\u0004 מן הכוסות שקיבלו בהם את דם הפסחים, \u0003נמצא שהוא מכשירו. אמרו לו לר' יהודה: והלא\u0004 דם זה של התערובת \u0003לא נתקבל בכלי!\u0004 ושואלים: \u0003מנא ידעי\u0004 \u0005[מנין יודעים]\u0006 חכמים שלא נתקבל? שמא נתקבל ונשפך מן הכלי! \u0003אלא\u0004 כך צריך לומר: הרי ספק הוא, \u0003שמא לא נתקבל בכלי! אמר להן:\u0004"],["\u0003אף אני לא אמרתי\u0004 שייזרק הדם \u0003אלא כשנתקבל בכלי.\u0004 ושואלים: \u0003והוא גופיה\u0004 \u0005[עצמו],\u0006 ר' יהודה, \u0003מנא ידע\u0004 \u0005[מנין\u0006 הוא \u0005יודע]\u0006 אם התקבל או לא? ומשיבים: הוא סומך על כך ש\u0003כהנים זריזין\u0004 הם, משתדלים לעשות עבודתם כראוי, ומקבלים כל הדם, \u0003ועבדין הייא\u0004 \u0005[ו\u0006אולם \u0005עושים במהירות]\u0006 \u0003ו\u0004כך \u0003משתפכין\u0004 הדמים מן הכלי.","ומקשים: \u0003והלא דם התמצית\u0004 (שמתמצה מן הצואר, לאחר שיצא דם הנפש) \u0003מעורב בו\u0004 בדם זה של התערובת, ואין זורקים תערובת כזו על המזבח! ומשיבים: \u0003ר' יהודה לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר: דם התמצית\u0004 \u0003קרי\u0004 \u0005[קרוי]\u0006 \u0003דם,\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003דם התמצית\u0004 הרי הוא \u0003באזהרה\u0004 שאם אוכל אותו עובר בלא תעשה, \u0003ר' יהודה אומר: בכרת,\u0004 כדם הנפש.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: מודה ר' יהודה לענין כפרה\u0004 על המזבח, \u0003ש\u0004דם התמצית \u0003אינו מכפר, שנאמר: \"כי הדם הוא (הנפש)\u0004 (בנפש) יכפר\" (ויקרא יז, יא), לומר:","\u0003דם שהנפש יוצאה בו קרוי דם, שאין הנפש יוצאה בו אין קרוי דם.\u0004 הרי שאף לדעת ר' יהודה אין דם התמצית ראוי לזריקה!","\u0003אלא\u0004 צריך לומר ש\u0003ר' יהודה\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו],\u0006 ש\u0003אמר: אין דם מבטל דם,\u0004 ולכן אין דם התמצית מבטל את הדם שנתקבל בכלי.","ושבים לברייתא, \u0003אמר להם ר' יהודה: לדבריכם,\u0004 שאי אפשר להשתמש בדם התערובת, \u0003למה פוקקין\u0004 \u0003העזרה\u0004 שתתמלא דם, ולא נותנים לדם לצאת דרך האמה? \u0003אמרו לו: שבח הוא לבני אהרן שיהלכו עד\u0004 \u0003ארכובותיהן\u0004 (קרסוליהם) \u0003בדם.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003דם הוי\u0004 \u0005[הריהו]\u0006 \u0003חציצה\u0004 בין רגליהם לרצפת העזרה! ומשיבים: דם זה \u0003לח הוא, ולא הוי\u0004 \u0005[ואינו]\u0006 \u0003חציצה, דתנן\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הדם, והדיו, והדבש, והחלב\u0004 אם היו \u0003יבישין\u0004 — \u0003חוצצין,\u0004 אם היו \u0003לחין\u0004 — \u0003אין חוצצין.\u0004","ומקשים: \u0003והא קא מיתווסי מאנייהו\u0004 \u0005[והרי מתלכלכים בגדיהם\u0006 בדם\u0005],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 אם \u0003היו בגדיו\u0004 של הכהן \u0003מטושטשין\u0004 (מלוכלכים) \u0003ועבד\u0004 — \u0003עבודתו פסולה! וכי תימא דמדלו להו\u0004 \u0005[ואם תאמר שמרימים אותם\u0006 את הבגדים\u0005],\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \"ולבש הכהן \u0003מדו\u0004 בד\" (ויקרא ו, ג) משמע שצריך הבגד להיות \u0003כמדתו,\u0004 \u0003שלא יחסר ושלא יותיר!\u0004 ומשיבים: מה שהכהנים הולכים ורגליהם בדם הרי זה \u0003בהולכת אברים לכבש, דלאו\u0004 \u0005[שלא]\u0006 \u0003עבודה היא.\u0004","ושואלים: \u0003ולא\u0004 עבודה היא? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר \u0003\"והקריב הכהן את הכל\u0004 והקטיר המזבחה\" (ויקרא א, יג) — \u0003זו הולכת אברים לכבש! אלא\u0004 יש לומר שמהלכים בדם \u0003בהולכת עצים למערכה, דלאו\u0004 \u0005[שלא]\u0006 \u0003עבודה היא.\u0004 ושואלים: \u0003ולעבודה\u0004 ממש \u0003היכי אזלי\u0004 \u0005[כיצד\u0006 הם \u0005הולכים]?\u0006 הרי העזרה מלאה בדם! ומשיבים: \u0003אזלי אאיצטבי\u0004 \u0005[הולכים\u0006 הם \u0005על אצטבאות],\u0006 על מקומות מוגבהים שברצפה שאין הדם מגיע לשם.","\u0003השוחט את הזבח\u0004 על מנת \u0003לאכול\u0004 חוץ לזמנו או חוץ למקומו \u0003דבר שאין דרכו לאכול\u0004 כגון אימורים, או \u0003להקטיר דבר שאין דרכו להקטיר\u0004 כגון בשר — הרי זה \u0003כשר,\u0004 משום שמחשבת פסול לא היתה על דבר הראוי לעניינו, \u0003ור' אליעזר פוסל.\u0004","אם שחט על מנת \u0003לאכול דבר שדרכו לאכול, ולהקטיר דבר שדרכו להקטיר,\u0004 אבל \u0003פחות מכזית\u0004 — \u0003כשר.\u0004 על מנת \u0003לאכול כחצי זית ולהקטיר כחצי זית\u0004 חוץ לזמנו או חוץ למקומו — \u0003כשר, שאין אכילה\u0004 \u0003והקטרה מצטרפין.\u0004","\u0003השוחט את הזבח\u0004 על מנת \u0003לאכול כזית מן העור ומן הרוטב, ומן הקיפה\u0004 התבלין המצטבר בשולי הקדירה ויש עמו מעט בשר, \u0003ומן האלל\u0004 (גיד הצוואר), \u0003ומן העצמות ומן הגידין, ומן הקרנים ומן הטלפים\u0004 (פרסות), \u0003חוץ לזמנו וחוץ למקומו\u0004 — \u0003כשר,\u0004 משום שאין הם נחשבים דבר הנאכל, \u0003ו\u0004משום כך גם \u0003אין חייבין עליהן\u0004 כולם \u0003משום\u0004 אכילת \u0003פיגול\u0004 אם חישב על הזבח מחשבת חוץ לזמנו, \u0003ו\u0004משום אכילת \u0003נותר, ו\u0004אינו חייב על אכילתם אם היה \u0003טמא.\u0004","\u0003השוחט את המוקדשין\u0004 (זבחים נקבות) על מנת \u0003לאכול שליל\u0004 (עובר) של אותה בהמה \u0003או שיליא\u0004 של הבהמה \u0003בחוץ\u0004 — \u0003לא פיגל\u0004 את הזבח על ידי כך. \u0003המולק את התורין\u0004 על מנת \u0003לאכול ביציהן\u0004 המצויים עדיין בגופם, \u0003בחוץ\u0004 — \u0003לא פיגל,\u0004 שאין הביצים נחשבות חלק מגוף התורים, ומאותה סיבה","\u0003חלב\u0004 של ה\u0003מוקדשין וביצי תורין אין חייבין עליהן\u0004 כרת \u0003משום\u0004 אכילת \u0003פיגול ונותר וטמא.\u0004","\u0003אמר ר' אלעזר:\u0004 אם \u0003פיגל בזבח\u0004 ששחטו על מנת לאוכלו לאחר זמנו — \u0003נתפגל\u0004 גם \u0003השליל\u0004 (העובר שבמעי הבהמה) ואם אכלו — חייב על כך משום פיגול. אבל אם פיגל \u0003בשליל\u0004 — \u0003לא נתפגל הזבח.\u0004 וכן אם \u0003פיגל באלל\u0004 (גיד הצואר) של עוף, שראוי לאכילה — \u0003נתפגלה\u0004 גם ה\u0003מוראה\u0004 (זפק) הדבוקה לו, אף שאינה נחשבת כדבר הנאכל, משום שיש אנשים האוכלים אותה. אבל אם פיגל \u0003במוראה לא נתפגל אלל.\u0004","אם \u0003פיגל באימורין\u0004 של פרים הנשרפים, ששחט על מנת להקטירם לאחר זמנם — \u0003נתפגלו\u0004 ה\u0003פרים\u0004 כולם, שאף האוכל את בשרם חייב משום פיגול. אבל אם פיגל \u0003בפרים\u0004 שחשב לאוכלם לאחר זמנם, הואיל ואין בהם פיגול, שהרי אינם עומדים לא להקטרה ולא לאכילה — \u0003לא נתפגלו אימורים.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003ושוים,\u0004 גם האומרים שיש פיגול בפרים הנשרפים, \u0003שאם חישב\u0004 מחשבת חוץ לזמנו \u0003באכילת פרים ובשריפתן\u0004 — \u0003לא עשה ולא כלום\u0004 שפרים אלו אינם נאכלים, ואין מחשבת פיגול אלא באכילה והקטרה, אבל לא בשריפה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003חישב באימורים\u0004 של אותם פרים מחשבת חוץ לזמנו, שיקטירם למחר — \u0003נתפגלו פרים,\u0004 וכדברי ר' אלעזר? ודוחים: \u0003לא,\u0004"],["דייק כך: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003חישב באימורין\u0004 להקטירם למחר — \u0003נתפגלו אימורין עצמן\u0004 וחייב על אכילתם משום פיגול, אבל בשר הפרים בכל מקרה אינו מתפגל.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003פרים הנשרפים ושעירים הנשרפים מועלין בהן\u0004 כלומר, הנהנה מהם חייב משום מעילה \u0003מ\u0004שעה \u0003שהוקדשו,\u0004 ולאחר ש\u0003נשחטו\u0004 — \u0003הוכשרו ליפסל ב\u0004נגיעה של \u0003טבול יום, וב\u0004נגיעה של \u0003מחוסר כיפורים, ובלינה\u0004 אם עבר עליהם הלילה ולא נעשתה מצוותם.","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003לינת בשר\u0004 שאף בשרם נפסל בלינה? \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 לענין פיגול, שהרי \u0003מגו דפסלה\u0004 \u0005[מתוך שפוסלת]\u0006 \u0003בלינה, פסלה\u0004 \u0005[פוסלת]\u0006 \u0003בה\u0004 בבשר גם \u0003מחשבה\u0004 של לינה, וחל עליו דין פיגול, כדברי ר' אלעזר!","ודוחים: \u0003לא,\u0004 הכוונה היא לפסול של \u0003לינת אימורים\u0004 ולא בשר, וגם מחשבה מפגלת דווקא את האימורים. ומקשים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנה בסוף\u0006 אותה משנה\u0005]:\u0006 \u0003כולן מועלין בהן על בית הדשן,\u0004 שהוא מקום שריפתם, \u0003עד שיותך הבשר\u0004 כלומר, עד שיישרף לגמרי, \u0003מכלל דרישא\u0004 \u0005[שבראש\u0006 המשנה\u0005]\u0006 גם כן ב\u0003לינת בשר\u0004 מדובר! ודוחים: \u0003מידי איריא\u0004 \u0005[כלום שייך\u0006 הדבר\u0005]?\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כמו שהוא וזה כמו שהוא],\u0006 \u0003רישא\u0004 \u0005[בראש]\u0006 מדובר ב\u0003אימורים, וסיפא\u0004 \u0005[ובסוף]\u0006 מדובר ב\u0003בשר.\u0004","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על שיטת ר' אלעזר ממה ששנינו בברייתא: \u0003ואלו שאין מפגלין ואין מתפגלין: צמר שבראשי כבשים,\u0004 \u0003ושער שבזקן תיישים, והעור והרוטב והקיפה, והאלל והמוראה והעצמות, והגידין והקרנים והטלפים, והשליל והשיליא, וחלב המוקדשין וביצי תורין\u0004 —","\u0003[כולן] לא מפגלין ולא מתפגלין, ואין חייבין עליהן משום פיגול\u0004 או \u0003נותר\u0004 או \u0003טמא, והמעלה מהן בחוץ\u0004 — \u0003פטור,\u0004 שאין הם קרבים על גב המזבח.","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שכולם \u0003לא מפגלין\u0004 את \u0003הזבח\u0004 אם חשב לאוכלם חוץ לזמנם, \u0003ו\u0004גם \u0003לא מתפגלין מחמת זבח?\u0004 ובכלל זה שליל ושיליא, ושלא כדברי ר' אלעזר שאמר שהזבח מפגל אותם!","ודוחים: \u0003לא,\u0004 הכוונה היא ש\u0003לא\u0004 הם \u0003מפגלין את הזבח, ולא מתפגלין מחמת עצמן,\u0004 כלומר שאם חישב לאוכלם חוץ לזמנו — גם הם אינם נאסרים משום פיגול. אבל הזבח מפגל אותם. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003הא דקתני סיפא\u0004 \u0005[זה ששנה\u0006 ב\u0005סוף]\u0006 פעם נוספת: \u0003כולן לא מפגלין ולא מתפגלין, הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי,\u0004 אם לא בא להוסיף שאין מתפגלים גם מחמת הזבח?","ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מדייק מתוספת הדברים, מה שנאמר פעם שלישית: \u0003אין חייבין עליו משום פיגול, הא תו\u0004 \u0005[זה עוד]\u0006 \u0003למה לי? אלא\u0004 חייב אתה להסביר שאין זה בא לחדש דין נוסף, אלא \u0003איידי דבעי למיתנא\u0004 \u0005[מתוך שרצה לשנות]\u0006 שאין חייבים עליהם משום \u0003נותר וטמא, תנא\u0004 \u0005[שנה]\u0006 בדרך אגב גם \u0003פיגול,\u0004","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לפרש באופן זה: \u0003איידי דבעי למיתני\u0004 \u0005[מתוך שרצה לשנות]\u0006 את הדין ש\u0003המעלה מהן בחוץ\u0004 פטור, \u0003תנא נמי\u0004 \u0005[שנה גם כן]:\u0006 \u0003וכולן לא מפגלין ולא מתפגלין.\u0004 ובאמת הזבח מפגל אותם, וכדברי ר' אלעזר.","\u0003רבא אמר: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנתנו כדברי ר' אלעזר: \u0003השוחט את המוקדשים לאכול שליל או שיליא בחוץ\u0004 — \u0003לא פיגל, והמולק את התורים לאכול ביציהם בחוץ\u0004 — \u0003לא פיגל.\u0004","\u0003והדר תני\u0004 \u0005[ו\u0006הוא \u0005חוזר ושונה]:\u0006 \u0003חלב המוקדשין וביצי תורים\u0004 — \u0003אין חייב עליהן משום פיגול נותר וטמא,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 על \u0003שליל ושיליא\u0004 שלא שנו בהם דבר זה — \u0003חייבים\u0004 משום פיגול!","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 ש\u0003כאן מחמת הזבח\u0004 הריהם מתפגלים, \u0003כאן מחמת עצמן\u0004 אם חישב בהם מחשבת חוץ לזמנם — לא פיגל בהם. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","הברייתא שהביא רבה לעיל הוזכרה גם בדיון אחר. וכך \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה להלן, ברשימת הקרבנות הפסולים, שאם עלו למזבח ירדו ממנו: \u0003ובעלי מומין. ר' עקיבא מכשיר בבעלי מומים,\u0004 שלדעתו, אם עלו — לא ירדו.","\u0003אמר\u0004 \u0003ר' חייא בר אבא אמר ר' יוחנן: לא הכשיר ר' עקיבא אלא בדוקין\u0004 (כעין קרומים) \u0003שבעין,\u0004 ובמומים כיוצא בהם שאינם ניכרים, \u0003הואיל וכשירים בעופות.\u0004 ועוד תנאי יש בענין זה: \u0003והוא, שקדם הקדישה\u0004 \u0003את מומה\u0004 שכשהקדיש את הבהמה היתה כשרה לגמרי, ואחר כך נפל בה מום. שכיון שחלה עליה קדושת קרבן, אם עלתה לא תרד.","\u0003אמר ר' חייא בר אבא: ומודה ר' עקיבא בעולת נקבה\u0004 כלומר, אם העלה נקבה כקרבן עולה על המזבח, ואין מקריבים עולה אלא מן הזכרים — \u0003דכמאן\u0004 \u0005[שכמי]\u0006 ש\u0003קדם מומה להקדישה דמי\u0004 \u0005[נחשבת],\u0006 שהרי המום מצוי בה מתחילתה, ואם עלתה — תרד.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003ר' זירא\u0004 ממה ששנינו בברייתא לעיל: \u0003המעלה מהן\u0004 כגון מן השליל (העובר) \u0003בחוץ\u0004 — \u0003פטור,\u0004 שאינו ראוי להיות מוקרב על המזבח בפנים. ויש לדייק: \u0003הא\u0004 \u0005[אבל]\u0006 אם היה מעלה \u0003מ\u0004בשר \u0003אימן\u0004 בחוץ היה \u0003חייב, והיכי משכחת לה\u0004 \u0005[ואיך אתה מוצא אותה]?\u0006 רק \u0003ב\u0004בשר \u0003עולת נקבה,\u0004 שהרי בבשר בהמת שלמים (היכולה להיות נקבה) שאינו עולה על המזבח, אלא נאכל — אין חיוב על העלאה בחוץ.","ומעתה, \u0003אי אמרת בשלמא קסבר\u0004 \u0005[נניח אם אתה אומר שסבור]\u0006 \u0003ר' עקיבא\u0004 ב\u0003עולת נקבה\u0004 ש\u0003אם עלתה לא תרד, הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' עקיבא היא,\u0004 כי דבר המוקרב על המזבח, גם בדיעבד, חייבים על העלאתו בחוץ. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 עולת נקבה \u0003אם עלתה תרד\u0004 שאין בה כלל דין הקרבה במזבח, \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006","ואומרים: \u0003אימא\u0004 \u0005[אמור]\u0006 ודייק כך: \u0003המעלה מהן\u0004 משליל \u0003בחוץ\u0004 — \u0003פטור, הא\u0004 \u0005[אבל]\u0006 אם העלה \u0003מאימורי אימן\u0004 — \u0003חייב,\u0004 ודין זה יכול לחול גם על חטאת או שלמים, שבאים גם מן הנקבה ואימוריהם מוקטרים על המזבח.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מהן\" קתני\u0004 \u0005[הוא שונה]\u0006 כלומר, מבשרם ולא מאימוריהן, \u0003ואימן דומיא דידהו\u0004 \u0005[בדומה להם],\u0006 שמעלה את הבשר ולא את האימורים! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003המעלה מאימוריהן בחוץ\u0004 — \u0003פטור, הא\u0004 \u0005[אבל]\u0006 אם היה מעלה \u0003מאימורי אימן\u0004 — \u0003חייב.\u0004","\u0003שחטו\u0004 את הזבח \u0003על מנת להניח את דמו או אימוריו למחר,\u0004 ולא על מנת להקריבם למחר, \u0003או\u0004 על מנת \u0003להוציאן לחוץ\u0004 ולא על מנת להקריבם בחוץ, \u0003ר' יהודה פוסל\u0004 למרות שלא חישב על אכילה או הקטרה חוץ לזמנו או חוץ למקומו, \u0003וחכמים מכשירין.\u0004 אם שחט \u0003על מנת ליתנן\u0004 את הדמים \u0003על גבי הכבש\u0004 שאינו מקום זריקת הדם, והוא פסול שם, או לתת את הדם על קיר המזבח, אבל \u0003שלא כנגד היסוד,\u0004 או \u0003ליתן את\u0004 הדמים \u0003הניתנים למעלן\u0004 בחלקו העליון של המזבח \u0003למטה, ואת הניתנים למטה למעלן, ואת הניתנים\u0004"],["\u0003בפנים\u0004 בתוך ההיכל \u0003בחוץ\u0004 על מזבח העולה, \u0003ו\u0004על מנת לתת \u0003את הניתנין בחוץ בפנים,\u0004 וכן אם שחט על מנת \u0003שיאכלוהו טמאים\u0004 או \u0003שיקריבוהו\u0004 \u0003טמאים,\u0004 או על מנת \u0003שיאכלוהו ערלים\u0004 או \u0003שיקריבוהו ערלים,\u0004 או שאמר שהוא שוחט על מנת \u0003לשבר עצמות הפסח,\u0004 או \u0003לאכול הימנו\u0004 (מן הפסח) \u0003נא,\u0004 או \u0003לערב דמו\u0004 של קרבן \u0003בדם הפסולים\u0004 — בכל אלה, למרות שחשב בעבודת הקרבן לעשות דבר אסור, ואפילו דבר הפוסל את הקרבן — הקרבן \u0003כשר,\u0004","\u0003שאין מחשבה פוסלת\u0004 את הקרבן \u0003אלא ב\u0004מחשבת אכילה או הקטרה \u0003חוץ לזמנו וחוץ למקומו, והפסח והחטאת\u0004 נפסלים במחשבה \u0003שלא לשמן.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 הפוסל במחשבה להניח למחר או להוציא לחוץ? \u0003אמר ר' אלעזר: תרי קראי כתיבי\u0004 \u0005[שני מקראות כתובים]\u0006 \u0003בנותר, כתוב אחד אומר: \"לא תותירו ממנו עד בקר\u0004 והנותר... באש תשרופו\" (שמות יב, י), \u0003וכתוב אחד אומר: \"לא יניח ממנו עד בקר\"\u0004 (ויקרא ז, טו), וכתוב זה הנוסף, \u0003אם אינו ענין\u0004 לעצם האיסור \u0003להניח,\u0004 שכבר נאמר בפסוק אחר, \u0003תנהו לענין מחשבת הינוח\u0004 שלא רק אם הניח בפועל, אלא גם אם חשב לעשות כך הרי הוא פוסל.","ושואלים: \u0003ו\u0004לדעת \u0003ר' יהודה האי קרא להכי הוא דאתא\u0004 \u0005[פסוק זה, לכך הוא שבא]?\u0006 \u0003האי\u0004 \u0003מיבעי ליה לכדתניא\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 נאמר \"ובשר זבח תודת שלמיו ביום קרבנו יאכל לא יניח ממנו עד בקר\", ומן המלים \u0003\"ובשר זבח\u0004 \u0003תודת שלמיו\"\u0004 (ויקרא ז, טו) \u0003למדנו לתודה שנאכלת ליום ולילה.\u0004","\u0003חליפין\u0004 של תודה, וכן \u0003וולדות\u0004 או \u0003תמורות\u0004 של תודה, \u0003מנין\u0004 שאף הם נאכלים ליום ולילה? \u0003תלמוד לומר: \"ובשר\"\u0004 שהוא\"ו בא לרבות. \u0003חטאת ואשם מנין\u0004 שהם נאכלים רק ליום ולילה? \u0003תלמוד לומר: \"זבח\",\u0004 לרבות זבחים אחרים.","\u0003ומנין לרבות\u0004 \u0003שלמי נזיר\u0004 איל שמביא הנזיר בסוף נזירותו \u0003ושלמי פסח? תלמוד לומר: \"שלמיו\"\u0004 בלשון רבים. \u0003לחמי תודה, וחלות ורקיקים שב\u0004קרבן ה\u0003נזיר מנין\u0004 שהם נאכלים ליום ולילה? \u0003תלמוד לומר: \"קרבנו\", כולן קורא אני בהן\u0004 \u0003\"לא יניח\u0004 ממנו עד בקר\". משמע שהפסוק נצרך ללמדנו כמה וכמה הלכות בענין זמן אכילת הקרבנות!","ומשיבים: \u0003אם כן,\u0004 אם רק לצורך זה, \u0003לימא קרא\u0004 \u0005[שיאמר הפסוק]\u0006 \u0003\"לא תותירו\u0004 ממנו עד בקר\" כמו בפסוק האחר, מאי \u0005[מהו]\u0006 \u0003\"לא יניח\"? אם אינו\u0004 \u0003ענין להינוח, תנהו ענין למחשבת הינוח.\u0004","ומקשים על המקור שהביא ר' אלעזר: \u0003התינח\u0004 \u0005[זה נוח]\u0006 להסביר דברי ר' יהודה בענין מי שחשב \u0003להניח\u0004 את האימורים למחר, אבל לפסול כשחשב \u0003להוציא\u0004 לחוץ \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי זה אינו נלמד מכאן!","\u0003ועוד\u0004 יש לטעון כנגד דברי ר' אלעזר: והרי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יהודה סברא הוא\u0004 ולא מן המקרא! \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להם ר' יהודה\u0004 לחכמים: \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתם מודים שאם\u0004 \u0003הניחו למחר שהוא פסול? אף חישב להניחו למחר\u0004 — \u0003פסול.\u0004 ואם כן, ר' יהודה אומר דברו מפני הסברה, שהוא מחשיב מחשבה כמעשה! ומקשים: \u0003אלא\u0004 תאמר כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יהודה סברא הוא,\u0004 ולא מן המקרא? אם כן, \u0003וניפלוג נמי\u0004 \u0005[ושיחלוק גם כן]\u0006 \u0003ר' יהודה בכולהו\u0004 \u0005[בכולם],\u0006 ויפסול אף בשאר המקרים המובאים במשנה מפני אותה סברה!","ודוחים: \u0003בהי ניפלוג\u0004 \u0005[באיזה\u0006 מהם \u0005יחלוק]?\u0006 אם \u0003ב\u0004שוחט על מנת שיהא \u0003שובר עצמות הפסח ו\u0004על מנת \u0003לאכול ממנו נא,\u0004 הלוא גם אם עשה כן בפועל, \u0003זיבחא גופיה מי מיפסיל\u0004 \u0005[הזבח עצמו האם נפסל]\u0006 על ידי כך? הרי זריקת הדם היא המרצה ומכפרת!","וכן אם אמר \u0003על מנת\u0004 \u0003שיאכלוהו טמאים ושיקריבוהו טמאים, זיבחא גופיה מי מיפסיל\u0004 \u0005[הזבח עצמו האם נפסל]\u0006 במעשה הזה? וכן \u0003שיאכלוהו ערלים ושיקריבוהו ערלים,\u0004 \u0003זיבחא גופיה\u0004 \u0003מי מיפסיל\u0004 \u0005[הזבח עצמו האם הוא נפסל]\u0006 אם נעשה בו כן? \u0003לישנא אחרינא\u0004 \u0005[בלשון אחרת]\u0006 אפשר לומר: \u0003כל כמיניה\u0004 \u0005[וכי בכוחו]\u0006 לעשות את הדברים הללו התלויים בדעת אחרים?","וכן במה ששנינו שאם חשב \u0003לערב דמן בדם הפסולין\u0004 שהוא כשר, \u0003ר' יהודה\u0004 אינו חולק, כי הוא הולך \u0003לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר: אין דם מבטל דם,\u0004 ולכן גם אם היה מערב את הדם בפועל לא היה נפסל. וכן כשחשב \u0003ליתן את הניתנין למעלה למטה,\u0004 ואת אלה שניתנים \u0003למטה למעלה, ר'\u0004 \u0003יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר:\u0004 דם הניתן \u0003שלא למקומו\u0004 במזבח \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מקומו קרינא ביה\u0004 \u0005[אנו קוראים בו]\u0006 ונרצה הקרבן.","ושואלים: \u0003וליפלוג\u0004 \u0005[ושיחלוק]\u0006 \u0003בניתנין\u0004 \u0003בפנים שנתנן בחוץ, והניתנין בחוץ שנתנן בפנים\u0004 שהרי מפורש במקרא שחטאת שדמה ניתן בפנים נפסלה!","ומשיבים: במקרה זה \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה\u0004 כי לפסול את הקרבן במחשבת חוץ למקומו \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהא זה \u0003מקום שיהא משולש, ב\u0004זריקת ה\u0003דם ב\u0004אכילת ה\u0003בשר וב\u0004הקטרת ה\u0003אימורין\u0004 ששלושתם כשרים בו, והוא חוץ לעזרה, שהיה כשר לכך בזמן היתר הבמות. אבל מחשבה על זריקה בהיכל שאין בו שלושה אלה (שאין בו הקרבת בשר ואימורין) אינה פוסלת.","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו,\u0006 מקבל\u0005]\u0006 \u0003ר' יהודה האי סברא\u0004 \u0005[סברה זו]\u0006 של מקום משולש? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 נאמר בכתוב \"לא תזבח לה'... כל \u0003דבר רע\"\u0004 (דברים יז, א), \u0003ריבה כאן חטאת ששחטה בדרום\u0004 ולא בצפון העזרה, שהוא מקומה, \u0003ו\u0004כן \u0003חטאת שנכנס דמה לפנים\u0004 כלומר, ששחטה על מנת להכניס דמה להיכל, שהיא \u0003פסולה.\u0004 משמע שפוסלת מחשבה גם על מקום שאינו משולש!","וכלפי זה טוענים: \u0003ולית\u0004 \u0005[ו\u0006כי \u0005אין]\u0006 לו \u0003לר' יהודה\u0004 סברה זו של \u0003שלישי\u0004 (מקום משולש)? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003אמר ר' יהודה:\u0004 אם \u0003הכניס\u0004 דם חטאת חיצונה לפנים \u0003בשוגג\u0004 — \u0003כשר,\u0004 ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם הכניס \u0003במזיד\u0004 — \u0003פסול, וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 שפוסל ר' יהודה רק \u0003בשכיפר\u0004 בפועל, שזרק את הדם על המזבח הפנימי.","\u0003השתא\u0004 \u0005[מעתה],\u0006 \u0003ומה התם\u0004 \u0005[שם]\u0006 אפילו \u0003עיילי עיילא\u0004 \u0005[הכניס\u0006 את הדם\u0005]\u0006 בפועל, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כיפר\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 פסולה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא כיפר\u0004 — \u0003לא, הכא דחשיב חשובי\u0004 \u0005[כאן שהוא\u0006 רק \u0005חושב מחשבה]\u0006 להכניס פנימה, \u0003לא כל שכן\u0004 שלא יפסול? ומשיבים: \u0003תרי תנאי ואליבא\u0004 \u0005[שני תנאים\u0006 הם שנחלקו \u0005ועל פי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה,\u0004 בענין מקום משולש.","ושואלים עוד על הברייתא: \u0003וסבר ר' יהודה\u0004 ש\u0003חטאת ששחטה בדרום\u0004"],["\u0003יהא חייב?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: יכול חטאת ששחטה בדרום יהא חייב\u0004 עליה? \u0003תלמוד לומר: \"לא תזבח לה' אלהיך שור ושה\u0004 אשר יהיה בו מום \u0003כל דבר רע\"\u0004 (דברים יז, א), ללמדנו: \u0003על\u0004 שחיטת \u0003דבר רע,\u0004 כגון מום, \u0003אתה מחייבו\u0004 מלקות, \u0003ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחייבו על חטאת ששחטה בדרום!\u0004 ומשיבים: אף כאן \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים\u0006 חלוקים \u0005לפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יהודה.\u0004 \u0003אמר ר' אבא:\u0004 אף שאמר ר' יהודה שהזבח נפסל כששחטו על מנת להניח את הדם למחר, \u0003ומודה ר' יהודה,\u0004 שאם לאחר מכן קיבל את הדם, או הוליך או זרק, במחשבת חוץ לזמנו, \u0003שחוזר וקובעו לפיגול,\u0004 ואין מחשבת ההנחה למחר מפקיעה את הקרבן מדין פיגול, כמחשבת חוץ למקומו או מחשבת שלא לשמו בפסח וחטאת (ראה לעיל זבחים כט,ב).","","\u0003אמר רבא: תדע\u0004 שכן הוא, שהרי גם מחשבת \u0003פיגול\u0004 עצמה, שיש בה מחשבה להניח את הדם למחר כדי לזורקו, \u0003לפני זריקה לא כלום הוא,\u0004 שאם שחט על מנת לזרוק את הדם למחר עדיין אין הפיגול חל, \u0003ו\u0004רק כשזורק \u0003אתיא\u0004 \u0005[באה]\u0006 \u0003זריקה וקבעה לה\u0004 \u0005[וקובעת אותו]\u0006 \u0003בפיגול.\u0004 נמצא איפוא שמחשבת ההנחה למחר כשלעצמה אינה מפקיעה את הקרבן ממחשבת פיגול.","את ההוכחה של רבא דוחים: \u0003ולא היא\u0004 (ואינו כן), אין זו הוכחה, \u0003התם הוא חדא מחשבה היא\u0004 \u0005[שם,\u0006 במחשבת פיגול, \u0005מחשבה אחת היא]\u0006 שנקבעת בזריקה, \u0003הכא\u0004 \u0005[כאן]\u0006 כשמחשב מתחילה להניח את הדם למחר, ואחר כך לזורקו חוץ לזמנו — \u0003תרי\u0004 \u0005[שתי]\u0006 \u0003מחשבות\u0004 נבדלות הן, ונמצא שיש מחשבת פסול בקרבן זה, ושוב אינו יכול להיקבע בפיגול.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב הונא לר' אבא\u0004 ממה ששנינו בברייתא: אם שחט על מנת \u0003ליתן את הניתנין למעלה למטה,\u0004 ואת הניתנים \u0003למטה למעלה,\u0004 וחשב לעשות זאת \u0003לאלתר\u0004 (מיד, באותו יום) — הרי זה \u0003כשר,\u0004 שאין מחשבה זו פוסלת. ולפיכך, אם \u0003חזר וחישב\u0004 על אותו קרבן שיעשה אותו \u0003חוץ למקומו\u0004 — \u0003פסול ואין בו כרת,\u0004 ואם חשב עליו שיקריבנו \u0003חוץ לזמנו\u0004 — \u0003פיגול וחייבין עליו כרת.\u0004","אבל אם חישב ליתן את הניתנים למעלה למטה וכו' \u0003למחר\u0004 — \u0003פסול\u0004 משום מחשבת הינוח, וכדברי ר' יהודה, ובמקרה זה, אם \u0003חזר וחישב\u0004 בקרבן זה \u0003בין חוץ לזמנו בין חוץ למקומו\u0004 — \u0003פסול ואין בו כרת.\u0004 משמע, איפוא, שמחשבת הינוח מפקיעה מידי מחשבת פיגול. ונמצא שזו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003ר' אבא!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","\u0003אמר רב חסדא אמר רבינא בר סילא:\u0004 אם כששחט \u0003חישב שיאכלוהו טמאים\u0004 את בשר הקרבן \u0003למחר\u0004 — \u0003חייב\u0004 משום פיגול, ואין אומרים שכיוון שאין הבשר ראוי לאכילה על ידם — לא תהא זו מחשבה לאוכלו חוץ לזמנו. \u0003אמר רבא: תדע\u0004 שכן הוא, שהרי \u0003בשר לפני זריקה לא חזי\u0004 \u0005[אינו ראוי]\u0006 לאכילה, \u0003וכי\u0004 \u0005[וכאשר]\u0006 הוא \u0003מחשב ביה\u0004 \u0005[בו]\u0006 מחשבה פסולה הריהו \u0003מיפסיל\u0004 \u0005[נפסל],\u0006 הרי שמחשבת חוץ לזמנו על אכילת דבר שאסור באכילה עושה אותו פיגול.","ודוחים: \u0003ולא היא\u0004 (ואינו כן) אין זו הוכחה, כי \u0003התם זריק ומיחזי\u0004 \u0005[שם זורק\u0006 את הדם והבשר \u0005נעשה ראוי\u0006 לאכילה\u0005]\u0006 למחר, \u0003הכא לא מיחזי\u0004 \u0005[כאן אינו ראוי\u0006 לאכילה על ידי טמאים\u0005]\u0006 \u0003כלל,\u0004 ולכן אין זו מחשבת אכילה.","ו\u0003אמר רב חסדא, מרגלא בפומיה\u0004 \u0005[מורגלת\u0006 היתה \u0005בפיו]\u0006 של \u0003רב דימי בר חיננא\u0004 הלכה זו: \u0003בשר פסח שלא הוצלה\u0004 (נצלה), \u0003ולחמי תודה שלא הורמו\u0004 שלא הפריש מהם חלק לכהנים, למרות שאינם מותרים באכילה, מכל מקום \u0003חייבין עליהן משום\u0004 אכילה ב\u0003טומאה.\u0004","\u0003אמר רבא: תדע\u0004 שכן הוא, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"והנפש אשר תאכל בשר מזבח השלמים אשר לה' וטומאתו עליו ונכרתה\" וכו' (ויקרא ז, כ), והתוספת \u0003\"אשר לה'\"\u0004 באה \u0003לרבות אימורי קדשים קלים\u0004 (המוקטרים לה') \u0003ל\u0004דין \u0003טומאה,\u0004 שהאוכלם בטומאה חייב כרת. \u0003אלמא אף על גב דלאו בני אכילה נינהו\u0004 \u0005[הרי\u0006 ש\u0005אף על פי שאינם ראויים לאכילה]\u0006 — \u0003חייבין עליהן משום\u0004 אכילה ב\u0003טומאה, הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בבשר הפסח שלא נצלה ולחמי תודה שלא הורמו, \u0003אף על גב דלאו\u0004 \u0005[אף על פי שלא]\u0006 \u0003בני אכילה נינהו\u0004 \u0005[הם]\u0006 — \u0003חייבין עליהן משום טומאה.\u0004","","ודוחים: \u0003ולא היא\u0004 (ואינו כן) אין זו השוואה, \u0003התם\u0004 \u0005[שם]\u0006 \u0003אימורי קדשים קלים חזו\u0004 \u0005[ראויים]\u0006 על כל פנים \u0003לגבוה\u0004 לאכילת מזבח, ולכן חייבים על אכילתם בטומאה, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003בשר פסח שלא הוצלה ולחמי תודה שלא הורמו, דלא חזו\u0004 \u0005[שאינם ראויים]\u0006 \u0003לא לגבוה ולא להדיוט.\u0004","ומביאים \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 בה נאמרו הדברים, שכך הוכיחו: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אימורין לא חזו\u0004 \u0005[אינם ראויים]\u0006 וחייבים עליהם! ודוחים: \u0003ולא היא\u0004 (ואינו כן), \u0003הנך חזו למילתייהו\u0004 \u0005[אלה,\u0006 האימורים, \u0005ראויים לעניינם],\u0006 \u0003והני לא חזו\u0004 \u0005[ואלה,\u0006 בשר פסח שלא הוצלה ולחמי תודה שלא הורמו, \u0005אינם ראויים]\u0006 \u0003כלל.\u0004","","\u0003בית שמאי אומרים: כל\u0004 הדמים \u0003הניתנין על מזבח החיצון,\u0004 ואף קרבנות שצריך לתת את דמם בשתי זריקות (שתיים שהן ארבע), אם \u0003נתן במתנה אחת\u0004 בלבד — \u0003כיפר, ובחטאת,\u0004 שצריך ליתן את דמה על ארבע קרנות המזבח, רק אם נתן לפחות \u0003שתי מתנות. ובית הלל אומרים: אף חטאת שנתנה מתנה אחת\u0004 בלבד — \u0003כיפר\u0004 בדיעבד.","\u0003לפיכך,\u0004 מכיון שיוצא ידי חובה במתנה אחת (לבית הלל בכל הקרבנות, ולבית שמאי, בכולם חוץ מחטאת), \u0003אם נתן את הראשונה כתיקנה ואת השניה\u0004 במחשבה \u0003חוץ לזמנה\u0004 — \u0003כיפר,\u0004 שכיוון שהמתנה השניה אינה מעכבת את העבודה אין מחשבה שחשב בה פוסלת. \u0003ו\u0004מאותה סיבה עצמה \u0003אם נתן את הראשונה\u0004 במחשבה \u0003חוץ לזמנה ואת השניה\u0004 במחשבה \u0003חוץ למקומה\u0004 — הרי \u0003זה\u0004 \u0003פיגול וחייבין עליו כרת,\u0004 כי מה שחשב מחשבת חוץ למקומו שוב אינו מפקיע את הפיגול. וכל זה במזבח החיצון.","","אבל \u0003כל הניתנין על המזבח הפנימי\u0004 דינם \u0003שאם חיסר אחת מן המתנות\u0004 — \u0003כאילו לא כיפר. לפיכך,\u0004 אם \u0003נתן\u0004 את המתנות \u0003כולן כתיקנן ואחת\u0004 נתן \u0003שלא כתיקנה\u0004 (במחשבת חוץ לזמנו) — הרי אותה חטאת \u0003פסולה,\u0004 שהרי היא חסרה מתנה אחת. \u0003ו\u0004אולם מצד אחר, הואיל וחשב מחשבת פיגול רק בחלק מן הדם המתיר את הקרבת הקרבן — \u0003אין בו\u0004 בקרבן זה \u0003כרת,\u0004 שאין פיגול אלא אם פיגל בכל המתיר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין לניתנין על מזבח החיצון שנתנן במתנה אחת שכיפר\u0004 בדיעבד? \u0003תלמוד לומר: \"ודם זבחיך ישפך\"\u0004 (דברים יב, כז), לומר שדי להם בשפיכה אחת. ושואלים: \u0003והאי להכי\u0004 \u0005[וזה\u0006 האם \u0005לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 \u0003האי מיבעי ליה לכדתניא\u0004 \u0005[זה הרי נצרך לו לכמו ששנויה\u0006 בברייתא\u0005]\u0006 לענין אחר:"],["\u0003מנין לכל הדמים\u0004 של כל הקרבנות \u0003ש\u0004הם \u0003טעונים מתן דם ליסוד? תלמוד לומר: \"ודם\u0004 \u0003זבחיך ישפך\"\u0004 (דברים יב, כז)! ומשיבים: לתנא של הברייתא הראשונה דבר זה \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד\u0005]\u0006 \u0003מ\u0004אותו פסוק שלומד ממנו \u0003רבי. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר לגבי חטאת העוף \u0003\"והנשאר בדם ימצה\u0004 אל יסוד המזבח\" (ויקרא ה, ט), \u0003שאין תלמוד\u0004 (צורך) \u0003לומר \"בדם\",\u0004 שהרי מדובר בפסוק זה על הדם, \u0003ומה תלמוד לומר\u0004 לשם מה נאמר \u0003\"בדם\"?\u0004","\u0003לפי שלא למדנו אלא לניתנין מתן ארבע\u0004 כלומר, חטאות חיצונות, \u0003שטעונין מתן דמים ליסוד\u0004 כמפורש בהם (ויקרא ד, כה ועוד), \u0003שאר דמים\u0004 של שאר קרבנות \u0003מנין? תלמוד לומר: \"והנשאר בדם ימצה\". שאין תלמוד\u0004 (צורך) \u0003לומר \"בדם\", ומה תלמוד לומר \"בדם\"?\u0004 \u0003לימד על כל הדמים שטעונין מתן דמים ליסוד.\u0004","ושואלים: \u0003ואכתי להכי\u0004 \u0005[ועדיין לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 פסוק זה \"ודם זבחיך ישפך\", ללמד שנתינה אחת כשירה? הלוא \u0003מיבעי\u0004 \u0003ליה לכדתניא\u0004 \u0005[נצרך לו לכמו ששנויה\u0006 בברייתא\u0005]\u0006 אחרת: \u0003מנין ל\u0004דמים ש\u0003ניתנין בזריקה\u0004 על קיר המזבח \u0003ש\u0004אם \u0003נתנן בשפיכה\u0004 ולא בדרך זריקה \u0003יצא? תלמוד לומר: \"ודם\u0004 \u0003זבחיך ישפך\"!\u0004 ומשיבים: כך לומד ר' ישמעאל, שסבור כן.","אבל התנא של הברייתא \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' עקיבא,\u0004 ש\u0003אמר: לא זריקה בכלל שפיכה ולא שפיכה בכלל זריקה,\u0004 וכל אחד הוא דין לעצמו, ואין יוצא ידי חובת זריקה על ידי שפיכה. והיכן שמענו שכך היא דעתו?","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 בענין הברכה שלפני אכילת הקרבן: \u0003ברך ברכת הפסח\u0004 — \u0003פטר\u0004 בברכתו \u0003את\u0004 הברכה \u0003של זבח\u0004 (השלמים הנאכלים עם הפסח), אבל אם ברך ברכה","\u0003של זבח\u0004 — \u0003לא פטר את הפסח, דברי ר' ישמעאל.\u0004 שדם הפסח ניתן בשפיכה, ודם הזבח בזריקה. והואיל ולדעתו זריקה בכלל שפיכה, ואם שפך את הטעון זריקה יצא ידי חובתו, לפיכך ברכת הפסח כוללת גם את הזבח, אבל לא להיפך.","\u0003ר' עקיבא אומר:\u0004 \u0003לא זו פוטרת זו, ולא זו פוטרת זו,\u0004 שאין זריקה בכלל שפיכה.","ושואלים: \u0003אכתי להכי\u0004 \u0005[עדיין לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 פסוק זה, ללמד שמתנת דם אחת על המזבח כשירה? \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003ר' ישמעאל אומר:\u0004 \u0003מתוך שנאמר\u0004 בכתוב \u0003\"אך בכור שור או בכור\u0004 \u0003כשב או בכור עז\u0004... את דמם תזרוק על המזבח ואת חלבם תקטיר\" (במדבר יח, יז), \u0003למדנו\u0004 מכאן \u0003לבכור שטעון מתן דמים ואימורים\u0004 \u0003לגבי מזבח. מעשר ופסח מנין\u0004 שהם טעונים דברים אלה? \u0003תלמוד לומר: \"ודם זבחיך ישפך\",\u0004 לומר שכל דבר שהוא זבח צריך לשפוך את דמו על המזבח!","ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי הגלילי\u0004 שלמד דין זה במעשר ופסח ממה שנאמר בבכור \"את דמם תזרוק על המזבח ואת חלבם תקטיר\" (במדבר יח, יז).","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר'\u0004 \u0003יוסי הגלילי אומר:\u0004 \u0003\"דמו\" לא נאמר אלא \"דמם\", \"חלבו\" לא נאמר\u0004 \u0003אלא \"חלבם\", לימד\u0004 על ידי לשון רבים זו לא רק \u0003על בכור,\u0004 אלא גם על \u0003מעשר ופסח שטעון מתן דמים ואימורין לגבי מזבח.\u0004","ושואלים: \u0003ור' ישמעאל,\u0004 הרי לשיטתו למדנו מ\"ודם זבחיך ישפך\" שזריקה בכלל שפיכה, וכאן הוא למד מפסוק זה שדינו של פסח בשפיכה, \u0003האי קרא\u0004 \u0005[פסוק זה]\u0006 \u0003מפיק ליה להכי ומפיק ליה להכי\u0004 \u0005[מוציא אותו ל\u0006דבר \u0005זה ומוציא אותו ל\u0006דבר \u0005אחר]?\u0006 ומשיבים: \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים\u0006 נחלקו \u0005בכך לפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' ישמעאל.\u0004","ועוד שואלים על המחלוקת בדרשת הכתוב \"אך בכור\": \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' ישמעאל דמוקים לה כוליה\u0004 \u0005[שמעמיד אותו\u0006 את הפסוק \u0005כולו]\u0006 \u0003בבכור,\u0004 ובפסוק זה מוזכרים שלושה סוגי בכורות — בכור שור, בכור כשב ובכור עז — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 מיד אחר כך: \u0003\"ובשרם יהיה לך\"\u0004 (במדבר יח, יח), שבשר הבכורות ניתן לאהרן ולבניו.","\u0003אלא ל\u0004דעת \u0003ר' יוסי\u0004 הגלילי, \u0003דמוקי ליה נמי\u0004 \u0005[שמעמיד אותו גם כן]\u0006 \u0003ב\u0004קרבן \u0003מעשר ופסח,\u0004 והלוא \u0003מעשר ופסח בעלים אכלי ליה\u0004 \u0005[אוכלים אותו]\u0006 ולא הכהנים, ואם כן \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ובשרם יהיה לך\"?\u0004 ומשיבים: לשון רבים האמורה בענין זה אינה מתייחסת למעשר ולפסח, אלא לבכורות, והכוונה היא — \u0003אחד\u0004 שור \u0003תם\u0004 (תמים, שדמו נזרק) \u0003ואחד\u0004 שור \u0003בעל מום,\u0004"],["\u0003לימד\u0004 פסוק זה \u0003על בכור בעל מום שניתן לכהן\u0004 במתנה, והוא אוכל את בשרו. \u0003שלא מצינו\u0004 דין דומה \u0003לו בכל התורה כולה,\u0004 שקרבן בעל מום ניתן לכהנים לאכילה.","ושואלים: \u0003ור' ישמעאל\u0004 שדורש אחרת, מנין לו הלכה זו בבכור בעל מום? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצאת לו]\u0006 הלכה זו \u0003מ\u0004מה שנאמר: \"כחזה התנופה וכשוק הימין \u0003לך יהיה\" דסיפא\u0004 \u0005[שבסוף]\u0006 פסוק זה (במדבר יח, יח).","ושואלים מצד אחר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' יוסי הגלילי דמוקי ליה נמי\u0004 \u0005[שמעמיד אותו\u0006 פסוק \u0005גם כן]\u0006 \u0003במעשר ופסח, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 שם: \u0003\"לא תפדה כי קדש הם\"\u0004 (במדבר יח, יז), וההדגשה \"הם\" באה לומר ש\u0003הם קריבין ואין תמורתן קריבה,\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003תמורת בכור ומעשר,\u0004 גם \u0003הן\u0004 התמורות עצמן, \u0003ו\u0004גם \u0003ולדן וולד ולדן עד סוף כל העולם\u0004 (כמה וכמה דורות) \u0003הרי הן כבכור ומעשר, ויאכלו במומן לבעלים,\u0004 אבל אינם קרבים למזבח.","\u0003ו\u0004כן לענין תמורת הפסח \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003אמר ר' יהושע: שמעתי שתמורת פסח קריבה ותמורת פסח אינה קריבה, ואין לי לפרש\u0004 את הדברים ששמעתי. וכמבואר להלן, תמורת הפסח עצמה אינה קרבה.","\u0003אלא לר' ישמעאל דמוקי ליה כוליה\u0004 \u0005[שמעמיד אותו\u0006 את הפסוק \u0005כולו]\u0006 \u0003בבכור, מעשר ופסח דלא\u0004 \u0005[שאין]\u0006 \u0003קריבה תמורתן מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: לענין \u0003מעשר גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"עברה\" \"עברה\" מבכור,\u0004 שנאמר בבכור: \"והעברת כל פטר רחם לה'\" וכו' (שמות יג, יב), ונאמר במעשר: \"כל אשר יעבור תחת השבט\" (ויקרא כז, לב),","\u0003פסח\u0004 — \u0003בהדיא כתב ביה\u0004 \u0005[במפורש כתוב בו]\u0006 כלומר, אין זה בגזירה שווה, אלא יש כתוב מיותר לענין זה, שנאמר בדין השלמים: \"ואם מן הצאן קרבנו... אם כשב הוא מקריב\" (ויקרא ג, ו— ז), ודי היה במלה \u0003\"כשב\",\u0004 \u0003מה תלמוד לומר \"אם כשב\"\u0004 (ויקרא ג, ו— ז)? הרי \"אם\" זה בא \u0003לרבות תמורת הפסח\u0004 כשהמיר בבהמה \u0003אחר הפסח, שתקרב שלמים\u0004 כדין תמורת שלמים, כיון שהפסח עצמו אחר חג הפסח נעשה קרבן שלמים. \u0003יכול אף\u0004 תמורת הפסח \u0003לפני הפסח\u0004 יהא דינה \u0003כן? תלמוד לומר: \"הוא\"\u0004 למעט, שתמורה זו אינה קרבה.","ולסיכום הדיון שואלים: \u0003וכל הנך תנאי דמפקי ליה להאי\u0004 \u0005[וכל אותם התנאים שמוציאים את זה]\u0006 הכתוב \u0003\"דם זבחיך ישפך\"\u0004 (דברים יב, כז) \u0003לדרשא אחרינא\u0004 \u0005[לדרשה אחרת],\u0006 \u0003האי\u0004 \u0005[\u0006ההלכה \u0005הזו]\u0006 ש\u0003כל הניתנין על מזבח החיצון שנתנן מתנה אחת שכיפר מנא להו\u0004 \u0005[מנין להם]?\u0006 ומשיבים: \u0003סברי להו\u0004 \u0005[סבורים הם]\u0006 \u0003כ\u0004דעת \u0003בית הלל, דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003אף חטאת שנתנה מתנה אחת כיפר, וילפינן כולהו\u0004 \u0005[ולמדים\u0006 הם את כל הקרבנות \u0005כולם]\u0006 \u0003מחטאת.\u0004","שנינו במשנה: \u0003ו\u0004אם נתן מן \u0003החטאת שתי מתנות\u0004 — כיפר לדעת בית שמאי. ולדעת בית הלל, אף חטאת שנתנה מתנה אחת כיפר. \u0003אמר רב הונא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי?\u0004","נאמר בדין נתינת דם החטאת על המזבח: \u0003\"קרנות\"\u0004 (ויקרא ד, כה) \u0003\"קרנות\"\u0004 (ויקרא ד, ל) \u0003\"קרנות\"\u0004 (ויקרא ד, לד) וכל אחד הוא לשון רבים — \u0003הרי כאן שש, ארבעה\u0004 מהם \u0003למצוה\u0004 שצריך לכתחילה לתת הדם על ארבע קרנות המזבח, \u0003ושתים\u0004 שנשארו הרי הם \u0003לעכב,\u0004 שאם לא נתן לפחות שתי מתנות על הקרנות — לא כיפר.","ושואלים: \u0003ובית הלל\u0004 מה הם סבורים? ומסבירים: לדעתם הולכים אחר מסורת הכתיבה, ומכיון ש\"קרנות\" כתוב פעמיים חסר, נמצא כי \u0003\"קרנת\" \"קרנת\" \"קרנות\"\u0004 — \u0003הרי כאן ארבע, שלש למצוה\u0004 לכתחילה, ו\u0003אחת\u0004 היא גם \u0003לעכב,\u0004 שאם לא נתן אפילו על אחת — לא התכפר.","ושואלים: \u0003ואימא כולהו\u0004 \u0005[ואמור\u0006 ש\u0005כולם]\u0006 \u0003למצוה\u0004 כלומר ארבע קרנות לכתחילה, ובדיעבד יתכפר גם בלא זה! ומשיבים: \u0003כפרה בכדי\u0004 \u0005[בחינם]\u0006 בלי זריקת דם כלל \u0003לא אשכחן\u0004 \u0005[מצאנו].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003בית הלל: אהני\u0004 \u0005[הועיל]\u0006 ה\u0003מקרא\u0004 הדרך שקוראים בה את המלה, שהיא לשון רבים, \u0003ואהני\u0004 \u0005[והועילה]\u0006 ה\u0003מסורת\u0004 של הכתיבה, שהיא לשון יחיד, ובאופן זה: \u0003אהני\u0004 \u0005[הועיל]\u0006 ה\u0003מקרא לטפויי חדא\u0004 \u0005[להוסיף\u0006 עוד קרן \u0005אחת],\u0006 \u0003ואהני\u0004 \u0005[והועילה]\u0006 \u0003מסורת לבצורי חדא\u0004 \u0005[להוריד אחת],\u0006 ואם כן נמצא שכאילו כתוב שם חמש, ארבע למצוה ואחת לעכב.","ושואלים: \u0003אלא מעתה\u0004 לפי דרך זו של דרשת המקראות, מה שנאמר בתפילין של ראש \u0003\"לטטפת\" \"לטטפת\" \"לטוטפות\"\u0004 — \u0003הרי כאן ארבע,\u0004 ומכאן למדים שיש ארבעה בתים בתפילין של ראש, מדוע לא נאמר גם כאן באותה שיטה: \u0003אהני קרא ואהני מסורת\u0004 \u0005[הועיל מקרא והועילה המסורת],\u0006 ואם כן \u0003חמשה בתי\u0004 \u0005[בתים]\u0006 \u0003בעי למיעבד\u0004 \u0005[צריך לעשות]!\u0006","ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 שאין אנו למדים דין זה ממספר הפעמים שהוזכר \"טוטפות\", אלא מדרשת המילה \"טטפת\", כי \u0003טט ב\u0004לשון \u0003כתפי\u0004 פירושו \u0003שתים, פת ב\u0004לשון \u0003אפריקי\u0004 פירושו \u0003שתים.\u0004","ועוד שואלים על שיטת מדרש זו: \u0003אלא מעתה,\u0004 נאמר \u0003\"בסכת\" \"בסכת\" \"בסוכות\",\u0004 שלפי המסורת נאמרה פעמיים לשון יחיד (\"סכת\"), ופעם אחת לשון רבים (\"סוכות\"), ולמדו מכאן שצריך ארבע דפנות לסוכה, מדוע לא נאמר גם פה לפי אותה שיטה: \u0003אהני\u0004 \u0005[הועיל]\u0006 ה\u0003מקרא\u0004 בלשון רבים ללמד על שש דפנות, \u0003ואהני\u0004 \u0005[והועילה]\u0006 ה\u0003מסורת\u0004 ללמד על ארבע דפנות, אם כן \u0003חמשא דפנתא בעי למיעבד\u0004 \u0005[חמש דפנות צריך לעשות]!\u0006"]]};
